"use client";

import { createContext, useContext, type ReactNode } from "react";

/** Which native Messages app to replicate. Sizes, spacing, and chrome all key off this. */
export type Platform = "ios" | "macos";

const PlatformContext = createContext<Platform>("ios");

export function PlatformProvider({ platform, children }: { platform: Platform; children: ReactNode }) {
  return <PlatformContext.Provider value={platform}>{children}</PlatformContext.Provider>;
}

export function usePlatform(): Platform {
  return useContext(PlatformContext);
}

import type { Platform } from "@/components/imessage/platform";

/**
 * Measured design tokens (see references/SPEC.md). Points equal CSS px.
 * Colors that vary with vertical screen position are expressed as top/bottom pairs of a
 * screen-space linear gradient; `screenHeight` is the reference height they were measured on.
 */
export type Service = "imessage" | "sms";
export type Direction = "incoming" | "outgoing";

export type BubbleMetrics = {
  fontSize: number;
  lineHeight: number;
  paddingX: number;
  paddingY: number;
  radius: number;
  minWidth: number;
  /** Widest bubble in px (iOS uses a fixed width at 402pt screens). */
  maxWidth: number;
  /** Fraction of the message pane width a bubble may occupy (macOS). */
  maxWidthRatio: number;
  /** Scale applied to the traced iOS tail (1 on iOS, 0.7 on macOS). */
  tailScale: number;
  /** Gap between consecutive bubbles of the same group, and between groups. */
  gapInGroup: number;
  gapBetweenGroups: number;
  /** Inset from the pane edge on the bubble's own side. */
  edgeInset: number;
  /** Whether every bubble gets a tail. Both platforms only tail the last bubble of a cluster. */
  tailOnEveryBubble: boolean;
  /** Status label ("Delivered") typography and offsets. Always semibold. */
  statusFontSize: number;
  statusLineHeight: number;
  statusLetterSpacing: number;
  statusGap: number;
  statusInset: number;
  /** Large glyph size, line box, and edge inset for emoji-only messages. */
  emojiOnlySize: number;
  emojiOnlyLineHeight: number;
  emojiOnlyInset: number;
  /** Tracking applied to bubble text so the web's SF matches native widths. */
  letterSpacing: number;
};

export const bubbleMetrics: Record<Platform, BubbleMetrics> = {
  ios: {
    fontSize: 17,
    lineHeight: 20,
    paddingX: 13.85,
    paddingY: 10,
    radius: 19,
    minWidth: 48,
    maxWidth: 280.5,
    /** Unverified: 0.17 under `maxWidth`. `message-list` uses the ratio on iOS too, so a bubble is
     * 280.33 wide in a list and 280.5 standalone. The widest body in `conv3-light.png` measures 280.67. */
    maxWidthRatio: 280.33 / 402,
    tailScale: 1,
    gapInGroup: 4.3333,
    // 10.33 cannot reproduce the 50.000 pt step native puts between the third "V" and the long
    // bubble: solving all seven row origins at once pins this to 10.168-10.25.
    gapBetweenGroups: 10.2,
    edgeInset: 16,
    tailOnEveryBubble: false,
    statusFontSize: 11,
    statusLineHeight: 13,
    statusLetterSpacing: -0.25,
    statusGap: 4.65,
    statusInset: 20.3,
    /** Unverified: no iOS capture holds an emoji-only message. Scaled from the measured macOS 72/87.3. */
    emojiOnlySize: 58,
    emojiOnlyLineHeight: 70,
    emojiOnlyInset: 4,
    letterSpacing: 0,
  },
  macos: {
    fontSize: 13,
    lineHeight: 14.7,
    paddingX: 12.5,
    paddingY: 7.03,
    // 14.5, not 14. An arc anchored to the four-line bubble's own measured straight edges (left
    // 227.477, top 493.976 in conversation-pane-light.png) fits 25 sub-pixel rows of the top
    // corners at 0.119 rmse; r = 14 fits at 0.194 with all 25 residuals on the same side. The same
    // routine run against our own 14.5 render returns 14.42, so native's 14.39 reads as 14.46 once
    // that bias is removed. What is left at 14.5 is a symmetric S of +-0.15, twice our own render's,
    // which is the shape difference of a slightly continuous corner, not a radius error.
    radius: 14.5,
    minWidth: 40,
    maxWidth: 382.5,
    maxWidthRatio: 0.6068,
    tailScale: 0.7,
    // Native lands every row's top on the device grid (0.5 at 2x), so a single gap reads anywhere
    // from 2.75 to 3.25. The run of six one-line bubbles in conversation-pane-dark.png settles it:
    // tops 379.5 / 411.5 / 443.0 / 475.0 / 506.5 / 538.5, a mean pitch of 31.7997 over five gaps
    // against a body height of 28.7545, so the gap is 3.045 +- 0.1. Do not re-derive it from one
    // pair of bubbles in a pane capture; those read 3.24 or 2.75 depending on the phase.
    gapInGroup: 3,
    gapBetweenGroups: 11.5,
    edgeInset: 20,
    tailOnEveryBubble: false,
    statusFontSize: 9,
    statusLineHeight: 11,
    statusLetterSpacing: 0,
    statusGap: 4,
    statusInset: 15.9,
    emojiOnlySize: 72,
    emojiOnlyLineHeight: 87.3,
    emojiOnlyInset: 4,
    letterSpacing: -0.4,
  },
};

export type ScreenGradient = { top: string; bottom: string; screenHeight: number };

export type Palette = {
  background: string;
  /** Outgoing iMessage blue, screen-space gradient. */
  imessage: ScreenGradient;
  /** Outgoing SMS green, screen-space gradient. */
  sms: ScreenGradient;
  /** Incoming gray, screen-space gradient (nearly flat). */
  incoming: ScreenGradient;
  incomingText: string;
  outgoingText: string;
  secondaryLabel: string;
  edited: string;
  /** Tapback balloon fills. */
  tapbackMine: string;
  tapbackTheirs: string;
  separator: string;
};

/**
 * iOS 26 measured: SMS green from the simulator. The blue and gray gradients are taken from macOS 26,
 * which shares Messages' palette; they are marked as such in SPEC.md until an iOS capture confirms them.
 *
 * Not measured, and not in SPEC.md either: `macos.*.sms` (no macOS capture holds a green bubble; the
 * only green in any of them is the plus-menu app icons), `macos.light.edited`, and both `ios.*.separator`
 * values. Treat them as placeholders, not as measurements.
 */
export const palettes: Record<Platform, { light: Palette; dark: Palette }> = {
  ios: {
    light: {
      background: "#ffffff",
      imessage: { top: "#77c7f5", bottom: "#3682f7", screenHeight: 874 },
      sms: { top: "#53e678", bottom: "#31c355", screenHeight: 874 },
      incoming: { top: "#e9e9eb", bottom: "#e9e9eb", screenHeight: 874 },
      incomingText: "#000000",
      outgoingText: "#ffffff",
      secondaryLabel: "#8a8a8e",
      edited: "#3f8ff7",
      tapbackMine: "#0088ff",
      tapbackTheirs: "#e9e9eb",
      separator: "#c6c6c8",
    },
    dark: {
      background: "#000000",
      imessage: { top: "#589af7", bottom: "#3d8ef7", screenHeight: 874 },
      sms: { top: "#53e678", bottom: "#31c355", screenHeight: 874 },
      incoming: { top: "#262629", bottom: "#262629", screenHeight: 874 },
      incomingText: "#ffffff",
      outgoingText: "#ffffff",
      secondaryLabel: "#8d8d93",
      edited: "#3f8ff7",
      tapbackMine: "#0088ff",
      tapbackTheirs: "#262629",
      separator: "#38383a",
    },
  },
  macos: {
    light: {
      background: "#ffffff",
      imessage: { top: "#77c7f5", bottom: "#3682f7", screenHeight: 640 },
      sms: { top: "#5fe083", bottom: "#35c65b", screenHeight: 640 },
      incoming: { top: "#e9e9eb", bottom: "#e9e9eb", screenHeight: 640 },
      incomingText: "#000000",
      outgoingText: "#ffffff",
      secondaryLabel: "#808080",
      edited: "#1f7cf5",
      tapbackMine: "#5498f8",
      tapbackTheirs: "#e9e9eb",
      separator: "#e1e1e1",
    },
    dark: {
      background: "#1e1e1e",
      imessage: { top: "#589af7", bottom: "#3d8ef7", screenHeight: 640 },
      sms: { top: "#4fd772", bottom: "#33bf56", screenHeight: 640 },
      incoming: { top: "#38383a", bottom: "#3c3c3e", screenHeight: 640 },
      incomingText: "#ffffff",
      outgoingText: "#ffffff",
      secondaryLabel: "#9a9a9a",
      edited: "#3f8ff7",
      tapbackMine: "#5498f8",
      tapbackTheirs: "#3b3b3d",
      separator: "#3a3a3a",
    },
  },
};

/** CSS custom properties that carry a palette, so components stay theme-aware through `.dark`. */
export function paletteVars(p: Palette): Record<string, string> {
  return {
    "--im-bg": p.background,
    "--im-blue-top": p.imessage.top,
    "--im-blue-bottom": p.imessage.bottom,
    "--im-green-top": p.sms.top,
    "--im-green-bottom": p.sms.bottom,
    "--im-gray-top": p.incoming.top,
    "--im-gray-bottom": p.incoming.bottom,
    "--im-incoming-text": p.incomingText,
    "--im-outgoing-text": p.outgoingText,
    "--im-secondary": p.secondaryLabel,
    "--im-edited": p.edited,
    "--im-tapback-mine": p.tapbackMine,
    "--im-tapback-theirs": p.tapbackTheirs,
    "--im-separator": p.separator,
    "--im-screen-h": `${p.imessage.screenHeight}px`,
  };
}

/** System font stacks. `-apple-system` resolves to SF Pro on Apple platforms, which is what native renders. */
export const fontStack = '-apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro", "Helvetica Neue", Helvetica, Arial, sans-serif';
export const emojiFontStack = '"Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", sans-serif';

/**
 * Native iMessage bubble geometry, traced from iOS 26 Messages (see references/SPEC.md and
 * references/ios/bubble-tail-beziers.json). All values are points (CSS px).
 *
 * The bubble body is a rounded rectangle with circular corners. On the sender's side the bottom
 * corner is replaced by the tail: the edge sweeps inward over the last ~19pt of height into a
 * neck, bulges back out, and ends in a point that hangs ~6.8pt below the body. The tail region is
 * a fixed 22×28pt box anchored at the body's bottom corner, so it never scales with the bubble.
 */
export type TailSide = "left" | "right" | "none";

/** Cubic Béziers relative to the body's bottom-right corner (x grows right, y grows down). */
const TAIL_SEGMENTS: Array<[number, number, number, number, number, number]> = [
  // S-curve from the straight right edge down to the neck
  [-0.442, -13.682, -3.003, -8.238, -7.457, -4.87],
  [-9.101, -3.553, -10.598, -1.75, -10.513, 0.463],
  // bulge from the neck down to the tip
  [-10.766, 2.71, -8.409, 4.088, -8.319, 6.13],
  // rounded tip
  [-8.33, 6.55, -8.6, 6.75, -9.0, 6.698],
  // underside from the tip back to the body's bottom edge
  [-14.001, 6.333, -17.413, 1.539, -22.0, 0],
];
const TAIL_START_Y = -19.203; // where the straight edge ends, relative to the body bottom
const TAIL_EDGE_START = -21.2; // clip box top: a little above so the arc/straight edge is untouched

export const tailBox = { width: 22, height: 21.2, hang: 6.8 } as const;

function fmt(n: number) {
  return Number(n.toFixed(3)).toString();
}

/**
 * SVG path for the fixed tail region. The path is in a `tailBox.width × (tailBox.height + tailBox.hang)`
 * coordinate system whose top-left is (bodyRight − 22, bodyBottom − 21.2). For a left tail it is mirrored.
 */
export function tailPath(side: Exclude<TailSide, "none">, scale = 1): string {
  const w = tailBox.width * scale;
  const h = tailBox.height * scale;
  const mx = (x: number) => (side === "right" ? w + x * scale : -x * scale);
  const my = (y: number) => h + y * scale;
  const parts = [`M${fmt(mx(-22))},${fmt(my(TAIL_EDGE_START))}`, `L${fmt(mx(0))},${fmt(my(TAIL_EDGE_START))}`, `L${fmt(mx(0))},${fmt(my(TAIL_START_Y))}`];
  for (const [x1, y1, x2, y2, x, y] of TAIL_SEGMENTS) {
    parts.push(`C${fmt(mx(x1))},${fmt(my(y1))} ${fmt(mx(x2))},${fmt(my(y2))} ${fmt(mx(x))},${fmt(my(y))}`);
  }
  parts.push("Z");
  return parts.join(" ");
}

/**
 * How far the body's clip has to reach into the tail box so the two do not leave a hairline where
 * they meet. Both platforms need it, and the reason is Chrome, not the geometry: a `clip-path`
 * reference box is snapped to whole CSS px before it rasterises, and the body's box and the tail's
 * box snap independently. Their shared edge then lands on two different device rows and the
 * background shows through the row between them - a white line running out of the tail across the
 * bubble, which is exactly what it looks like.
 *
 * 0.75 was measured, not guessed: `scripts/measure/hairline.ts` over `/lab?scene=ios-conv3` at
 * twelve sub-pixel offsets of the message column still finds the seam at 0.25 and never finds it
 * from 0.5 up, so 0.75 keeps a quarter point of margin. The ceiling is the tail's own straight top
 * segment, `(tailBox.height - 19.203) * scale` = 1.997 on iOS and 1.398 on macOS; past that the
 * body would paint outside the tail's outline.
 */
export const tailSeamOverlap: Record<"ios" | "macos", number> = { ios: 0.75, macos: 0.75 };

/**
 * clip-path polygon that removes the tail box from a plain rounded-rectangle body so the tail SVG
 * can draw that region exactly. Use with `border-radius` for the three untouched corners.
 *
 * `overlap` shrinks the removed box along its two interior edges, so the body keeps painting that
 * far *into* the tail box and covers the seam described on `tailSeamOverlap`. Both edges are
 * interior to the tail's own outline, so the body can only become visible there if it reaches past
 * the tail's straight top segment.
 */
export function bodyClipPath(side: Exclude<TailSide, "none">, scale = 1, overlap = 0): string {
  const w = tailBox.width * scale - overlap;
  const h = tailBox.height * scale - overlap;
  return side === "right"
    ? `polygon(0 0, 100% 0, 100% calc(100% - ${fmt(h)}px), calc(100% - ${fmt(w)}px) calc(100% - ${fmt(h)}px), calc(100% - ${fmt(w)}px) 100%, 0 100%)`
    : `polygon(0 0, 100% 0, 100% 100%, ${fmt(w)}px 100%, ${fmt(w)}px calc(100% - ${fmt(h)}px), 0 calc(100% - ${fmt(h)}px))`;
}

/** Full bubble outline as an SVG path (for masks, effects, and tests). */
export function bubblePath(width: number, height: number, side: TailSide, radius = 19, scale = 1): string {
  const r = Math.min(radius, height / 2, width / 2);
  if (side === "none") {
    return `M${fmt(r)},0 H${fmt(width - r)} A${fmt(r)},${fmt(r)} 0 0 1 ${fmt(width)},${fmt(r)} V${fmt(height - r)} A${fmt(r)},${fmt(r)} 0 0 1 ${fmt(width - r)},${fmt(height)} H${fmt(r)} A${fmt(r)},${fmt(r)} 0 0 1 0,${fmt(height - r)} V${fmt(r)} A${fmt(r)},${fmt(r)} 0 0 1 ${fmt(r)},0 Z`;
  }
  const mx = (x: number) => (side === "right" ? width + x * scale : -x * scale);
  const my = (y: number) => height + y * scale;
  const tail: string[] = [`L${fmt(mx(0))},${fmt(my(TAIL_START_Y))}`];
  for (const [x1, y1, x2, y2, x, y] of TAIL_SEGMENTS) tail.push(`C${fmt(mx(x1))},${fmt(my(y1))} ${fmt(mx(x2))},${fmt(my(y2))} ${fmt(mx(x))},${fmt(my(y))}`);
  if (side === "right") {
    return `M${fmt(r)},0 H${fmt(width - r)} A${fmt(r)},${fmt(r)} 0 0 1 ${fmt(width)},${fmt(r)} ${tail.join(" ")} H${fmt(r)} A${fmt(r)},${fmt(r)} 0 0 1 0,${fmt(height - r)} V${fmt(r)} A${fmt(r)},${fmt(r)} 0 0 1 ${fmt(r)},0 Z`;
  }
  // left tail: walk the outline counter-clockwise so the mirrored tail segments read in order
  return `M${fmt(width - r)},0 H${fmt(r)} A${fmt(r)},${fmt(r)} 0 0 0 0,${fmt(r)} ${tail.join(" ")} H${fmt(width - r)} A${fmt(r)},${fmt(r)} 0 0 0 ${fmt(width)},${fmt(height - r)} V${fmt(r)} A${fmt(r)},${fmt(r)} 0 0 0 ${fmt(width - r)},0 Z`;
}

"use client";

import { useEffect, type RefObject } from "react";

/**
 * Native bubbles are filled with one gradient fixed to the screen, so a bubble's color depends on
 * where it currently sits. This keeps every `[data-slot="message-bubble"]` and every
 * `[data-slot="typing-indicator"]` inside `container` in sync
 * by writing `--bubble-bottom` (the body's bottom edge relative to the screen frame) on scroll and
 * resize. It touches the DOM directly, so scrolling never re-renders React.
 *
 * `frame` is the element that represents the device screen (defaults to the container).
 */
export function useBubbleScreenSpace(container: RefObject<HTMLElement | null>, frame?: RefObject<HTMLElement | null>) {
  useEffect(() => {
    const root = container.current;
    if (!root) return;
    let raf = 0;
    const update = () => {
      raf = 0;
      const screen = (frame?.current ?? root).getBoundingClientRect();
      // The typing indicator is an incoming bubble too, so it needs the same screen-space fill.
      root.querySelectorAll<HTMLElement>('[data-slot="message-bubble"], [data-slot="typing-indicator"]').forEach(bubble => {
        // The typing indicator is its own body; a message bubble keeps its body in a child.
        const body = bubble.querySelector<HTMLElement>('[data-slot="bubble"], [data-slot="emoji"]') ?? (bubble.dataset.slot === "typing-indicator" ? bubble : null);
        if (!body) return;
        const bottom = body.getBoundingClientRect().bottom - screen.top;
        bubble.style.setProperty("--bubble-bottom", `${bottom.toFixed(2)}px`);
      });
    };
    const schedule = () => { if (!raf) raf = requestAnimationFrame(update); };
    update();
    root.addEventListener("scroll", schedule, { passive: true });
    const observer = new ResizeObserver(schedule);
    observer.observe(root);
    const mutations = new MutationObserver(schedule);
    mutations.observe(root, { childList: true, subtree: true, characterData: true });
    return () => { cancelAnimationFrame(raf); root.removeEventListener("scroll", schedule); observer.disconnect(); mutations.disconnect(); };
  }, [container, frame]);
}

"use client";

import { useLayoutEffect, useRef, type ComponentProps, type CSSProperties, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import { usePlatform, type Platform } from "@/components/imessage/platform";
import { bodyClipPath, tailBox, tailPath, tailSeamOverlap } from "@/components/imessage/bubble-shape";
import { bubbleMetrics, emojiFontStack, fontStack, type Direction, type Service } from "@/components/imessage/tokens";

export type MessageBubbleProps = Omit<ComponentProps<"div">, "children"> & {
  direction?: Direction;
  service?: Service;
  /** Draw the tail. Both platforms only tail the last bubble of a cluster; the list decides. */
  tail?: boolean;
  /** Group-chat sender name shown above an incoming bubble. */
  sender?: string;
  /** "Delivered", "Read 9:41 AM", "Sent as Text Message"… */
  status?: ReactNode;
  edited?: boolean;
  /** Tapback balloons; positioned on the bubble's top corner away from the screen edge. */
  reactions?: ReactNode;
  /** Render a big glyph with no bubble (auto-detected for 1–3 emoji when omitted). */
  emojiOnly?: boolean;
  /**
   * Clicked once, so the balloon carries its selection overlay. macOS only; the message list drives
   * this from `selectedIds` and the macOS pane owns the click. See `selectionOverlayClass`.
   */
  selected?: boolean;
  /**
   * Screen-space y of the bubble body's bottom edge, in px, for the native position-dependent fill.
   * The message list keeps this updated while scrolling; leave it unset for a mid-screen color.
   */
  screenBottom?: number;
  /** Widest the bubble may grow. Defaults to the native rule: 280.5px on iOS, 60.7% of the pane on macOS. */
  maxWidth?: number | string;
  platform?: Platform;
  children?: ReactNode;
};

const EMOJI_ONLY = /^(?:\p{Extended_Pictographic}(?:️|‍\p{Extended_Pictographic}|[\u{1F3FB}-\u{1F3FF}])*\s?){1,3}$/u;

export function isEmojiOnly(text: ReactNode): boolean {
  return typeof text === "string" && EMOJI_ONLY.test(text.trim());
}

/**
 * Where a reaction balloon hangs off a message's own box, per platform. It lives here because every
 * message kind needs it, not only a text bubble: a photo, a link card, an audio row and a bare emoji
 * all take reactions too, and each draws its own container.
 */
export const reactionOffsets: Record<Platform, { marginTop: number; top: number; side: number }> = {
  ios: { marginTop: 28, top: -27.25, side: -14.1 },
  macos: { marginTop: 19.6, top: -19.1, side: -9.9 },
};

function fillVars(direction: Direction, service: Service): CSSProperties {
  const key = direction === "incoming" ? "gray" : service === "sms" ? "green" : "blue";
  return { "--im-fill-top": `var(--im-${key}-top)`, "--im-fill-bottom": `var(--im-${key}-bottom)`, "--im-sel": `var(--im-sel-${key})` } as CSSProperties;
}

/**
 * The overlay a selected balloon carries, read out of macOS Messages itself rather than a screenshot:
 * `-[CKTextBalloonView setSelected:withSelectionState:]` turns on a highlight overlay layer whose
 * colour is `-[CKBalloonView highlightOverlayColor]`, which for a coloured balloon is
 * `-[CKUIThemeMac balloonOverlayColorForColorType:]`. Blue and gray are opaque there, so a selected
 * bubble drops its screen-space gradient for a flat fill; green is a wash left over it. Both themes
 * share the green. Values from ChatKit 26.5 (macOS 26.5).
 */
export const selectionOverlayClass =
  "[--im-sel-blue:#1b60d8] [--im-sel-gray:#c6c6c7] [--im-sel-green:#0a0a7833] " +
  "dark:[--im-sel-blue:#0b50c8] dark:[--im-sel-gray:#55555c]";

/**
 * Native bubbles hug their longest wrapped line instead of stretching to the maximum width, and
 * center text that is narrower than the minimum bubble width. CSS shrink-to-fit cannot express either,
 * so measure the laid-out line boxes and set the frame width explicitly.
 */
function useNativeTextFit(enabled: boolean, paddingX: number, minWidth: number, deps: unknown[]) {
  // The ref is created here rather than passed in, so the DOM writes below are on a value this hook
  // owns.
  const frame = useRef<HTMLDivElement>(null);
  useLayoutEffect(() => {
    const frameEl = frame.current;
    const textEl = frameEl?.querySelector<HTMLElement>('[data-slot="text"]');
    if (!enabled || !frameEl || !textEl) return;
    const container = frameEl.parentElement;
    let raf = 0;
    const measure = () => {
      frameEl.style.width = "";
      const range = document.createRange();
      range.selectNodeContents(textEl);
      const lines: Array<{ top: number; left: number; right: number }> = [];
      for (const rect of Array.from(range.getClientRects())) {
        if (rect.width === 0 && rect.height === 0) continue;
        const line = lines.find(l => Math.abs(l.top - rect.top) < 1);
        if (line) { line.left = Math.min(line.left, rect.left); line.right = Math.max(line.right, rect.right); }
        else lines.push({ top: rect.top, left: rect.left, right: rect.right });
      }
      if (!lines.length) return;
      const longest = Math.max(...lines.map(l => l.right - l.left));
      const bubble = textEl.parentElement as HTMLElement;
      bubble.style.textAlign = lines.length === 1 && longest < minWidth - 2 * paddingX ? "center" : "";
      const hug = Math.ceil((longest + 2 * paddingX) * 100) / 100 + 0.05;
      if (lines.length > 1 && hug < frameEl.getBoundingClientRect().width - 0.1) frameEl.style.width = `${hug}px`;
    };
    measure();
    const observer = new ResizeObserver(() => { cancelAnimationFrame(raf); raf = requestAnimationFrame(measure); });
    if (container) observer.observe(container);
    document.fonts?.ready.then(() => measure()).catch(() => {});
    return () => { observer.disconnect(); cancelAnimationFrame(raf); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [enabled, paddingX, minWidth, ...deps]);
  return frame;
}

export function MessageBubble({
  direction = "incoming", service = "imessage", tail = false, sender, status, edited = false, reactions, emojiOnly, selected = false,
  screenBottom, maxWidth, platform: platformProp, className, style, children, ...props
}: MessageBubbleProps) {
  const contextPlatform = usePlatform();
  const platform = platformProp ?? contextPlatform;
  const m = bubbleMetrics[platform];
  const outgoing = direction === "outgoing";
  const side = outgoing ? "right" : "left";
  const big = emojiOnly ?? isEmojiOnly(children);
  const tailW = tailBox.width * m.tailScale;
  const tailH = tailBox.height * m.tailScale;
  const hang = tailBox.hang * m.tailScale;
  // macOS's tail box is 15.4 × 14.84, so its left edge lands on a fraction (594.609 in the 630pt
  // pane) and Chrome paints the tail's clip up to half a point off the body's clip edge, leaving a
  // white hairline down the bubble (one 75%-white device pixel at 2x, measured at x 594.5 on the
  // four-line bubble). Overlapping the body into the box closes it. iOS's box is 22 × 21.2 on whole
  // pixels and shows no seam, so it keeps a flush join. See bodyClipPath.
  const tailOverlap = tailSeamOverlap[platform];
  const frame = useNativeTextFit(!big, m.paddingX, m.minWidth, [children, platform, maxWidth]);

  // The fill is one gradient in screen coordinates. Anchor it to the bubble's bottom so the body and
  // the tail (which hangs `hang` px lower) share the same image without knowing the body height.
  // `--bubble-bottom` may also be set on the element directly (see use-screen-space.ts) so scrolling
  // never needs a React render.
  const bottomVar = screenBottom === undefined ? "var(--bubble-bottom, calc(var(--im-screen-h) * 0.55))" : `${screenBottom}px`;
  // The selection overlay is one more background layer over the fill, so the body's clip and the
  // tail's clip carry it for free and no extra element is needed.
  const fill: CSSProperties = {
    backgroundImage: `${selected ? "linear-gradient(var(--im-sel), var(--im-sel))," : ""}linear-gradient(var(--im-fill-top), var(--im-fill-bottom))`,
    backgroundSize: selected ? "100% 100%, 100% var(--im-screen-h)" : "100% var(--im-screen-h)",
    backgroundRepeat: "no-repeat",
    backgroundColor: "var(--im-fill-bottom)",
  };
  // background-position-y = 100% + K puts the image's bottom K below the element's bottom.
  const at = (position: string) => (selected ? `0 0, ${position}` : position);
  const bodyFill: CSSProperties = { ...fill, backgroundPosition: at(`0 calc(100% + (var(--im-screen-h) - ${bottomVar}))`) };
  const tailFill: CSSProperties = { ...fill, backgroundPosition: at(`0 calc(100% + (var(--im-screen-h) - ${bottomVar} - ${hang}px))`) };
  const vars = { ...(screenBottom === undefined ? {} : { "--bubble-bottom": `${screenBottom}px` }), ...fillVars(direction, service) } as CSSProperties;
  const reactionOffset = reactionOffsets[platform];

  return (
    <div data-slot="message-bubble" data-direction={direction} data-service={service} data-platform={platform} data-selected={selected ? "true" : undefined}
      className={cn("flex min-w-0 flex-col", selectionOverlayClass, outgoing ? "items-end" : "items-start", className)}
      style={{ fontFamily: fontStack, ...vars, ...style }} {...props}>
      {sender && <span data-slot="sender" className="mb-[2px] px-[14px] text-[12px] leading-[14px]" style={{ color: "var(--im-secondary)" }}>{sender}</span>}
      <div ref={frame} data-slot="bubble-frame" className="relative max-w-full" style={{ maxWidth: maxWidth ?? (platform === "ios" ? m.maxWidth : `${m.maxWidthRatio * 100}%`), marginTop: reactions ? reactionOffset.marginTop : undefined }}>
        {big ? (
          <div data-slot="emoji" style={{ fontSize: m.emojiOnlySize, lineHeight: `${m.emojiOnlyLineHeight}px`, fontFamily: emojiFontStack, padding: `0 ${m.emojiOnlyInset}px` }}>
            <span className="sr-only">{outgoing ? "You: " : `${sender ?? "Contact"}: `}</span>{children}
          </div>
        ) : (
          <div data-slot="bubble" className="relative whitespace-pre-wrap [overflow-wrap:anywhere]" style={{
            fontSize: m.fontSize, lineHeight: `${m.lineHeight}px`, letterSpacing: m.letterSpacing,
            padding: `${m.paddingY}px ${m.paddingX}px`, minWidth: m.minWidth, textAlign: "start",
            color: outgoing ? "var(--im-outgoing-text)" : "var(--im-incoming-text)",
          }}>
            {/* The fill lives behind the text so clipping the tail corner never clips glyphs.
                Chrome rounds a painted background box to whole CSS px, so the widest macOS bubble,
                whose layout box is 227.71875 to 610, paints 228.00 to 610.00: 0.29 narrower and
                0.24 to the right of native's 227.477 to 609.763. No token can move that. A layout
                left edge of 227.5 rounds to the same 228, and `will-change` does not opt out;
                only a fractional `transform` escapes the rounding, and the send and receive
                animations already own this element's transform, so it stays as it is. */}
            {/* The tail-less case still carries a clip-path, and that is not cosmetic: Chrome snaps a
                plain rounded-rect background to whole CSS pixels, so a body laid out at 100.333 paints
                at 100.0, while native's bodies sit on thirds. A clip-path opts the fill out of that
                snapping and it paints where the layout put it. Verified at 3x: 100.333 painted at
                100.0 without one and at exactly device row 301 with one. */}
            <div aria-hidden="true" data-slot="fill" className="pointer-events-none absolute inset-0" style={{ borderRadius: m.radius, clipPath: tail ? bodyClipPath(side, m.tailScale, tailOverlap) : `inset(0 round ${m.radius}px)`, ...bodyFill }} />
            {tail && <div aria-hidden="true" data-slot="tail" className="pointer-events-none absolute" style={{
              [side]: 0, bottom: -hang, width: tailW, height: tailH + hang, clipPath: `path("${tailPath(side, m.tailScale)}")`, ...tailFill,
            }} />}
            <span className="sr-only">{outgoing ? "You: " : `${sender ?? "Contact"}: `}</span>
            <span data-slot="text" className="relative">{children}</span>
          </div>
        )}
        {reactions && <div data-slot="reactions" className="absolute z-10" style={{ top: reactionOffset.top, [outgoing ? "left" : "right"]: reactionOffset.side }}>{reactions}</div>}
      </div>
      {edited && <span data-slot="edited" className="mt-[3px] px-[14px] text-[11px] font-medium leading-[13px]" style={{ color: "var(--im-edited)" }}>Edited</span>}
      {status && <div data-slot="status" style={{ fontSize: m.statusFontSize, lineHeight: `${m.statusLineHeight}px`, fontWeight: 600, letterSpacing: m.statusLetterSpacing, marginTop: m.statusGap, paddingInlineEnd: outgoing ? m.statusInset : 0, paddingInlineStart: outgoing ? 0 : m.statusInset, color: "var(--im-secondary)" }}>{status}</div>}
    </div>
  );
}

"use client";

import { useId, useLayoutEffect, useRef, type ComponentProps, type CSSProperties, type ReactNode, type RefObject } from "react";
import { cn } from "@/lib/utils";
import { usePlatform, type Platform } from "@/components/imessage/platform";
import { emojiFontStack, fontStack } from "@/components/imessage/tokens";

/**
 * Tapback balloon, measured from iOS 26 (`references/ios/captures/tapback-love-light.png`, 3x):
 * a Ø34 circle with two trailing circles (Ø10.4 at (−10.82, +15.20) and Ø5 at (−17.49, +23.46) from
 * the balloon's center) pointing away from the bubble. Own reactions are #0088ff (light and dark), the
 * heart is an 18.34×16.33 glossy pink shape centered 0.8 below the circle's center. Others' balloons are
 * #e9e9eb light / #262629 dark (`incoming-light.png`, `incoming-dark.png`). macOS (circle-fitted on
 * `references/macos/captures/tapback-love-light-2x.png` and `tapback-love-dark-2x.png`, both 2x, rmse
 * 0.01–0.03 pt): Ø27.98 centred (136.72, 57.45) pt, trail Ø8.04 at (−9.04, +12.42) and Ø4.00 at
 * (−14.22, +19.05), heart ink 14.64 × 12.96 centred 0.53 below the circle's centre. Both captures give
 * the same numbers to 0.01 pt.
 *
 * The macOS fill is one theme-independent blue, #5498f8, laid over the pane with a vertical opacity
 * ramp: solving the light/dark pair row by row gives a constant colour (85, 152, 248) and an alpha of
 * 0.912 at the top edge rising to 1.00 at ≈83% down (light row y=89 reads (100,161,249), dark
 * (80,141,229); by row y=139 both read (84,152,248)). The trailing circles are fully opaque.
 * The artwork is also knocked out of whatever it covers by a 0.5 pt rim in the pane colour: invisible
 * over the empty pane, it shows as a ring where the balloon laps the bubble (dark 2x, radial cut at
 * −50°: (84,151,247) → (55,88,133) → (84,152,248); light: (85,152,248) → (182,218,251) → (108,186,245)).
 */
export const tapbackLabels = { love: "Love", like: "Like", dislike: "Dislike", laugh: "Laugh", emphasize: "Emphasize", question: "Question" } as const;
export type TapbackType = keyof typeof tapbackLabels;
export const tapbackTypes = Object.keys(tapbackLabels) as TapbackType[];

/** Local color tokens (not in tokens.ts). Measured own-reaction blue; the rest are system values. */
export const tapbackColors = {
  own: "#0088ff",
  ownDark: "#0088ff",
  /** Highlight ring behind the chosen tapback inside the bar (Ø44.2; measured on both selected captures). */
  selectedRing: "#26aeff",
  selectedRingDark: "#0064d2",
} as const;

/**
 * The macOS own-reaction blue and the opacity ramp the main circle carries over it. Solved row by row
 * from the light/dark pair of `tapback-love-*-2x.png` at the balloon's own rows y 89–139 (2x): one
 * colour in both themes, alpha 0.907 at the top edge, 0.951 a quarter down, 0.982 at the centre and
 * opaque from ≈83% down. Reproducing it as alpha (not as two baked colours) keeps both themes right.
 */
export const macosBalloonFill = "#5498f8";
const macosBalloonSurface = "linear-gradient(to bottom, rgba(84,152,248,0.907) 0%, rgba(84,152,248,0.951) 25%, rgba(84,152,248,0.982) 50%, rgba(84,152,248,1) 100%)";
/** The macOS balloon is knocked out of what it covers by this much pane colour (measured 0.51 pt). */
export const macosBalloonRim = 0.5;

/**
 * CSS variables the tapback UI reads (with fallbacks to the light iOS values). Spread on a frame
 * next to `paletteVars`. Glass fills were solved from the captures: the pill over the dimmed white
 * list is #ededef and over the dimmed green bubble ≈#b4efc6 (brighter than the dimmed content, hence
 * the brightness term); over the dimmed black list it is #1f1e21. The dim itself is rgba(22,18,44,0.21).
 */
export function tapbackVars(theme: "light" | "dark", platform: Platform = "ios"): Record<string, string> {
  const ios: Record<string, string> = theme === "light" ? {
    "--im-dim": "rgba(22,18,44,0.21)", "--im-glass": "rgba(229,229,231,0.69)", "--im-glass-filter": "blur(9px) brightness(1.32) saturate(1.35)", "--im-glass-solid": "#ededef", "--im-glass-rim": "rgba(255,255,255,0.55)",
    "--im-glass-shadow": "0 6px 24px rgba(0,0,0,0.10)", "--im-picker-icon": "#aeaeb2", "--im-menu-glass": "rgba(229,229,231,0.69)", "--im-menu-glass-filter": "blur(9px) brightness(1.32) saturate(1.35)", "--im-menu-bg": "#edeff1", "--im-menu-text": "#000000",
    "--im-menu-separator": "rgba(0,0,0,0.12)", "--im-menu-destructive": "#ff3b30", "--im-tapback-own": tapbackColors.own, "--im-tapback-ring": tapbackColors.selectedRing,
  } : {
    "--im-dim": "rgba(22,18,44,0.21)", "--im-glass": "rgba(38,37,39,0.8)", "--im-glass-filter": "blur(9px) saturate(1.6)", "--im-glass-solid": "#1f1e21", "--im-glass-rim": "rgba(255,255,255,0.10)",
    "--im-glass-shadow": "0 6px 24px rgba(0,0,0,0.5)", "--im-picker-icon": "#8e8e93", "--im-menu-glass": "rgba(20,25,25,0.8)", "--im-menu-glass-filter": "blur(9px) saturate(2)", "--im-menu-bg": "#121316", "--im-menu-text": "#ffffff",
    "--im-menu-separator": "rgba(255,255,255,0.15)", "--im-menu-destructive": "#ff453a", "--im-tapback-own": tapbackColors.ownDark, "--im-tapback-theirs": "#262629", "--im-tapback-ring": tapbackColors.selectedRingDark,
  };
  if (platform === "ios") return ios;
  const macos = { "--im-tapback-own": macosBalloonFill, "--im-tapback-own-surface": macosBalloonSurface };
  return theme === "light"
    ? { ...ios, ...macos, "--im-menu-bg": "rgba(247,248,251,0.92)", "--im-menu-text": "#242526", "--im-menu-separator": "#dfe0e2", "--im-menu-border": "#b1b1b1", "--im-menu-rim": "rgba(255,255,255,0.7)" }
    : { ...ios, ...macos, "--im-menu-bg": "rgba(30,34,39,0.92)", "--im-menu-text": "#dcddde", "--im-menu-separator": "#3e4145", "--im-menu-border": "#050506", "--im-menu-rim": "rgba(255,255,255,0.28)", "--im-tapback-theirs": "#3b3b3d" };
}

export type BalloonGeometry = { main: number; medium: number; small: number; mediumOffset: [number, number]; smallOffset: [number, number]; glyph: number; /** The glyph sits this far below the circle's centre. */ glyphOffsetY?: number };

/**
 * Balloon geometry per platform. Offsets are the trailing circles' centers relative to the main
 * center, pointing left. iOS from `incoming-light.png` (Ø34.0, trail Ø10.4 at (−10.82, +15.20) and
 * Ø5.0 at (−17.49, +23.46), heart ink 18.34).
 *
 * macOS is circle-fitted on both `tapback-love-light-2x.png` and `tapback-love-dark-2x.png`, which
 * agree to 0.01 pt: main centre (273.44, 114.90) px Ø55.97 px, medium (255.37, 139.73) Ø16.07, small
 * (245.00, 153.00) Ø7.99. It is close to the iOS artwork at 28/34 but not exactly: that scaling would
 * put the trail at Ø8.57 and Ø4.12, 6% and 3% larger. The heart ink (rows y 103–129, columns x 259–288)
 * measures 14.64 × 12.96 with its centre 0.53 below the circle's, of which 0.07 comes from the glyph
 * box itself, so the box is nudged 0.46.
 */
export const balloonGeometry: Record<Platform, BalloonGeometry> = {
  ios: { main: 34, medium: 10.4, small: 5, mediumOffset: [-10.82, 15.2], smallOffset: [-17.49, 23.46], glyph: 18.34, glyphOffsetY: 0.8 },
  macos: { main: 28, medium: 8.04, small: 4, mediumOffset: [-9.04, 12.42], smallOffset: [-14.22, 19.05], glyph: 14.64, glyphOffsetY: 0.46 },
};

/**
 * Where a balloon sits relative to the bubble body it belongs to, measured on the settled captures.
 * `marginTop` is the extra space the list opens above the bubble, `top`/`side` place the main circle
 * against the body's top corner on the side away from the screen edge. Consumed by `message-bubble`.
 *
 * iOS: `conv3-light.png` → `tapback-love-light.png` is the same fixture with and without the balloon,
 * and the cluster gap grows from 10.313 to 38.313, i.e. exactly 28. `top`/`side` average the outgoing
 * capture (−27.47 / −14.02) and the mirrored incoming one (`incoming-light.png`, −27.31 / +13.68).
 * macOS (`tapback-love-dark-2x.png`, cross-checked light): body bottom 34.93 → next body top 65.51 is
 * a 30.58 gap where the cluster gap below it is 3.18, so the slot opens 27.40; the Ø28 circle's top
 * (86.92 px) sits 22.05 above the body top (131.01 px) and its leading edge (245.46 px) 11.79 outside
 * the body's leading edge (269.03 px).
 *
 * `message-bubble` carries its own copy of these numbers and is the one that actually places a
 * balloon; its macOS row still reads { 19.6, −19.1, −9.9 } and is 7.8 / 3.0 / 1.9 pt off.
 */
export const balloonSlot: Record<Platform, { marginTop: number; top: number; side: number }> = {
  ios: { marginTop: 28, top: -27.39, side: -13.85 },
  macos: { marginTop: 27.4, top: -22.05, side: -11.79 },
};

/** The emoji-picker "thought bubble" beside a long-pressed message is the same shape at ~1.3x. */
export const pickerBalloonGeometry: BalloonGeometry = { main: 44, medium: 14.6, small: 8, mediumOffset: [-13.2, 20.3], smallOffset: [-22.2, 30.7], glyph: 24 };

/** Renders the trailing circles of a balloon; the parent is the main circle (position: relative). */
export function BalloonTrail({ geometry, side, color }: { geometry: BalloonGeometry; side: "left" | "right"; color: string }) {
  const half = geometry.main / 2;
  const place = (d: number, [dx, dy]: [number, number]): CSSProperties => ({
    position: "absolute", width: d, height: d, borderRadius: "50%", background: color, top: half + dy - d / 2,
    [side === "left" ? "left" : "right"]: half + dx - d / 2,
  });
  return (
    <>
      <span aria-hidden="true" data-slot="balloon-medium" style={place(geometry.medium, geometry.mediumOffset)} />
      <span aria-hidden="true" data-slot="balloon-small" style={place(geometry.small, geometry.smallOffset)} />
    </>
  );
}

const glossyText = (gradient: string): CSSProperties => ({ backgroundImage: gradient, WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent", WebkitTextFillColor: "transparent" });

/**
 * Heart ramps, sampled at matching heights on every capture. On a gray or white balloon Apple's heart
 * runs #ffc1d8 → #ff4796; on the blue own-reaction balloon (and on the blue selected disc in the bar)
 * the same artwork reads a constant 21/255 lighter in green and 20/255 in blue, so it keeps its
 * contrast. Positions are the radial offsets fitted to the Ø49.8 balloon in the details popover.
 */
const heartRamp = {
  plain: [["0", "#ffd9ea"], ["0.12", "#ffc1d8"], ["0.38", "#ff99ca"], ["0.51", "#ff81bd"], ["0.79", "#ff6cb0"], ["1", "#ff4796"]],
  onAccent: [["0", "#ffeefe"], ["0.12", "#ffd6ec"], ["0.38", "#ffaede"], ["0.51", "#ff96d1"], ["0.79", "#ff81c4"], ["1", "#ff5caa"]],
} as const;

/**
 * The six classic tapback glyphs and custom emoji, drawn to match Apple's artwork.
 * `size` is the glyph box: 25.33 in the iOS tapback bar, 18.34 in a Ø34 balloon.
 * `onAccent` picks the lighter artwork Apple uses on the blue balloon and the blue selected disc.
 */
export function TapbackGlyph({ type, emoji, size, onAccent = false, className, style }: { type?: TapbackType; emoji?: string; size: number; onAccent?: boolean; className?: string; style?: CSSProperties }) {
  const id = useId().replace(/:/g, "");
  const base: CSSProperties = { display: "inline-flex", alignItems: "center", justifyContent: "center", lineHeight: 1, userSelect: "none", ...style };
  if (emoji || !type) {
    return <span data-slot="tapback-glyph" data-glyph="emoji" className={className} style={{ ...base, fontSize: size, fontFamily: emojiFontStack, width: size, height: size }}>{emoji}</span>;
  }
  if (type === "love") {
    // Outline traced from `tapback-love-light.png` at 3x: ink 18.34 × 16.33 (ratio 0.8906), the two
    // lobes are r 4.75 circles centred (4.75, 4.91) and (13.25, 4.91) meeting in a notch at (9, 2.79),
    // and each flank is one cubic to the tip (rmse 0.03 against 15 sampled rows).
    const w = size, h = size * 0.8906;
    return (
      <svg data-slot="tapback-glyph" data-glyph="love" className={className} style={base} width={w} height={h} viewBox="0 0 18 16.03" aria-hidden="true">
        <defs>
          <radialGradient id={`${id}-h`} cx="0.5" cy="0.18" r="0.8">
            {(onAccent ? heartRamp.onAccent : heartRamp.plain).map(([offset, color]) => <stop key={offset} offset={offset} stopColor={color} />)}
          </radialGradient>
        </defs>
        <path d="M9,16.03 C7.6,15.9 0,10.51 0,4.91 A4.75,4.75 0 0 1 9,2.79 A4.75,4.75 0 0 1 18,4.91 C18,10.51 10.4,15.9 9,16.03 Z" fill={`url(#${id}-h)`} />
      </svg>
    );
  }
  if (type === "like" || type === "dislike") {
    // The 👎 face sits 1.84 higher than native in a 25.33 slot; 👍 lands right. Push it back down.
    const drop = type === "dislike" ? size * 0.145 : 0;
    return <span data-slot="tapback-glyph" data-glyph={type} className={className} style={{ ...base, marginTop: (typeof base.marginTop === "number" ? base.marginTop : 0) + drop, fontSize: size * 0.987, fontFamily: emojiFontStack, width: size, height: size }}>{type === "like" ? "👍" : "👎"}</span>;
  }
  if (type === "laugh") {
    return (
      <span data-slot="tapback-glyph" data-glyph="laugh" className={className} style={{ ...base, flexDirection: "column", width: size, height: size, fontFamily: fontStack, fontWeight: 800, fontSize: size * 0.68, lineHeight: `${size * 0.5}px`, letterSpacing: -size * 0.02, ...glossyText("linear-gradient(#5fc9ff, #0aa6ff 55%, #0090f5)") }}>
        <span style={{ WebkitTextStroke: `${size * 0.02}px rgba(255,255,255,0.6)` }}>HA</span><span style={{ WebkitTextStroke: `${size * 0.02}px rgba(255,255,255,0.6)` }}>HA</span>
      </span>
    );
  }
  if (type === "emphasize") {
    const w = size * 0.71, h = size * 1.053;
    return (
      <svg data-slot="tapback-glyph" data-glyph="emphasize" className={className} style={base} width={w} height={h} viewBox="0 0 18 26.67" aria-hidden="true">
        <defs><linearGradient id={`${id}-e`} x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#ff8c6e" /><stop offset="0.6" stopColor="#ff4f3f" /><stop offset="1" stopColor="#ff2a34" /></linearGradient></defs>
        {[0, 10].map(x => (
          <g key={x} transform={`translate(${x} 0)`}>
            <path d="M0.2,3.6 A3.8,3.8 0 0 1 7.8,3.6 L6.3,16.3 A2.3,2.3 0 0 1 1.7,16.3 Z" fill={`url(#${id}-e)`} />
            <circle cx="4" cy="23.1" r="3.5" fill={`url(#${id}-e)`} />
            <ellipse cx="3" cy="3.8" rx="1.3" ry="2" fill="#fff" opacity="0.45" />
          </g>
        ))}
      </svg>
    );
  }
  if (type === "question") {
    const w = size * 0.566, h = size * 0.987;
    return (
      <svg data-slot="tapback-glyph" data-glyph="question" className={className} style={base} width={w} height={h} viewBox="0 0 14.33 25" aria-hidden="true">
        <defs><linearGradient id={`${id}-q`} x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#c4a8ff" /><stop offset="0.6" stopColor="#9b7cf5" /><stop offset="1" stopColor="#7a5ee0" /></linearGradient></defs>
        <path d="M2.4,7.4 A4.9,4.9 0 1 1 8.1,12.1 C7.3,12.6 7.2,13.4 7.2,15.4" fill="none" stroke={`url(#${id}-q)`} strokeWidth="4.2" strokeLinecap="round" strokeLinejoin="round" />
        <circle cx="7.2" cy="22.4" r="2.5" fill={`url(#${id}-q)`} />
        <path d="M4.4,5.4 A3.2,3.2 0 0 1 7.6,3.6" fill="none" stroke="#fff" strokeWidth="1.2" strokeLinecap="round" opacity="0.5" />
      </svg>
    );
  }
  return null;
}

export type TapbackProps = Omit<ComponentProps<"button">, "children" | "type"> & {
  reaction?: TapbackType;
  /** A custom emoji reaction instead of one of the six classics. */
  emoji?: string;
  /** Blue balloon (your own reaction) or the gray one for other people's. */
  own?: boolean;
  /** Which side of the bubble the balloon sits on; the trail points that way. Outgoing bubbles use "left". */
  side?: "left" | "right";
  selected?: boolean;
  count?: number;
  platform?: Platform;
  /** Extra content, e.g. a screen-reader description. */
  children?: ReactNode;
  /**
   * Pop the balloon in the way applying a Tapback does natively: it scales up past its size and
   * settles, the trailing circles riding the same scale. Off by default, because reactions that were
   * already on a message when the conversation opened do not animate; turn it on for one the person
   * just applied.
   */
  animateIn?: boolean;
  /** Scrub the entrance (0..1) instead of playing it. */
  appearProgress?: number;
};

/**
 * Timed on `references/macos/captures/tapback-apply-frames-100-123.png`, 24 consecutive 60 fps frames
 * (f100 = 1667 ms, 16.67 ms apart). The menu is still whole at f101 and has gone at f112, a 183 ms
 * dissolve (95%→5% in 134 ms). The balloon then appears at f118 = 1967 ms, 100 ms after the menu is
 * gone, in the same frame the list starts opening the slot. Its fill diameter over the settled Ø28
 * measures 0.19 (f118), 0.28 (f119), ≈0.52 (f120), ≈0.65 (f121), ≈0.75 (f122) and ≥0.80 (f123), so it
 * needs ≈110 ms to reach full size counting from the last empty frame. The small trailing circle
 * measures 0.49 / 0.64 / 0.71 / 0.81 across f120–f123, i.e. it rides the balloon's own scale with no
 * delay of its own — hence `trailDelay: 0` and no separate animation for the trail.
 *
 * The strip ends at f123 = 2050 ms with the balloon still growing, so the overshoot past 1 and the
 * settle after it are NOT in the capture: `duration` and the peak below are unverified.
 */
export const tapbackAppear = { duration: 420, growth: 110, trailDelay: 0 } as const;

export function Tapback({ reaction = "love", emoji, own = true, side = "left", selected = false, count, platform: platformProp, className, onClick, style, children, animateIn = false, appearProgress, ...props }: TapbackProps) {
  const contextPlatform = usePlatform();
  const host = useRef<HTMLSpanElement & HTMLButtonElement>(null);
  useLayoutEffect(() => {
    const element = host.current;
    if (!element || !animateIn) return;
    const reduced = typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches === true;
    if (reduced) return;
    // The trailing circles are children, so the one scale below carries them: the capture shows them
    // at the balloon's own scale in every frame, with no delay to animate separately.
    const grow = tapbackAppear.growth / tapbackAppear.duration;
    const balloon = element.animate(
      [
        { transform: "scale(0)", opacity: 0 },
        { offset: grow * 0.08, transform: "scale(0.12)", opacity: 1 },
        { offset: grow, transform: "scale(1)" },
        { offset: grow * 1.26, transform: "scale(1.14)" },
        { offset: 0.62, transform: "scale(0.94)" },
        { offset: 0.84, transform: "scale(1.03)" },
        { transform: "scale(1)" },
      ],
      { duration: tapbackAppear.duration, easing: "linear", fill: "both" },
    );
    if (appearProgress === undefined) balloon.play();
    else { balloon.pause(); balloon.currentTime = Math.max(0, Math.min(1, appearProgress)) * tapbackAppear.duration; }
    return () => balloon.cancel();
  }, [animateIn, appearProgress]);
  const platform = platformProp ?? contextPlatform;
  const g = balloonGeometry[platform];
  const fill = own ? "var(--im-tapback-own, #0088ff)" : "var(--im-tapback-theirs, #e9e9eb)";
  // macOS paints the main circle with the measured opacity ramp and knocks the artwork out of
  // whatever it laps with a 0.5 pt pane-coloured rim; the trailing circles stay flat and rimless.
  const surface = platform === "macos" && own ? `var(--im-tapback-own-surface, ${fill})` : fill;
  const rim = platform === "macos" ? `0 0 0 ${macosBalloonRim}px var(--im-bg, #fff)` : null;
  const ring = selected ? `0 0 0 ${platform === "ios" ? 2 : 1.5}px var(--im-bg, #fff), 0 0 0 ${platform === "ios" ? 4 : 3}px var(--im-tapback-ring, ${tapbackColors.selectedRing})` : null;
  // Reads on its own: "Love tapback, 2, from you" rather than a bare glyph name and a bracket.
  const label = `${emoji ?? tapbackLabels[reaction]} tapback${count !== undefined && count > 1 ? `, ${count}` : ""}${own ? ", from you" : ""}`;
  const pill = count !== undefined && count > 1;
  const rootStyle: CSSProperties = {
    position: "relative", display: "inline-flex", alignItems: "center", justifyContent: "center", boxSizing: "border-box",
    width: pill ? undefined : g.main, minWidth: g.main, height: g.main, borderRadius: g.main / 2, background: surface,
    paddingInline: pill ? g.main * 0.26 : 0, gap: g.main * 0.12, fontFamily: fontStack,
    color: own ? "#fff" : "var(--im-incoming-text, #000)",
    // The selected ring uses the same token as the picker, so dark gets #0064d2 rather than #26aeff.
    boxShadow: [rim, ring].filter(Boolean).join(", ") || undefined,
    ...style,
  };
  const content = (
    <>
      <TapbackGlyph type={emoji ? undefined : reaction} emoji={emoji} size={g.glyph} onAccent={own} style={{ marginTop: emoji ? 0 : 2 * (g.glyphOffsetY ?? 0) }} />
      {pill && <span data-slot="tapback-count" style={{ fontSize: g.main * 0.38, fontWeight: 600, lineHeight: 1 }}>{count}</span>}
      <BalloonTrail geometry={g} side={side} color={fill} />
      {children}
    </>
  );
  const shared = { "data-slot": "tapback", "data-reaction": emoji ? "emoji" : reaction, "data-own": own, "data-side": side, "data-platform": platform } as const;
  if (!onClick) return <span ref={host as RefObject<HTMLSpanElement>} role="img" aria-label={label} className={cn("select-none", className)} style={{ ...rootStyle, transformOrigin: side === "left" ? "85% 85%" : "15% 85%" }} {...shared}>{content}</span>;
  return (
    <button ref={host as RefObject<HTMLButtonElement>} type="button" aria-label={label} aria-pressed={selected} className={cn("cursor-pointer select-none border-0 outline-none focus-visible:ring-2 focus-visible:ring-blue-500 focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50", className)} style={{ ...rootStyle, transformOrigin: side === "left" ? "85% 85%" : "15% 85%" }} onClick={onClick} {...shared} {...props}>
      {content}
    </button>
  );
}

"use client";

import { useCallback, useEffect, useId, useLayoutEffect, useRef, useState, useSyncExternalStore, type ComponentProps, type CSSProperties, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import { Avatar } from "@/components/imessage/avatar";
import { usePlatform, type Platform } from "@/components/imessage/platform";
import { BalloonTrail, TapbackGlyph, balloonGeometry, macosBalloonRim, tapbackLabels, type BalloonGeometry, type TapbackType } from "@/components/imessage/tapback";
import { fontStack } from "@/components/imessage/tokens";

/**
 * "Tapback Details…", the surface both context menus open: who reacted, with what, and a way to take
 * your own reaction back.
 *
 * **NO CAPTURE EXISTS.** Nothing in `references/` records this surface on either platform, so not one
 * number below was read off a frame. They come from ChatKit 26.5 instead, the framework macOS
 * Messages is built on, read out of the live runtime on 2026-09-08 with a Mac Catalyst probe
 * (`clang -target arm64-apple-ios26.0-macabi`, `dlopen` of
 * `/System/iOSSupport/System/Library/PrivateFrameworks/ChatKit.framework/ChatKit`, then `objc_msgSend`
 * on the class and instance getters named below). Every value states its selector.
 *
 * ChatKit calls this the **voting view**: `-[CKUIBehavior messageAcknowledgementVotingViewHeight]`
 * and its neighbours size the platter, and the Swift type `ChatKit.StyleSupport` carries the interior
 * as class constants (`+votingViewCellWidth` and the rest). The strings are ChatKit's own, from
 * `ChatKit.framework/Resources/ChatKit.loctable` (`en`): `TAPBACK_DETAILS_ELLIPSIS` = "Tapback
 * Details…" is the menu row, `TAPBACK_DETAILS` = "Tapback Details" the title, and
 * `ACCESSIBILITY_TAPBACK_LABEL` = "%@ reacted with %@" plus
 * `ACCESSIBILITY_EXPANDED_TAPBACK_FORMAT` = "%lu %@ reactions from %@" are the accessibility texts
 * this file reproduces.
 *
 * **The native layout is a horizontal platter, not a table.** `votingViewPlatterCornerRadius` = 34
 * round, `messageAcknowledgementVotingViewHeight` = 72 tall on iOS and 80 on Mac, holding one
 * `votingViewCellWidth` = 64 wide cell per reactor: a `votingViewAvatarDiameter` = 44 avatar badged
 * with the reaction in a `votingViewAvatarViewGlyphFrame` 20 square, then
 * `votingViewAvatarToTextSpacing` = 4 and a `votingViewAvatarViewLabelHeight` = 18 name. The count
 * leads it as a `votingViewExpandedTally` 27 square per reaction kind with its total beside it
 * (`votingViewTallyLabelSpacing` = 0). This file reproduces that shape rather than a vertical list.
 *
 * **Mac numbers go through Catalyst's 0.77.** ChatKit is a UIKit framework and Messages a Catalyst
 * app, so one Mac-idiom point is 0.77 of an AppKit point. Two of ChatKit's own constants pin that
 * factor against measurements already in SPEC.md:
 * `+[ChatKit.StyleSupport transcriptTitleViewAvatarButtonDiameter]` = 52 lands on the macOS header's
 * measured Ø40 avatar (52 × 0.77 = 40.04), and `+transcriptTitleViewHeight` = 87 lands on the 67 that
 * capture's avatar and name pill span together (87 × 0.77 = 66.99). Neither matches iOS, whose nav
 * bar avatar is Ø60. Every macOS number here is therefore its ChatKit value times `catalystScale`,
 * and is unverified against a capture.
 *
 * **What is JUDGEMENT, and is marked so below:** the presentation's durations, the close button's
 * size, using the macOS knockout rim on the iOS badge, and presenting the platter as a bottom sheet
 * on iOS and an anchored popover on macOS (ChatKit has one platter and does not say how either host
 * presents it). The platter's fill, rim and shadow are not judgement: they reuse the glass solved
 * from `references/ios/captures/longpress-*.png` in `tapback.tsx`'s `tapbackVars`, and the balloon
 * artwork is the traced geometry from the same file, scaled.
 *
 * Not to be confused with `message-actions.tsx`'s `TapbackDetails`, which is a different ChatKit
 * surface: `CKTapbackAttributionView`, the card that floats above a long-pressed message you have
 * already reacted to (`-[CKUIBehavior attributionViewHeight]` = 132, `attributionViewMaxWidth` = 400
 * on iOS and 500 on Mac).
 */

/** One Mac-idiom UIKit point is this much of an AppKit point. See the header for the two constants that fix it. */
export const catalystScale = 0.77;

export type TapbackDetailsMetrics = {
  /** `-[CKUIBehavior messageAcknowledgementVotingViewHeight]`: 72 iOS, 80 Mac. */
  height: number;
  /** `+[ChatKit.StyleSupport votingViewPlatterCornerRadius]` = 34. */
  radius: number;
  /** `+votingViewHorizontalPadding` = 24. */
  paddingX: number;
  /** `+votingViewItemSpacing` = 24, between the tallies and between the cells. */
  itemSpacing: number;
  /** `+votingViewAdditionalTopInset` = 4. */
  topInset: number;
  /** `-[CKUIBehavior messageAcknowledgementVotingViewMaxWidth]`: 400 iOS, 500 Mac. */
  maxWidth: number;
  /** `-messageAcknowledgementVotingViewMinPadding`: 8 iOS, 6 Mac, from the presenting edge. */
  minPadding: number;
  /** `+votingViewCellWidth` = 64. */
  cellWidth: number;
  /** `+votingViewAvatarDiameter` = 44. */
  avatar: number;
  /** `+votingViewAvatarViewGlyphFrameWidth` and `…Height`, both 20: the reaction badged on the avatar. */
  glyphFrame: number;
  /** `+votingViewAvatarToTextSpacing` = 4. */
  avatarToText: number;
  /** `+votingViewAvatarViewLabelHeight` = 18. */
  labelHeight: number;
  /** `-[CKUIBehavior avatarNameFont]`: SFNS Regular 12 iOS, 16 Mac. */
  nameFontSize: number;
  /** `-[CKUIBehavior messageAcknowledgmentVoteCountFont]`: SFNS Regular 12 iOS, 16 Mac. */
  countFontSize: number;
  /** `+votingViewExpandedTallyWidth` and `…Height`, both 27. */
  tally: number;
  /** `+votingViewTallyLabelSpacing` = 0, between a tally and its count. */
  tallyLabelSpacing: number;
  /** `+votingViewBlurWidth` = 88: how far the platter fades its scrolling content at each end. */
  blurWidth: number;
  /** `+votingViewCloseButtonLeftPadding` = 22. The button's own size is judgement; see `closeSize`. */
  closeLeftPadding: number;
  /** JUDGEMENT: ChatKit gives the close button a left padding but no size, so it takes the tally's box. */
  closeSize: number;
};

const mac = (points: number) => Number((points * catalystScale).toFixed(4));

export const tapbackDetailsMetrics: Record<Platform, TapbackDetailsMetrics> = {
  ios: {
    height: 72, radius: 34, paddingX: 24, itemSpacing: 24, topInset: 4, maxWidth: 400, minPadding: 8,
    cellWidth: 64, avatar: 44, glyphFrame: 20, avatarToText: 4, labelHeight: 18,
    nameFontSize: 12, countFontSize: 12, tally: 27, tallyLabelSpacing: 0,
    blurWidth: 88, closeLeftPadding: 22, closeSize: 27,
  },
  macos: {
    height: mac(80), radius: mac(34), paddingX: mac(24), itemSpacing: mac(24), topInset: mac(4), maxWidth: mac(500), minPadding: mac(6),
    cellWidth: mac(64), avatar: mac(44), glyphFrame: mac(20), avatarToText: mac(4), labelHeight: mac(18),
    nameFontSize: mac(16), countFontSize: mac(16), tally: mac(27), tallyLabelSpacing: 0,
    blurWidth: mac(88), closeLeftPadding: mac(22), closeSize: mac(27),
  },
};

/**
 * The presentation. `scale` is ChatKit's own (`+[ChatKit.StyleSupport tapbackStartingScaleX]` and
 * `…ScaleY`, both 0.3). Everything else is JUDGEMENT, borrowed from motion this kit has already
 * measured rather than invented: `enter` and `ease` are the sheet duration and curve `ios-details.tsx`
 * uses for its own rise, and `exit`/`exitEase` are the long-press overlay's measured 220 ms dismissal
 * (`messageActionsTiming.exit`). ChatKit does carry `-[CKUIBehavior tapbackDismissalDuration]` = 0.5 s,
 * but it belongs to the picker rather than to this platter, so it is recorded and not used.
 */
export const tapbackDetailsMotion = {
  enter: 320,
  exit: 220,
  ease: "cubic-bezier(0.32, 0.72, 0, 1)",
  exitEase: "cubic-bezier(0.4, 0, 1, 1)",
  scale: 0.3,
  /** ChatKit's `-[CKUIBehavior tapbackDismissalDuration]` in ms. Recorded, not used; see above. */
  frameworkDismissal: 500,
} as const;

/**
 * Light values ride the root's inline style so the platter renders correctly with no Tailwind at all;
 * the dark set rides a `dark:` class, the way `avatar.tsx` splits its own gradient.
 *
 * The platter's fill, rim and shadow are the glass `tapback.tsx` solved from the long-press captures
 * (`--im-glass-solid` #ededef light and #1f1e21 dark, with its rim and shadow). `--im-td-label` is
 * ChatKit's `-[CKUITheme messageAcknowledgmentVotingTextColor]`, which resolves to
 * `secondaryLabelColor`: rgba(0,0,0,0.498) light, rgba(255,255,255,0.549) dark, the same colour
 * `-attributionCountViewFontColor` returns for the count. The dim behind the iOS sheet is the 20%
 * black measured on `references/ios/captures/newmsg-light.png` (`ios-new-message-sheet.tsx`), and the
 * close button's fill is the segmented-control track measured on `effects-picker-light.png`.
 */
const lightVars = {
  "--im-td-platter": "#ededef",
  "--im-td-rim": "rgba(255,255,255,0.55)",
  "--im-td-shadow": "0 6px 24px rgba(0,0,0,0.10)",
  "--im-td-label": "rgba(0,0,0,0.498)",
  "--im-td-dim": "rgba(0,0,0,0.2)",
  "--im-td-fill": "rgba(120,120,128,0.16)",
  "--im-td-theirs": "#e9e9eb",
} as const;

const darkVars =
  "dark:[--im-td-platter:#1f1e21] dark:[--im-td-rim:rgba(255,255,255,0.10)] dark:[--im-td-shadow:0_6px_24px_rgba(0,0,0,0.5)] " +
  "dark:[--im-td-label:rgba(255,255,255,0.549)] dark:[--im-td-dim:rgba(0,0,0,0.5)] dark:[--im-td-fill:rgba(120,120,128,0.24)] " +
  "dark:[--im-td-theirs:#262629]";

/** Which corner of the popover its entrance grows out of. */
const transformOrigins: Record<"top-left" | "top-right" | "bottom-left" | "bottom-right", string> = {
  "top-left": "0% 0%",
  "top-right": "100% 0%",
  "bottom-left": "0% 100%",
  "bottom-right": "100% 100%",
};

export type TapbackReactor = {
  id: string;
  /** Full name, used for the accessible text. The cell truncates it to one line. */
  name: string;
  /** What the 64 wide cell shows under the avatar; the first word of `name` when absent. */
  shortName?: string;
  /** One or two letters for the avatar; derived from `name` when absent. */
  initials?: string;
  /** A photo instead of initials. */
  avatar?: string;
  /** One of the six classics. Ignored when `emoji` is set. */
  reaction?: TapbackType;
  /** A custom emoji reaction. */
  emoji?: string;
  /** Your own reaction: the one cell that can be activated to take it back. */
  own?: boolean;
};

export type TapbackDetailsProps = Omit<ComponentProps<"div">, "children"> & {
  reactors: TapbackReactor[];
  platform?: Platform;
  /** Called when the own cell is activated. ChatKit's own name for this action is "Remove Tapback". */
  onRemove?: (reactor: TapbackReactor) => void;
  /** Dismiss: Escape, the close button, the iOS dim, or a click outside the macOS popover. */
  onClose?: () => void;
  /** False plays the dismissal; the platter stays mounted until it is over, then calls `onExited`. */
  open?: boolean;
  onExited?: () => void;
  /**
   * Seek the presentation to this fraction (0..1) instead of playing it, which is what the harness
   * does. It seeks whichever direction `open` selects, and a seeked dismissal never fires `onExited`:
   * scrubbing a timeline is not a dismissal, and a checkpoint has to land on the same frame every run.
   */
  progress?: number;
  /** macOS: the popover's top-left corner in the containing block, and the corner it grows out of. */
  left?: number;
  top?: number;
  origin?: keyof typeof transformOrigins;
  /** Move focus into the platter when it opens (keyboard users). */
  autoFocus?: boolean;
};

function clamp01(value: number) {
  return Math.max(0, Math.min(1, value));
}

const reducedMotionQuery = () => (typeof window === "undefined" ? null : window.matchMedia?.("(prefers-reduced-motion: reduce)") ?? null);
function subscribeReducedMotion(onChange: () => void) {
  const query = reducedMotionQuery();
  query?.addEventListener("change", onChange);
  return () => query?.removeEventListener("change", onChange);
}
/** `macos-plus-menu.tsx` has the same hook; this file keeps its own copy so it installs on its own. */
function usePrefersReducedMotion() {
  return useSyncExternalStore(subscribeReducedMotion, () => reducedMotionQuery()?.matches ?? false, () => false);
}

function initialsOf(reactor: TapbackReactor) {
  if (reactor.initials) return reactor.initials;
  return reactor.name.trim().split(/\s+/).slice(0, 2).map(part => part[0] ?? "").join("").toUpperCase();
}

function reactionKey(reactor: TapbackReactor) {
  return reactor.emoji ? `emoji:${reactor.emoji}` : `type:${reactor.reaction ?? "love"}`;
}

function reactionName(reactor: TapbackReactor) {
  return reactor.emoji ?? tapbackLabels[reactor.reaction ?? "love"];
}

/**
 * The balloon geometry from `tapback.tsx`, measured on `tapback-love-light.png` (iOS, Ø34) and on
 * both `tapback-love-*-2x.png` (macOS, Ø27.98), scaled so the whole balloon fills the ChatKit frame
 * it is given. Scaling the traced artwork keeps the glyph, the neck and both trailing circles in the
 * proportions the captures fix; only the overall size comes from the framework.
 */
export function scaledBalloonGeometry(platform: Platform, frame: number): BalloonGeometry {
  const g = balloonGeometry[platform];
  const k = frame / g.main;
  return {
    main: frame,
    medium: g.medium * k,
    small: g.small * k,
    mediumOffset: [g.mediumOffset[0] * k, g.mediumOffset[1] * k],
    smallOffset: [g.smallOffset[0] * k, g.smallOffset[1] * k],
    glyph: g.glyph * k,
    glyphOffsetY: (g.glyphOffsetY ?? 0) * k,
  };
}

/**
 * One reaction balloon at an arbitrary size, built from the scaled measured geometry. `Tapback`
 * itself is fixed at the balloon's own measured diameter, so the badge and the tally rebuild the
 * artwork here rather than scaling that component with a transform, which would scale its rim too.
 */
function Balloon({ geometry, own, side, rim = false, children, style }: { geometry: BalloonGeometry; own: boolean; side: "left" | "right"; rim?: boolean; children?: ReactNode; style?: CSSProperties }) {
  const fill = own ? "var(--im-tapback-own, #0088ff)" : "var(--im-td-theirs, #e9e9eb)";
  return (
    <span
      aria-hidden="true"
      data-slot="tapback-details-balloon"
      data-own={own}
      style={{
        position: "relative", display: "inline-flex", alignItems: "center", justifyContent: "center", boxSizing: "border-box",
        width: geometry.main, height: geometry.main, borderRadius: "50%", background: fill,
        boxShadow: rim ? `0 0 0 ${macosBalloonRim}px var(--im-td-platter, #ededef)` : undefined,
        ...style,
      }}
    >
      {children}
      <BalloonTrail geometry={geometry} side={side} color={fill} />
    </span>
  );
}

/**
 * JUDGEMENT: the cell shows a first name. ChatKit sizes the label at `votingViewCellWidth` 64 with
 * `avatarNameFont` at 12, which fits a first name and truncates almost every full one; native avatar
 * stacks label themselves the same way. The whole name stays in the accessible text, and a caller
 * with a better short form passes `shortName`.
 */
function shortNameOf(reactor: TapbackReactor) {
  return reactor.shortName ?? reactor.name.trim().split(/\s+/)[0] ?? reactor.name;
}

export function TapbackDetails({
  reactors, platform: platformProp, onRemove, onClose, open = true, onExited, progress,
  left, top, origin = "top-left", autoFocus = false, className, style, ...props
}: TapbackDetailsProps) {
  const contextPlatform = usePlatform();
  const platform = platformProp ?? contextPlatform;
  const m = tapbackDetailsMetrics[platform];
  const t = tapbackDetailsMotion;
  const id = useId().replace(/:/g, "");
  const reduced = usePrefersReducedMotion();
  const platter = useRef<HTMLDivElement>(null);
  const dim = useRef<HTMLDivElement>(null);
  const scroller = useRef<HTMLDivElement>(null);

  /**
   * The dismissal is derived DURING RENDER, not in an effect: an effect leaves one committed frame
   * with the platter already unmounted and the exit never gets to run. `macos-plus-menu.tsx` and
   * `ios-details.tsx` derive theirs the same way.
   */
  const [seenOpen, setSeenOpen] = useState(open);
  const [shown, setShown] = useState(open);
  const [settled, setSettled] = useState(open && reduced);
  if (seenOpen !== open) {
    setSeenOpen(open);
    if (open) { setShown(true); setSettled(reduced); }
    // Under reduced motion there is no dismissal to wait for, so it goes in the same frame.
    else if (reduced) setShown(false);
  }
  const closing = shown && !open;
  const state = closing ? "closing" : reduced || settled || (progress !== undefined && clamp01(progress) === 1) ? "open" : "entering";

  const exited = useRef(onExited);
  const close = useRef(onClose);
  useEffect(() => { exited.current = onExited; close.current = onClose; });

  // One place fires `onExited`, whether the platter left on its animation or under reduced motion.
  const wasShown = useRef(shown);
  useEffect(() => {
    if (wasShown.current && !shown) exited.current?.();
    wasShown.current = shown;
  }, [shown]);

  /**
   * Web Animations, not a transition or a rAF loop, so `document.getAnimations()` can reach the
   * timeline and a `progress` frame is a seek rather than a replay. iOS rises off the bottom edge the
   * way a sheet does; macOS pops out of the corner it is anchored by, from ChatKit's own 0.3.
   */
  useEffect(() => {
    const element = platter.current;
    if (!element || !shown || reduced) return;
    const poses: Keyframe[] = platform === "ios"
      ? [{ opacity: 0, transform: `translateY(${m.height + m.minPadding}px)` }, { opacity: 1, transform: "translateY(0px)" }]
      : [{ opacity: 0, transform: `scale(${t.scale})` }, { opacity: 1, transform: "scale(1)" }];
    const animation = open
      ? element.animate(poses, { duration: t.enter, easing: t.ease, fill: "both" })
      : element.animate([poses[1], poses[0]], { duration: t.exit, easing: t.exitEase, fill: "both" });
    if (progress !== undefined) {
      // Seeked, not played: a scrubbed checkpoint has to land on the same frame every run.
      animation.pause();
      try { animation.currentTime = clamp01(progress) * (open ? t.enter : t.exit); } catch { /* no timeline yet */ }
      return () => animation.cancel();
    }
    const done = () => (open ? setSettled(true) : setShown(false));
    animation.addEventListener("finish", done);
    return () => {
      animation.removeEventListener("finish", done);
      // Reopened mid-dismissal: drop the fold so it cannot hold a stale pose under the entrance.
      if (animation.playState !== "finished") animation.cancel();
    };
  }, [shown, open, progress, reduced, platform, m.height, m.minPadding, t.enter, t.exit, t.ease, t.exitEase, t.scale]);

  // The dim rides the same timeline, so a scrubbed frame is consistent with the platter's.
  useEffect(() => {
    const element = dim.current;
    if (!element || !shown || reduced) return;
    const animation = open
      ? element.animate([{ opacity: 0 }, { opacity: 1 }], { duration: t.enter, easing: "ease-out", fill: "both" })
      : element.animate([{ opacity: 1 }, { opacity: 0 }], { duration: t.exit, easing: "ease-out", fill: "both" });
    if (progress !== undefined) {
      animation.pause();
      try { animation.currentTime = clamp01(progress) * (open ? t.enter : t.exit); } catch { /* no timeline yet */ }
    }
    return () => { try { animation.cancel(); } catch { /* already gone */ } };
  }, [shown, open, progress, reduced, t.enter, t.exit]);

  // Escape from wherever focus is, and on macOS a click anywhere outside the popover.
  useEffect(() => {
    if (!open) return;
    const onKey = (event: globalThis.KeyboardEvent) => {
      if (event.key !== "Escape" || !close.current) return;
      event.preventDefault();
      close.current();
    };
    const onPointerDown = (event: globalThis.PointerEvent) => {
      const target = event.target as Node | null;
      if (platform !== "macos" || !close.current || !target || platter.current?.contains(target)) return;
      // The control that opened it owns the toggle; closing here would let its own click reopen it.
      if (target instanceof Element && target.closest('[aria-haspopup="dialog"]')) return;
      close.current();
    };
    document.addEventListener("keydown", onKey);
    document.addEventListener("pointerdown", onPointerDown, true);
    return () => {
      document.removeEventListener("keydown", onKey);
      document.removeEventListener("pointerdown", onPointerDown, true);
    };
  }, [open, platform]);

  useEffect(() => {
    // A scrubbed entrance must not move the caret: the harness seeks frames, it does not open dialogs.
    if (!open || !autoFocus || progress !== undefined) return;
    platter.current?.querySelector<HTMLElement>("button, [tabindex]:not([tabindex='-1'])")?.focus({ preventScroll: true });
  }, [open, autoFocus, progress]);

  /**
   * ChatKit fades the platter's content over `votingViewBlurWidth` at each end, which only means
   * anything once there is more than fits. Keyboard users get the scroller itself as a focus stop
   * when that happens, which is the accessible pattern for a scrollable region.
   */
  const [edges, setEdges] = useState({ start: false, end: false });
  const measure = useCallback(() => {
    const node = scroller.current;
    if (!node) return;
    const hidden = node.scrollWidth - node.clientWidth;
    const next = { start: node.scrollLeft > 0.5, end: hidden > 0.5 && node.scrollLeft < hidden - 0.5 };
    setEdges(current => (current.start === next.start && current.end === next.end ? current : next));
  }, []);
  useLayoutEffect(() => {
    measure();
    const node = scroller.current;
    if (!node || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(measure);
    observer.observe(node);
    return () => observer.disconnect();
  }, [measure, reactors.length]);
  const overflowing = edges.start || edges.end;

  if (!shown || reactors.length === 0) return null;

  // Tallies keep first-appearance order, and one counts as yours if any reaction in it is yours.
  const tallies: Array<{ key: string; reactor: TapbackReactor; count: number; own: boolean; names: string[] }> = [];
  for (const reactor of reactors) {
    const key = reactionKey(reactor);
    const found = tallies.find(entry => entry.key === key);
    if (found) { found.count += 1; found.own = found.own || Boolean(reactor.own); found.names.push(reactor.name); }
    else tallies.push({ key, reactor, count: 1, own: Boolean(reactor.own), names: [reactor.name] });
  }

  const badge = scaledBalloonGeometry(platform, m.glyphFrame);
  const fade = `linear-gradient(to right, transparent 0, #000 ${m.blurWidth}px, #000 calc(100% - ${m.blurWidth}px), transparent 100%)`;

  /**
   * Hover, focus and pressed feedback on the one cell that does something. Driven from CSS so a
   * pointer crossing the platter never touches React state, and gated on `data-state` so nothing
   * lights up while the platter is still growing under a stationary cursor. The scroller hides its
   * bar: native fades its content instead, and a bar would eat the cells' bottom edge.
   */
  const platterCss = `[data-slot="tapback-details"] [data-slot="tapback-details-cell-fill"]{opacity:0;transition:opacity 80ms linear}
[data-slot="tapback-details"][data-state="open"] [data-slot="tapback-details-remove"]:hover [data-slot="tapback-details-cell-fill"]{opacity:1}
[data-slot="tapback-details"] [data-slot="tapback-details-remove"]:focus-visible [data-slot="tapback-details-cell-fill"]{opacity:1}
[data-slot="tapback-details"] [data-slot="tapback-details-remove"]:active [data-slot="tapback-details-cell-fill"]{opacity:1}
[data-slot="tapback-details-scroller"]::-webkit-scrollbar{display:none}
@media (prefers-reduced-motion: reduce){[data-slot="tapback-details"] [data-slot="tapback-details-cell-fill"]{transition:none}}`;

  const cellBody = (reactor: TapbackReactor) => (
    <>
      <span
        aria-hidden="true"
        data-slot="tapback-details-cell-fill"
        style={{ position: "absolute", left: 0, right: 0, top: -m.topInset / 2, bottom: -m.topInset / 2, borderRadius: m.avatar / 2, background: "var(--im-td-fill, rgba(120,120,128,0.16))" }}
      />
      <span style={{ position: "relative", display: "block", width: m.avatar, height: m.avatar, marginInline: "auto" }}>
        <Avatar size={m.avatar} initials={initialsOf(reactor)} src={reactor.avatar} role="presentation" aria-hidden="true" style={{ position: "absolute", inset: 0 }} />
        {/* The badge sits on the avatar's trailing-bottom with its trail pointing away, the way a
            balloon points away from its bubble. Its 0.5 knockout rim is measured on macOS
            (`macosBalloonRim`); using it on iOS too, where a balloon over a bubble has none, is
            JUDGEMENT: an avatar is not a bubble and the badge needs the separation. */}
        <Balloon geometry={badge} own={Boolean(reactor.own)} side="right" rim style={{ position: "absolute", right: -m.glyphFrame * 0.1, bottom: -m.glyphFrame * 0.1 }}>
          <TapbackGlyph
            type={reactor.emoji ? undefined : reactor.reaction ?? "love"}
            emoji={reactor.emoji}
            size={badge.glyph}
            onAccent={Boolean(reactor.own)}
            style={{ marginTop: reactor.emoji ? 0 : 2 * (badge.glyphOffsetY ?? 0) }}
          />
        </Balloon>
      </span>
      <span
        data-slot="tapback-details-name"
        style={{
          position: "relative", display: "block", marginTop: m.avatarToText, width: m.cellWidth, height: m.labelHeight,
          lineHeight: `${m.labelHeight}px`, fontSize: m.nameFontSize, fontWeight: 400, letterSpacing: 0,
          color: "var(--im-td-label, rgba(0,0,0,0.498))", textAlign: "center",
          overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap",
        }}
      >
        {shortNameOf(reactor)}
      </span>
    </>
  );

  const cells = reactors.map((reactor, index) => {
    // ChatKit's own accessibility string is "%@ reacted with %@"; the action that takes one back is
    // "Remove Tapback".
    const reacted = `${reactor.name} reacted with ${reactionName(reactor)}`;
    const box: CSSProperties = { position: "relative", display: "block", width: m.cellWidth, textAlign: "center" };
    return (
      <li key={reactor.id} data-slot="tapback-details-cell" data-own={reactor.own || undefined}
        style={{ listStyle: "none", margin: 0, padding: 0, marginLeft: index === 0 ? 0 : m.itemSpacing, flex: "0 0 auto" }}>
        {reactor.own && onRemove ? (
          <button type="button" data-slot="tapback-details-remove" aria-label={`${reacted}. Remove Tapback`} onClick={() => onRemove(reactor)}
            // The ring is inset: the scroller has to clip on the cross axis, so an outset one is cut.
            style={{ ...box, border: 0, background: "transparent", padding: 0, margin: 0, cursor: "default", font: "inherit", color: "inherit", outlineOffset: -2 }}>
            {cellBody(reactor)}
          </button>
        ) : (
          <span data-slot="tapback-details-person" role="img" aria-label={reacted} style={box}>
            {cellBody(reactor)}
          </span>
        )}
      </li>
    );
  });

  // The platter hugs its content and only then runs into `maxWidth`, which is what ChatKit's pair of
  // a max width and a minimum padding from the presenting edge describes. On macOS an absolutely
  // positioned box with an auto width already shrink-wraps; on iOS a centring row does it instead,
  // because setting both `left` and `right` would stretch it.
  const platterStyle: CSSProperties = {
    ...(platform === "ios"
      ? { position: "relative", maxWidth: `min(${m.maxWidth}px, 100%)` }
      : { position: "absolute", left, top, maxWidth: m.maxWidth }),
    boxSizing: "border-box",
    height: m.height,
    borderRadius: m.radius,
    paddingTop: m.topInset,
    paddingInline: m.paddingX,
    display: "flex",
    alignItems: "center",
    background: "var(--im-td-platter, #ededef)",
    boxShadow: "var(--im-td-shadow, 0 6px 24px rgba(0,0,0,0.10)), inset 0 0 0 0.5px var(--im-td-rim, rgba(255,255,255,0.55))",
    transformOrigin: transformOrigins[origin],
    // Nothing is clickable while it folds away, so a dismissal cannot pick a cell by accident.
    pointerEvents: closing ? "none" : undefined,
  };

  const inside = (
    <>
      <span id={`${id}-title`} style={{ position: "absolute", width: 1, height: 1, margin: -1, padding: 0, overflow: "hidden", clipPath: "inset(50%)", whiteSpace: "nowrap", border: 0 }}>Tapback Details</span>

      {/* The count and the people scroll together, which is what one fade at each end of the platter
          (`votingViewBlurWidth`) describes; only the close button is pinned. */}
      <div ref={scroller} data-slot="tapback-details-scroller"
        role={overflowing ? "group" : undefined} aria-label={overflowing ? "Reactions" : undefined} tabIndex={overflowing ? 0 : undefined}
        style={{
          flex: "0 1 auto", minWidth: 0, overflowX: "auto", overflowY: "hidden", scrollbarWidth: "none",
          WebkitMaskImage: overflowing ? fade : undefined, maskImage: overflowing ? fade : undefined,
        }}>
        <div style={{ display: "flex", alignItems: "center", width: "max-content" }}>
          {/* ChatKit calls the count the expanded tally: one per reaction kind with its total beside
              it at `votingViewTallyLabelSpacing` 0, named with ChatKit's own
              ACCESSIBILITY_EXPANDED_TAPBACK_FORMAT, "%lu %@ reactions from %@". */}
          <div data-slot="tapback-details-tallies" style={{ display: "flex", alignItems: "center", flex: "0 0 auto", marginRight: m.itemSpacing }}>
            {tallies.map((entry, index) => (
              <span key={entry.key} data-slot="tapback-details-tally" role="img"
                aria-label={`${entry.count} ${reactionName(entry.reactor)} ${entry.count === 1 ? "reaction" : "reactions"} from ${entry.names.join(", ")}`}
                style={{ display: "inline-flex", alignItems: "center", marginLeft: index === 0 ? 0 : m.itemSpacing }}>
                {/* The tally is the bare glyph in ChatKit's `votingViewExpandedTally` box, not a
                    balloon: a balloon's neck and trail point at the bubble it belongs to, and a
                    summary has no bubble. */}
                <span aria-hidden="true" style={{ width: m.tally, height: m.tally, display: "inline-flex", alignItems: "center", justifyContent: "center" }}>
                  <TapbackGlyph type={entry.reactor.emoji ? undefined : entry.reactor.reaction ?? "love"} emoji={entry.reactor.emoji} size={m.tally} />
                </span>
                <span aria-hidden="true" data-slot="tapback-details-count"
                  style={{ marginLeft: m.tallyLabelSpacing, fontSize: m.countFontSize, lineHeight: 1, fontWeight: 400, letterSpacing: 0, color: "var(--im-td-label, rgba(0,0,0,0.498))" }}>
                  {entry.count}
                </span>
              </span>
            ))}
          </div>
          <ul data-slot="tapback-details-list" style={{ display: "flex", alignItems: "center", margin: 0, padding: 0, listStyle: "none" }}>
            {cells}
          </ul>
        </div>
      </div>

      {onClose && (
        <button type="button" data-slot="tapback-details-close" aria-label="Close" onClick={onClose}
          style={{
            flex: "0 0 auto", marginLeft: m.closeLeftPadding, width: m.closeSize, height: m.closeSize,
            borderRadius: m.closeSize / 2, border: 0, padding: 0, cursor: "default",
            display: "flex", alignItems: "center", justifyContent: "center",
            background: "var(--im-td-fill, rgba(120,120,128,0.16))", color: "var(--im-td-label, rgba(0,0,0,0.498))",
            outlineOffset: -2,
          }}>
          {/* The cross is 0.394 of its button, the ratio between the 17.33 cross and the Ø44 glass
              circle measured on `newmsg-light.png` in `ios-new-message-sheet.tsx`. */}
          <svg aria-hidden="true" width={m.closeSize * 0.394} height={m.closeSize * 0.394} viewBox="0 0 12 12" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round">
            <path d="M1 1 11 11M11 1 1 11" />
          </svg>
        </button>
      )}
    </>
  );

  // macOS: the popover is the root, positioned by the caller against the message it belongs to.
  if (platform === "macos") {
    return (
      <div ref={platter} data-slot="tapback-details" data-platform="macos" data-state={state}
        role="dialog" aria-labelledby={`${id}-title`}
        className={cn("select-none", darkVars, className)}
        style={{ fontFamily: fontStack, zIndex: 40, ...lightVars, ...platterStyle, ...style } as CSSProperties}
        {...props}>
        <style>{platterCss}</style>
        {inside}
      </div>
    );
  }

  // iOS: the platter comes up over the dimmed conversation, so the dim is the root.
  return (
    <div data-slot="tapback-details" data-platform="ios" data-state={state}
      className={cn("absolute inset-0 z-40 select-none", darkVars, className)}
      style={{ fontFamily: fontStack, ...lightVars, ...style } as CSSProperties}
      {...props}>
      <style>{platterCss}</style>
      {/* The dim is the 20% black measured on `newmsg-light.png`; tapping it dismisses, as a sheet does. */}
      <div ref={dim} data-slot="tapback-details-dim" aria-hidden="true" onClick={onClose}
        style={{ position: "absolute", inset: 0, background: "var(--im-td-dim, rgba(0,0,0,0.2))" }} />
      <div style={{ position: "absolute", left: m.minPadding, right: m.minPadding, bottom: m.minPadding, display: "flex", justifyContent: "center" }}>
        <div ref={platter} data-slot="tapback-details-platter" role="dialog" aria-modal="true" aria-labelledby={`${id}-title`} style={platterStyle}>
          {inside}
        </div>
      </div>
    </div>
  );
}

"use client";

import type { ComponentProps, CSSProperties } from "react";
import { cn } from "@/lib/utils";
import { usePlatform, type Platform } from "@/components/imessage/platform";
import { bodyClipPath, tailBox, tailPath, tailSeamOverlap } from "@/components/imessage/bubble-shape";
import { bubbleMetrics, palettes } from "@/components/imessage/tokens";

/**
 * The "someone is typing" balloon.
 *
 * NOT MEASURED. No capture in `references/` shows a typing indicator: every iOS and macOS still, both
 * 60 fps recordings and every motion contact sheet were checked on 2026-09-08 and none contains one.
 *
 * What is anchored to a capture is the balloon itself. It is an incoming bubble, so it takes the
 * measured incoming geometry rather than numbers of its own: the one-line body height
 * (2 x paddingY + lineHeight), the measured corner radius, the traced tail on the bottom-left, and
 * the incoming screen-space fill, all read from `bubbleMetrics` and `bubble-shape` so it can never
 * drift from a real bubble. The message list insets it by the same measured edge inset as a bubble.
 *
 * Only the dots are invented: diameter, spacing and the 1.2 s pulse are provisional, and the dot
 * colour reuses the platform's measured secondary-label gray because no capture shows the real one.
 * The pulse is a CSS animation with negative delays, so every dot is inside its active phase at every
 * time: pausing `document.getAnimations()` and setting `currentTime` pins the balloon to a frame, and
 * that frozen frame is the one the animation shows while running.
 */
export type TypingIndicatorMetrics = {
  /** Body box, both derived from the measured one-line incoming bubble. */
  width: number;
  height: number;
  /** Provisional: dot diameter and the gap between two dots. */
  dot: number;
  dotGap: number;
  /** Measured bubble radius and tail scale, carried through so the balloon matches a bubble exactly. */
  radius: number;
  tailScale: number;
};

/** The only free numbers in the balloon. Everything else falls out of the measured bubble. */
const dotSizes: Record<Platform, { dot: number; dotGap: number }> = {
  ios: { dot: 10, dotGap: 5 },
  macos: { dot: 7, dotGap: 3.5 },
};

function metricsFor(platform: Platform): TypingIndicatorMetrics {
  const b = bubbleMetrics[platform];
  const { dot, dotGap } = dotSizes[platform];
  return {
    width: 2 * b.paddingX + 3 * dot + 2 * dotGap,
    height: 2 * b.paddingY + b.lineHeight,
    dot,
    dotGap,
    radius: b.radius,
    tailScale: b.tailScale,
  };
}

export const typingIndicatorMetrics: Record<Platform, TypingIndicatorMetrics> = {
  ios: metricsFor("ios"),
  macos: metricsFor("macos"),
};

/** Dot loop and the stagger between two dots. Provisional; no capture times the pulse. */
export const typingLoopMs = 1200;
export const typingStaggerMs = 200;

/**
 * The delays are negative so a dot is never in its "before" phase: at time 0 dot 1 is already
 * `typingStaggerMs` into the loop instead of sitting on its unanimated base style, which is what made
 * a frozen frame at t = 0 disagree with the running animation.
 */
const dotDelayMs = (index: number) => index * typingStaggerMs - typingLoopMs;

const keyframes = `
@keyframes im-typing-dot { 0%, 60%, 100% { opacity: .35; transform: translateY(0) scale(1); } 30% { opacity: 1; transform: translateY(-1px) scale(1.06); } }
[data-slot="typing-indicator"] > span[data-dot] { animation: im-typing-dot ${typingLoopMs}ms ease-in-out infinite both; }
@media (prefers-reduced-motion: reduce) { [data-slot="typing-indicator"] > span[data-dot] { animation: none; opacity: .7; } }
`;

export type TypingIndicatorProps = ComponentProps<"div"> & {
  label?: string;
  /** The balloon is always the last thing in the transcript, so it carries a tail like any last bubble. */
  tail?: boolean;
  /**
   * Screen-space y of the body's bottom edge, in px, for the position-dependent incoming fill. The
   * message list tracks this element too, so it is only needed outside a list: pass it to keep a macOS
   * dark balloon exactly on the incoming ramp; the iOS grays are flat and never need it.
   */
  screenBottom?: number;
  platform?: Platform;
};

export function TypingIndicator({
  label = "Someone is typing", tail = true, screenBottom, platform: platformProp, className, style, ...props
}: TypingIndicatorProps) {
  const contextPlatform = usePlatform();
  const platform = platformProp ?? contextPlatform;
  const t = typingIndicatorMetrics[platform];
  const tailW = tailBox.width * t.tailScale;
  const tailH = tailBox.height * t.tailScale;
  const hang = tailBox.hang * t.tailScale;

  // Same screen-space fill an incoming bubble paints: one gradient in screen coordinates, anchored to
  // the body's bottom so the body and the tail (which hangs `hang` lower) share the same image. The
  // fallbacks only matter when the balloon is used outside a palette; inside one they never apply.
  const screen = `var(--im-screen-h, ${palettes[platform].light.incoming.screenHeight}px)`;
  const bottomVar = screenBottom === undefined ? `var(--bubble-bottom, calc(${screen} * 0.55))` : `${screenBottom}px`;
  const fill: CSSProperties = {
    backgroundImage: "linear-gradient(var(--im-fill-top), var(--im-fill-bottom))",
    backgroundSize: `100% ${screen}`,
    backgroundRepeat: "no-repeat",
    backgroundColor: "var(--im-fill-bottom)",
  };
  const bodyFill: CSSProperties = { ...fill, backgroundPosition: `0 calc(100% + (${screen} - ${bottomVar}))` };
  const tailFill: CSSProperties = { ...fill, backgroundPosition: `0 calc(100% + (${screen} - ${bottomVar} - ${hang}px))` };
  const vars = {
    "--im-fill-top": "var(--im-gray-top, #e9e9eb)",
    "--im-fill-bottom": "var(--im-gray-bottom, #e9e9eb)",
    ...(screenBottom === undefined ? {} : { "--bubble-bottom": `${screenBottom}px` }),
  } as CSSProperties;

  return (
    <div role="status" aria-label={label} data-slot="typing-indicator" data-platform={platform}
      className={cn("relative flex shrink-0 items-center justify-center", className)}
      style={{ width: t.width, height: t.height, gap: t.dotGap, ...vars, ...style }} {...props}>
      <style>{keyframes}</style>
      {/* The fill sits behind the dots so clipping the tail corner never clips a dot. */}
      <div aria-hidden="true" data-slot="fill" className="pointer-events-none absolute inset-0"
        style={{ borderRadius: t.radius, clipPath: tail ? bodyClipPath("left", t.tailScale, tailSeamOverlap[platform]) : undefined, ...bodyFill }} />
      {tail && <div aria-hidden="true" data-slot="tail" className="pointer-events-none absolute" style={{
        left: 0, bottom: -hang, width: tailW, height: tailH + hang, clipPath: `path("${tailPath("left", t.tailScale)}")`, ...tailFill,
      }} />}
      {[0, 1, 2].map(index => (
        <span key={index} aria-hidden="true" data-dot={index} className="relative block rounded-full"
          style={{ width: t.dot, height: t.dot, background: "var(--im-secondary, #8a8a8e)", animationDelay: `${dotDelayMs(index)}ms` }} />
      ))}
    </div>
  );
}

"use client";

import type { ComponentProps, ReactNode } from "react";
import { cn } from "@/lib/utils";
import { usePlatform, type Platform } from "@/components/imessage/platform";
import { fontStack } from "@/components/imessage/tokens";

/**
 * The centered timestamp that separates conversation history.
 *
 * Measured (references/ios/captures/conv3-light.png @3x, references/macos/captures/conversation-pane-light-partial.png @2x):
 * - iOS: two lines ("iMessage" then "Today 1:25 AM"), 11pt on a 14pt pitch, #8a8a8e. The service line and
 *   "Today" render at weight 500; the time is regular. The first bubble sits 7.6pt below the second line box.
 * - macOS: one line, 9pt on an 11pt pitch (ink 63 x 9pt for "Today 1:47 AM"; SPEC.md's 11pt is 20% too wide),
 *   "Today" at weight **500**, #808080 light / #9a9a9a dark. The first bubble's body top sits 6.0 below the
 *   header's ink bottom. Weight 500 is measured, not assumed: rendering the string at 9pt/2x and comparing
 *   the ten ink runs of `conversation-pane-light-partial.png` (normalised to the "T", pt from its left edge:
 *   0.00-10.50, 11.00-16.00, 16.50-21.00, 22.00-26.50, 30.00-33.00, 34.50-36.00, 37.00-42.50, 43.00-47.50,
 *   49.50-55.50, 56.50-63.00) puts weight 500 within one device px on all ten and on the 63.00 total, where
 *   600 runs 0.5 wide on seven of them and 63.50 overall, and 400 is 0.5 narrow on eight. Same weight as iOS.
 *   `gapBelow` is 6 even though the box wants 5.7: at 9pt/2x Blink paints the ink at `round(box top) + 2`,
 *   so 5.7 and 6 put the ink on the same device row, and 6 is the number the capture states.
 *
 * Only the header that opens a conversation carries the service name; a header inserted mid-list after an
 * hour-long gap is one line and sits in a gap of its own. Measured in `dateheader-mid-light.png`: the
 * previous body bottom is at 605.0, the header ink runs 621.0 to 631.33, the next bubble top is 639.0.
 * Chrome snaps a baseline to whole CSS px, so the ink can land a third of a point off the capture even
 * when the box is exactly right; the gaps below are the box positions, not the rasterised ink.
 */
export type DateSeparatorVariant = "first" | "mid";
export type DateSeparatorMetrics = {
  fontSize: number; lineHeight: number; weight: number; dayWeight: number;
  /** Space between the previous row and the line box, and between the line box and the next row. */
  gapAbove: number; gapBelow: number;
  /** The same two gaps for a mid-list header, which has no bubble above it to lean on. */
  midGapAbove: number; midGapBelow: number;
};

export const dateSeparatorMetrics: Record<Platform, DateSeparatorMetrics> = {
  ios: { fontSize: 11, lineHeight: 14, weight: 400, dayWeight: 500, gapAbove: 0, gapBelow: 7.6, midGapAbove: 13.33, midGapBelow: 6.67 },
  // No macOS capture of a mid-list header yet: it reuses the between-cluster gap above and the measured 6 below.
  macos: { fontSize: 9, lineHeight: 11, weight: 400, dayWeight: 500, gapAbove: 0, gapBelow: 6, midGapAbove: 11.5, midGapBelow: 6 },
};

export type DateLabel = {
  /** "Today", "Yesterday", a weekday name, or "Sep 8, 2026". */
  day: string;
  /** "1:25 AM" (narrow no-break space before the period, as Apple renders it). */
  time: string;
  /** " " for relative days, " at " before absolute dates. */
  joiner: " " | " at ";
  text: string;
  iso: string;
};

const WEEKDAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

function startOfDay(d: Date) { return new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime(); }

export function formatClockTime(value: Date | number): string {
  const d = new Date(value);
  const hours = d.getHours();
  const h12 = hours % 12 || 12;
  return `${h12}:${String(d.getMinutes()).padStart(2, "0")} ${hours < 12 ? "AM" : "PM"}`;
}

/** Apple's relative date style: Today / Yesterday / weekday within a week / "Sep 8, 2026 at 1:25 AM". */
export function formatDateLabel(value: Date | number, now: Date | number = Date.now()): DateLabel {
  const d = new Date(value);
  const days = Math.round((startOfDay(new Date(now)) - startOfDay(d)) / 86_400_000);
  const time = formatClockTime(d);
  let day: string;
  let joiner: DateLabel["joiner"] = " ";
  if (days === 0) day = "Today";
  else if (days === 1) day = "Yesterday";
  else if (days > 1 && days < 7) day = WEEKDAYS[d.getDay()];
  else { day = `${MONTHS[d.getMonth()]} ${d.getDate()}, ${d.getFullYear()}`; joiner = " at "; }
  return { day, time, joiner, text: `${day}${joiner}${time}`, iso: d.toISOString() };
}

export type DateSeparatorProps = Omit<ComponentProps<"div">, "children"> & {
  /** The moment the header describes. Omit to render `children` verbatim. */
  date?: Date | number;
  /** Reference time for "Today"/"Yesterday"; defaults to the current time. */
  now?: Date | number;
  /** iOS shows the conversation's service ("iMessage", "Text Message") above the date. Ignored on macOS. */
  service?: ReactNode;
  /** "first" opens the conversation; "mid" is inserted after an hour-long gap and gets its own spacing. */
  variant?: DateSeparatorVariant;
  platform?: Platform;
  /** Custom label used instead of the formatted date. */
  children?: ReactNode;
  dateTime?: string;
};

export function DateSeparator({ date, now, service, variant = "first", platform: platformProp, children, dateTime, className, style, ...props }: DateSeparatorProps) {
  const contextPlatform = usePlatform();
  const platform = platformProp ?? contextPlatform;
  const m = dateSeparatorMetrics[platform];
  const mid = variant === "mid";
  const label = date === undefined ? undefined : formatDateLabel(date, now);
  return (
    <div data-slot="date-separator" data-platform={platform} data-variant={variant} className={cn("text-center", className)}
      style={{ fontFamily: fontStack, fontSize: m.fontSize, lineHeight: `${m.lineHeight}px`, fontWeight: m.weight, letterSpacing: 0, color: "var(--im-secondary, #8a8a8e)", paddingTop: mid ? m.midGapAbove : m.gapAbove, paddingBottom: mid ? m.midGapBelow : m.gapBelow, ...style }} {...props}>
      {platform === "ios" && !mid && service ? <div data-slot="service" style={{ fontWeight: m.dayWeight }}>{service}</div> : null}
      <time dateTime={dateTime ?? label?.iso}>
        {children ?? (label ? <><span data-slot="day" style={{ fontWeight: m.dayWeight }}>{label.day}</span>{label.joiner}{label.time}</> : null)}
      </time>
    </div>
  );
}

"use client";

import type { ComponentProps, ReactNode } from "react";
import { cn } from "@/lib/utils";
import { usePlatform, type Platform } from "@/components/imessage/platform";
import { fontStack } from "@/components/imessage/tokens";

/**
 * The link card Messages shows for a URL without rich metadata: a gray rounded card with the hostname on
 * the left and a Safari compass disc on the right. With `media` (or an `image`) it becomes the rich card:
 * the image on top, then the title and hostname.
 *
 * macOS metrics are measured from the apple.com card in `references/macos/captures/conversation-pane-light.png`
 * and `conversation-pane-dark-2.png` (630x640 pt @2x, so every pixel pair is one point):
 *
 * | Part | Measurement |
 * |---|---|
 * | Card | 140 x 60 (x 470-610, y 179-239 in the light capture), radius 14 |
 * | Fill | #e9e9eb light / #3b3b3d dark (the incoming gray) |
 * | Hostname | "apple.com" ink 49.5 x 10, left ink edge 10 in from the card, baseline 35 below the card top |
 * | Host colour | #808084 light / #a6a6a9 dark |
 * | Disc | 24 x 24, right edge 16 in from the card's right edge (centre 28 in), #757576 light / #a7a7a7 dark |
 * | Content shift | hostname baseline and disc centre both sit 1 below the card's vertical centre |
 *
 * The corner is really one of Apple's continuous corners: a superellipse of radius 17.375 and exponent
 * 2.5 fits the light capture to 0.09 px, where the best circle (14.3) is off by up to 0.27 pt. Radius 14
 * keeps the card on the same circular geometry as the macOS bubble, which is within that error.
 *
 * There is **no native capture of the iOS card or of either rich variant**. iOS reuses what iOS itself
 * measures - the 19 bubble radius, the incoming gray (#e9e9eb / #262629), the secondary label
 * (#8a8a8e / #8d8d93), the 280.5 max bubble width and the 13.85/10 bubble padding - and its card box,
 * hostname size and disc size are the macOS ones re-proportioned for 17pt type. Treat those as a
 * considered guess, not a measurement.
 */
export type LinkPreviewMetrics = {
  width: number;
  height: number;
  radius: number;
  hostSize: number;
  hostLineHeight: number;
  padStart: number;
  disc: number;
  /** Distance from the card's right edge to the disc's right edge. */
  discInsetEnd: number;
  /** Native draws the hostname and disc this much below the card's vertical center. */
  contentShift: number;
  richWidth: number;
  titleSize: number;
  titleLineHeight: number;
  richPadX: number;
  richPadY: number;
};

export const linkPreviewMetrics: Record<Platform, LinkPreviewMetrics> = {
  macos: { width: 140, height: 60, radius: 14, hostSize: 10, hostLineHeight: 12, padStart: 10, disc: 24, discInsetEnd: 16, contentShift: 1, richWidth: 280, titleSize: 12, titleLineHeight: 15, richPadX: 12.5, richPadY: 8 },
  ios: { width: 198, height: 85, radius: 19, hostSize: 14, hostLineHeight: 17, padStart: 14, disc: 34, discInsetEnd: 23, contentShift: 1.4, richWidth: 280.5, titleSize: 17, titleLineHeight: 20, richPadX: 13.85, richPadY: 10 },
};

export type LinkPreviewProps = Omit<ComponentProps<"a">, "title" | "children" | "href" | "media"> & {
  href: string;
  title?: string;
  description?: string;
  /** Hostname label; defaults to the URL's host without "www.". */
  host?: string;
  /** Rich card image slot (any node, e.g. an <img>). */
  media?: ReactNode;
  /** Convenience for the rich card: an image URL rendered in the media slot. */
  image?: string;
  platform?: Platform;
};

function SafariDisc({ size }: { size: number }) {
  return (
    <svg aria-hidden="true" data-slot="safari-icon" viewBox="0 0 24 24" width={size} height={size} style={{ display: "block", color: "var(--im-card-icon)" }}>
      <circle cx="12" cy="12" r="12" fill="currentColor" />
      <g transform="rotate(45 12 12)">
        <path d="M12 3.6 L14.2 12 L12 20.4 L9.8 12 Z" fill="var(--im-card)" stroke="var(--im-card)" strokeWidth="0.9" strokeLinejoin="round" />
        <circle cx="12" cy="12" r="1.5" fill="currentColor" />
      </g>
    </svg>
  );
}

/**
 * macOS values are measured off the apple.com card. iOS swaps in its own measured grays - the incoming
 * bubble (#e9e9eb / #262629) and the secondary label (#8a8a8e / #8d8d93) - because #3b3b3d is the macOS
 * incoming gray and reads wrong next to iOS bubbles. The Safari disc keeps the macOS gray: nothing on
 * iOS measures it.
 */
const themeVars: Record<Platform, string> = {
  macos: "[--im-card:#e9e9eb] [--im-card-fg:#808084] [--im-card-icon:#757576] [--im-card-title:#000000] dark:[--im-card:#3b3b3d] dark:[--im-card-fg:#a6a6a9] dark:[--im-card-icon:#a7a7a7] dark:[--im-card-title:#ffffff]",
  ios: "[--im-card:#e9e9eb] [--im-card-fg:#8a8a8e] [--im-card-icon:#757576] [--im-card-title:#000000] dark:[--im-card:#262629] dark:[--im-card-fg:#8d8d93] dark:[--im-card-icon:#a7a7a7] dark:[--im-card-title:#ffffff]",
};

export function LinkPreview({ href, title, description, host, media, image, platform: platformProp, className, style, target, rel, ...props }: LinkPreviewProps) {
  const contextPlatform = usePlatform();
  const platform = platformProp ?? contextPlatform;
  const m = linkPreviewMetrics[platform];
  let url: URL;
  try { url = new URL(href); } catch { throw new Error("LinkPreview requires an absolute HTTP(S) URL."); }
  if (!["https:", "http:"].includes(url.protocol)) throw new Error("LinkPreview requires an absolute HTTP(S) URL.");
  const hostname = host ?? url.hostname.replace(/^www\./, "");
  // A plain <img>: registry components stay framework-agnostic (pass `media` to use next/image).
  // eslint-disable-next-line @next/next/no-img-element
  const mediaNode = media ?? (image ? <img src={image} alt="" style={{ display: "block", width: "100%", height: "100%", objectFit: "cover" }} /> : null);
  const rich = Boolean(mediaNode);
  const shared = { fontFamily: fontStack, letterSpacing: 0, color: "var(--im-card-fg)", background: "var(--im-card)", borderRadius: m.radius, textDecoration: "none", ...style };
  if (!rich) {
    return (
      <a href={url.href} target={target} rel={rel ?? (target === "_blank" ? "noopener noreferrer" : undefined)} data-slot="link-preview" data-variant="compact" data-platform={platform}
        className={cn("relative block overflow-hidden focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-blue-500", themeVars[platform], className)}
        style={{ ...shared, width: m.width, height: m.height, boxSizing: "border-box" }} aria-label={title ? `${title}, ${hostname}` : hostname} {...props}>
        <span data-slot="host" className="absolute truncate" style={{ left: m.padStart, right: m.discInsetEnd + m.disc + m.padStart / 2, top: (m.height - m.hostLineHeight) / 2 + m.contentShift, fontSize: m.hostSize, lineHeight: `${m.hostLineHeight}px` }}>{hostname}</span>
        <span className="absolute" style={{ right: m.discInsetEnd, top: (m.height - m.disc) / 2 + m.contentShift, width: m.disc, height: m.disc }}><SafariDisc size={m.disc} /></span>
      </a>
    );
  }
  return (
    <a href={url.href} target={target} rel={rel ?? (target === "_blank" ? "noopener noreferrer" : undefined)} data-slot="link-preview" data-variant="rich" data-platform={platform}
      className={cn("block max-w-full overflow-hidden focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-blue-500", themeVars[platform], className)}
      style={{ ...shared, width: m.richWidth }} {...props}>
      <div data-slot="media" className="overflow-hidden" style={{ aspectRatio: "1.91 / 1", background: "color-mix(in srgb, var(--im-card-fg) 20%, var(--im-card))" }}>{mediaNode}</div>
      <div data-slot="meta" style={{ padding: `${m.richPadY}px ${m.richPadX}px` }}>
        {title && <p data-slot="title" className="m-0 line-clamp-2" style={{ fontSize: m.titleSize, lineHeight: `${m.titleLineHeight}px`, fontWeight: 600, color: "var(--im-card-title)" }}>{title}</p>}
        {description && <p data-slot="description" className="m-0 line-clamp-2" style={{ fontSize: m.hostSize, lineHeight: `${m.hostLineHeight}px`, marginTop: 2 }}>{description}</p>}
        <p data-slot="host" className="m-0 truncate" style={{ fontSize: m.hostSize, lineHeight: `${m.hostLineHeight}px`, marginTop: title || description ? 2 : 0 }}>{hostname}</p>
      </div>
    </a>
  );
}

"use client";

import { useId, type ComponentProps, type CSSProperties, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import { bubblePath, tailBox } from "@/components/imessage/bubble-shape";
import { usePlatform, type Platform } from "@/components/imessage/platform";

/**
 * A file attachment message: the document card Messages draws instead of a text bubble.
 *
 * macOS numbers are measured from `references/macos/captures/attachment-not-delivered-dark-2x.png`
 * (960×640 @2x, so every pixel pair is one point):
 *
 * | Part | Measurement |
 * |---|---|
 * | Card | body 275 × 88.75 (x 17–292, y 5.5–94.4 in the crop), plus the 0.7-scale tail hanging 4.6 |
 * | Corner | best circle 14.5 (rmse 0.28 px on both top corners); the earlier 18 was off by 2.7 px |
 * | Fill | #3b3b3d dark (the incoming gray — file cards are gray in both directions) |
 * | Icon | 38.6 × 51.6 page at (22.7, 18.6) inside the card, 14 fold, 2 corner radius |
 * | Filename | 12pt semibold #f7f7f7 tracked −0.5 (ink 90.0 × 11.0, x-height 6.6), ink left 84.5, baseline 43.5 |
 * | Subtitle | 11pt #a6a6a9 tracked −0.45 (ink 128.5 × 10.0), ink left 84.0, baseline 58.5 |
 * | Failed | #eb534e ring, outer Ø 16.5, stroke 1.2; left edge 9.5 past the card, centre at 50.25 (body centre + 0.4) |
 * | Not Delivered | 10pt semibold #eb534e, ink 60.0 × 7.0, right ink edge 11.0 past the card's trailing edge |
 *
 * The corner is really a continuous one (superellipse radius 17.4, exponent 2.5, rmse 0.08 px), the same
 * shape the compact link card shows. `bubblePath` draws circular arcs so the card takes the best circle.
 * The badge and the label live in `ios-notices.tsx`; the numbers above are what they have to hit.
 *
 * `titleTop` and `subtitleTop` are the two baselines minus Chrome's baseline offset inside their line
 * boxes (12 for 12/15, 11 for 11/13), so the ink lands on the native baseline whenever the card sits on
 * whole points. A host that offsets the card by half a point (`/lab/ios-screens?scene=attachment` does,
 * through a `translateY(0.5px)`) puts the whole subtree in a composited layer whose text snaps a point at
 * a time, so every glyph and the icon land half a point off; that is the host's, not the card's.
 *
 * The iOS variant is that layout re-proportioned for the 17/13pt type world. **It is not verified
 * against a capture** — no iOS attachment frame exists in `references/` — so treat its numbers as a
 * considered guess, not a measurement.
 */

const font = "-apple-system, BlinkMacSystemFont, sans-serif";

/**
 * macOS is measured off the dark crop. iOS keeps the same shape but takes its own measured grays, the
 * incoming bubble (#e9e9eb / #262629) and the secondary label (#8a8a8e / #8d8d93): #3b3b3d is the macOS
 * incoming gray and reads wrong beside iOS bubbles.
 */
const vars: Record<Platform, string> = {
  macos:
    "[--im-att-fill:#e9e9eb] [--im-att-title:#000000] [--im-att-subtitle:#6e6e6d] " +
    "dark:[--im-att-fill:#3b3b3d] dark:[--im-att-title:#f7f7f7] dark:[--im-att-subtitle:#a6a6a9]",
  ios:
    "[--im-att-fill:#e9e9eb] [--im-att-title:#000000] [--im-att-subtitle:#8a8a8e] " +
    "dark:[--im-att-fill:#262629] dark:[--im-att-title:#ffffff] dark:[--im-att-subtitle:#8d8d93]",
};

type AttachmentMetrics = {
  width: number; height: number; radius: number; tailScale: number;
  iconWidth: number; iconHeight: number; iconLeft: number; iconTop: number;
  textLeft: number; textRight: number;
  titleSize: number; titleLine: number; titleTop: number; titleTracking: number;
  subtitleSize: number; subtitleLine: number; subtitleTop: number; subtitleTracking: number;
};

/** macOS is measured; iOS is the same layout scaled to 17/13pt type and is unverified. */
export const attachmentMetrics: Record<Platform, AttachmentMetrics> = {
  macos: {
    width: 275, height: 88.75, radius: 14.5, tailScale: 0.7,
    iconWidth: 38.6, iconHeight: 51.6, iconLeft: 22.7, iconTop: 18.6,
    textLeft: 83.75, textRight: 12,
    titleSize: 12, titleLine: 15, titleTop: 31.5, titleTracking: -0.5,
    subtitleSize: 11, subtitleLine: 13, subtitleTop: 47.5, subtitleTracking: -0.45,
  },
  ios: {
    width: 280.5, height: 100, radius: 19, tailScale: 1,
    iconWidth: 44, iconHeight: 58, iconLeft: 18, iconTop: 21,
    textLeft: 74, textRight: 14,
    titleSize: 17, titleLine: 22, titleTop: 31, titleTracking: 0,
    subtitleSize: 13, subtitleLine: 16, subtitleTop: 53, subtitleTracking: 0,
  },
};

/**
 * The page with a folded corner that macOS draws for a generic document, traced off the same crop.
 *
 * The user space is the page's own 38.6 × 51.6 box. Its top-right corner is cut at 45° over the last 14,
 * and the flap folds back onto the page as the triangle (24.6,0)–(38.6,14)–(24.6,14). Sampling the crop on
 * a grid gives a flat #f5f5f5 body shading one level per point of distance along the (1,−1) diagonal, down
 * to about #e0e0e0 at the cut; the flap runs the other way, #e7e7e7 at the cut up to #ffffff about 4.6 in,
 * and drops a short shadow along its two straight edges. The page sits on a soft shadow of its own (peak
 * alpha ≈ 0.3 at the bottom edge, gone by 3 out).
 *
 * `preserveAspectRatio="none"` because the drawing is the box: any letterboxing would offset the whole
 * page by a fraction of a point against the card.
 */
function DocumentIcon({ width, height }: { width: number; height: number }) {
  const id = useId();
  return (
    <svg aria-hidden="true" width={width} height={height} viewBox="0 0 38.6 51.6" preserveAspectRatio="none"
      style={{ display: "block", overflow: "visible", filter: "drop-shadow(0 0.45px 1.2px rgba(0,0,0,0.42))" }}>
      <defs>
        {/* Both ramps run along the page's (1,−1) diagonal, in the page's own coordinates. */}
        <linearGradient id={`${id}-page`} gradientUnits="userSpaceOnUse" x1="10.74" y1="14.28" x2="25.02" y2="0">
          <stop offset="0" stopColor="#f5f5f5" />
          <stop offset="1" stopColor="#e0e0e0" />
        </linearGradient>
        <linearGradient id={`${id}-flap`} gradientUnits="userSpaceOnUse" x1="31.6" y1="7" x2="28.35" y2="10.25">
          <stop offset="0" stopColor="#e7e7e7" />
          <stop offset="1" stopColor="#ffffff" />
        </linearGradient>
        <linearGradient id={`${id}-crease-x`} gradientUnits="userSpaceOnUse" x1="21.6" y1="0" x2="24.6" y2="0">
          <stop offset="0" stopColor="#000000" stopOpacity="0" />
          <stop offset="1" stopColor="#000000" stopOpacity="0.09" />
        </linearGradient>
        <linearGradient id={`${id}-crease-y`} gradientUnits="userSpaceOnUse" x1="0" y1="14" x2="0" y2="16">
          <stop offset="0" stopColor="#000000" stopOpacity="0.06" />
          <stop offset="1" stopColor="#000000" stopOpacity="0" />
        </linearGradient>
      </defs>
      <path d="M2 0h22.6l14 14v35.6a2 2 0 0 1-2 2H2a2 2 0 0 1-2-2V2a2 2 0 0 1 2-2z" fill={`url(#${id}-page)`} />
      <rect x="21.6" y="0" width="3" height="14" fill={`url(#${id}-crease-x)`} />
      <rect x="24.6" y="14" width="14" height="2" fill={`url(#${id}-crease-y)`} />
      <path d="M24.6 0l14 14H24.6z" fill={`url(#${id}-flap)`} />
    </svg>
  );
}

export type MessageAttachmentProps = Omit<ComponentProps<"div">, "children" | "title"> & {
  /** File name, e.g. "design-notes.txt". */
  name: string;
  /** Kind, e.g. "Text Document". Joined with `size` by a middle dot. */
  kind?: string;
  /** Human size, e.g. "275 bytes". Used alone when `kind` is absent. */
  size?: string;
  /** Overrides the whole second line. */
  subtitle?: ReactNode;
  /** Turns the card into a link. */
  href?: string;
  download?: boolean;
  onOpen?: () => void;
  direction?: "incoming" | "outgoing";
  /** The card only tails when it ends a cluster, exactly like a text bubble. */
  tail?: boolean;
  platform?: Platform;
  /** Custom artwork in place of the document page (a thumbnail, say). */
  icon?: ReactNode;
};

export function MessageAttachment({
  name, kind, size, subtitle, href, download, onOpen,
  direction = "outgoing", tail = false, platform: platformProp, icon, className, style, ...props
}: MessageAttachmentProps) {
  const contextPlatform = usePlatform();
  const platform = platformProp ?? contextPlatform;
  const m = attachmentMetrics[platform];
  const side = direction === "outgoing" ? "right" : "left";
  const hang = tailBox.hang * m.tailScale;
  const secondLine = subtitle ?? (kind && size ? `${kind} · ${size}` : (kind ?? size));

  const surface: CSSProperties = { background: "var(--im-att-fill)" };
  const Inner = href ? "a" : onOpen ? "button" : "div";
  const innerProps = href
    ? { href, download, target: href.startsWith("http") ? "_blank" : undefined, rel: href.startsWith("http") ? "noreferrer" : undefined }
    : onOpen ? { type: "button" as const, onClick: onOpen } : {};

  return (
    <div data-slot="message-attachment" data-direction={direction} data-platform={platform}
      className={cn("relative select-none", vars[platform], className)}
      style={{ width: m.width, height: m.height, fontFamily: font, ...style }} {...props}>
      {/*
        Body and tail are one clipped box, not two adjacent ones. Chrome rasterises two abutting
        clip paths independently and snaps the second to a whole device pixel, which left a 1px
        hairline of the page showing along the tail's leading and top edges at 2x (the card's
        88.75 height puts that join on a half device pixel).
      */}
      <div aria-hidden="true" data-slot="fill" className="pointer-events-none absolute left-0 top-0 w-full"
        style={tail
          ? { height: m.height + hang, clipPath: `path("${bubblePath(m.width, m.height, side, m.radius, m.tailScale)}")`, ...surface }
          : { height: m.height, borderRadius: m.radius, ...surface }} />
      <Inner data-slot="card" {...innerProps}
        className="absolute inset-0 block text-left focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#0088ff]"
        style={{ borderRadius: m.radius }}>
        <span aria-hidden="true" data-slot="icon" className="absolute flex items-center justify-center"
          style={{ left: m.iconLeft, top: m.iconTop, width: m.iconWidth, height: m.iconHeight }}>
          {icon ?? <DocumentIcon width={m.iconWidth} height={m.iconHeight} />}
        </span>
        <span data-slot="name" className="absolute block overflow-hidden text-ellipsis whitespace-nowrap"
          style={{ left: m.textLeft, right: m.textRight, top: m.titleTop, fontSize: m.titleSize, lineHeight: `${m.titleLine}px`, fontWeight: 600, letterSpacing: m.titleTracking, color: "var(--im-att-title)" }}>
          {name}
        </span>
        {secondLine !== undefined && (
          <span data-slot="subtitle" className="absolute block overflow-hidden text-ellipsis whitespace-nowrap"
            style={{ left: m.textLeft, right: m.textRight, top: m.subtitleTop, fontSize: m.subtitleSize, lineHeight: `${m.subtitleLine}px`, letterSpacing: m.subtitleTracking, color: "var(--im-att-subtitle)" }}>
            {secondLine}
          </span>
        )}
      </Inner>
    </div>
  );
}

