import { useCallback, useImperativeHandle, useLayoutEffect, useMemo, useRef, useState, type ComponentProps, type CSSProperties, type KeyboardEvent, type MouseEvent, type PointerEvent, type ReactNode, type Ref, type RefObject } from "react";
import { cn } from "@/lib/utils";
import { usePlatform, type Platform } from "@/components/imessage/platform";
import { bubbleMetrics, emojiFontStack, fontStack, type Direction, type Service } from "@/components/imessage/tokens";
import { isEmojiOnly, MessageBubble, reactionOffsets } from "@/components/imessage/message-bubble";
import { DateSeparator, formatClockTime, formatDateLabel, type DateSeparatorVariant } from "@/components/imessage/date-separator";
import { LinkPreview } from "@/components/imessage/link-preview";
import { MessageAttachment } from "@/components/imessage/message-attachment";
import { MessageImages } from "@/components/imessage/message-image";
import { MessageAudio } from "@/components/imessage/message-audio";
import { InvisibleInk } from "@/components/imessage/message-effects";
import { ReplyCount, ReplyStub } from "@/components/imessage/message-reply";
import { FailedSendBadge, NotDelivered } from "@/components/imessage/ios-notices";
