      <path d="M2.7 1.7h7.4l5.2 5.2v13.4a1 1 0 0 1-1 1H2.7a1 1 0 0 1-1-1V2.7a1 1 0 0 1 1-1Z" />
      <path d="M10.1 1.9v5.1h5.1" />
    </svg>
