  }
  if (icon === "audio") {
    const bars = [5.2, 9.4, 13.4, 17.6, 13.4, 9.4, 5.2];
    return (
      <svg aria-hidden="true" {...common}>
        <defs><linearGradient id={`${id}-aud`} x1="0" y1="0" x2="0.3" y2="1"><stop offset="0" stopColor="#ff9a63" /><stop offset="1" stopColor="#f4593c" /></linearGradient></defs>
        <circle cx="19.5" cy="19.5" r="19.5" fill={`url(#${id}-aud)`} />
        {bars.map((h, i) => (
          <rect key={i} x={19.5 + (i - 3) * 3.6 - 1.05} y={19.5 - h / 2} width="2.1" height={h} rx="1.05" fill="#ffffff" />
        ))}
      </svg>
    );
  }
  if (icon === "images") {
    return (
      <svg aria-hidden="true" {...common}>
        <defs><linearGradient id={`${id}-img`} x1="0" y1="0" x2="0.3" y2="1"><stop offset="0" stopColor="#ff5f86" /><stop offset="1" stopColor="#ec1f52" /></linearGradient></defs>
        <circle cx="19.5" cy="19.5" r="19.5" fill={`url(#${id}-img)`} />
        <g fill="none" stroke="#ffffff" strokeWidth="1.5">
          <circle cx="17.6" cy="17.4" r="7.6" />
          <path d="M10 17.4h15.2M17.6 9.8c3.2 4.6 3.2 10.6 0 15.2M17.6 9.8c-3.2 4.6-3.2 10.6 0 15.2" strokeWidth="1.15" />
          <path d="M23.2 23 29.4 29.2" strokeWidth="2.6" strokeLinecap="round" />
        </g>
      </svg>
    );
  }
  return (
    <svg aria-hidden="true" {...common}>
      <circle cx="19.5" cy="19.5" r="19.5" fill="#ffd42e" />
      <path d="M12.2 20.4 17.3 25.5 28.2 12.4" fill="none" stroke="#3a2a06" strokeWidth="3.4" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

/**
 * A row label, shrunk to fit `labelMaxWidth` the way iOS shrinks one. The font size is what changes,
 * not a transform: the line box keeps its 66.5 pitch, so a smaller face grows its own half-leading
 * by exactly as much as its ascent loses and the cap stays centred on the row (checked against both
 * "Camera" at 24 and "Apple Cash" at 21.7 in `plus-menu-open-light.png`).
 */
function RowLabel({ label }: { label: string }) {
  const m = plusMenuMetrics;
  const ref = useRef<HTMLSpanElement>(null);
  const [fontSize, setFontSize] = useState<number>(m.labelSize);
  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const fit = () => {
      // The used width, not `getBoundingClientRect`: a row carries a lift and a fade while the sheet
      // opens, and a rect would report the label mid-animation and re-fit it on every frame. Advance
      // widths scale with the size and the tracking is zero, so one measurement at whatever size is
      // currently applied recovers the natural width, and re-running is idempotent.
      const style = getComputedStyle(el);
      const applied = Number.parseFloat(style.fontSize) || m.labelSize;
      const natural = (Number.parseFloat(style.width) * m.labelSize) / applied;
      if (!Number.isFinite(natural) || natural <= 0) return;
      setFontSize(natural > m.labelMaxWidth ? (m.labelSize * m.labelMaxWidth) / natural : m.labelSize);
    };
    fit();
    document.fonts?.ready.then(fit).catch(() => {});
  }, [label, m.labelMaxWidth, m.labelSize]);
  return (
    <span ref={ref} data-slot="label" className="absolute whitespace-nowrap"
      style={{ left: m.labelX - m.left, top: 0, lineHeight: `${m.rowPitch}px`, fontSize, letterSpacing: 0, transform: "translateY(-0.6667px)", color: "var(--ios-pm-label)" }}>
      {label}
    </span>
  );
}

export type IosPlusMenuProps = Omit<ComponentProps<"div">, "children"> & {
  items?: PlusMenuItem[];
  /**
   * 0 = the sheet is still the composer's `+`, 1 = settled. Leave unset to play `open` on a spring;
   * pass it to seek the entrance instead, which is what the harness does.
   */
  progress?: number;
  open?: boolean;
  /**
   * Fires once a dismissal has folded the sheet back into the `+`, so the caller can unmount it. The
   * caller keeps the sheet mounted until then, exactly as `ios-messages-app.tsx` keeps the effects
   * screen mounted after its own prop has cleared.
   */
  onExited?: () => void;
  /**
   * The composer row. Rendered under the sheet with its `+` faded out, as the capture shows. A menu
   * handed to `IosMessagesApp` as an `overlay` leaves this unset: that shell draws its own composer,
   * and the `+` in it fades all the same.
   */
  composer?: ReactNode;
  /** Called by Escape, by the close control over the `+`, and by a tap anywhere outside the sheet. */
  onDismiss?: () => void;
};

export function IosPlusMenu({ items = defaultPlusMenuItems, progress, open = true, onExited, composer, onDismiss, className, style, ...props }: IosPlusMenuProps) {
  const m = plusMenuMetrics;
  const mo = plusMenuMotion;
  const id = useId();

  // The sheet outlives the `open` prop so the dismissal has frames to run in, and `closing` is
  // derived during render rather than in an effect: an effect leaves one committed frame with the
  // sheet already gone and the exit never runs. Same rule as `ios-messages-app.tsx`.
  const [seenOpen, setSeenOpen] = useState(open);
  const [closing, setClosing] = useState(false);
  if (seenOpen !== open) {
    setSeenOpen(open);
    setClosing(!open);
  }

  const exited = useRef(onExited);
  useEffect(() => { exited.current = onExited; });
  // Read by the spring when it settles, which happens a frame after this render has committed.
  const openNow = useRef(open);
  useEffect(() => { openNow.current = open; }, [open]);
  const onSettled = useCallback(() => {
    // A spring that settles on 1 has just opened; only the one that lands back on the `+` reports.
    if (openNow.current) return;
    exited.current?.();
  }, []);

  const spring = usePlusMenuSpring(open ? 1 : 0, progress === undefined, onSettled);
  const t = progress === undefined ? spring : clamp01(progress);
  const sheet = useRef<HTMLDivElement>(null);
  // One tab stop for the sheet; the arrow keys walk the rows, as a menu does.
  const [focusIndex, setFocusIndex] = useState(0);

  // A seeked dismissal has no spring to report it: the caller owns the clock, so it is over when the
  // sheet reads 0 and is back inside the `+`. Reported once, and from a ref rather than state, so
  // finishing an exit never schedules a render of its own.
  const reported = useRef(false);
  useEffect(() => {
    if (progress === undefined || !closing || t > 0) { reported.current = false; return; }
    if (reported.current) return;
    reported.current = true;
    exited.current?.();
  }, [progress, closing, t]);

  // Escape closes it, so the sheet never depends on a tap outside to get out of the way.
  useEffect(() => {
    if (!open || !onDismiss) return;
    const onKey = (event: globalThis.KeyboardEvent) => { if (event.key === "Escape") { event.preventDefault(); onDismiss(); } };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [open, onDismiss]);

  function onKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) return;
    const rows = Array.from(sheet.current?.querySelectorAll<HTMLButtonElement>('[role="menuitem"]') ?? []);
    if (!rows.length) return;
    event.preventDefault();
    const from = rows.indexOf(document.activeElement as HTMLButtonElement);
    const current = from < 0 ? focusIndex : from;
    const next = event.key === "Home" ? 0 : event.key === "End" ? rows.length - 1 : event.key === "ArrowDown" ? (current + 1) % rows.length : (current - 1 + rows.length) % rows.length;
    setFocusIndex(next);
    rows[next]?.focus();
  }

  // The box the sheet grows out of: the composer's Ø40 `+`, in the same screen points the sheet uses.
  const from = mo.button;
  const fromLeft = from.centerX - from.size / 2;
  const fromTop = from.centerY - from.size / 2;
  const box = {
    left: lerp(fromLeft, m.left, t),
    top: lerp(fromTop, m.top, t),
    width: lerp(from.size, m.width, t),
    height: lerp(from.size, m.height, t),
    radius: lerp(from.size / 2, m.radius, t),
  };
  // The sheet's fill takes over from the `+`'s while the two shapes still coincide, so the handover
  // between the two measured glasses is never visible as a change of colour. The blur and the shadow
  // ramp over the whole entrance instead: both reach past the box and both are what makes it read as
  // a sheet rather than a white card.
  const glass = easeOut(clamp01(t / mo.glassFade));
  const attach = easeOut(clamp01(t / mo.attachFade));
  const filter = `blur(${lerp(mo.buttonBlur, mo.sheetBlur, t).toFixed(2)}px) saturate(${lerp(1, mo.sheetSaturate, t).toFixed(2)})`;
  const alive = t > 0 || open;

  return (
    <div data-slot="ios-plus-menu" data-plus-menu={id} data-progress={t.toFixed(3)}
      data-state={open ? "open" : t > 0 ? "closing" : "closed"}
      className={cn("absolute inset-0 z-20 select-none", vars, className)}
      style={{ fontFamily: font, pointerEvents: "none", ...style }} {...props}>
      {/* The `+` fades out under the sheet growing over it. Two rules, not one selector list: the
          composer is inside this menu when a caller passes it to `composer`, and a sibling under the
          app frame when the menu is handed to `IosMessagesApp` as an overlay. An unsupported `:has()`
          would take a whole selector list down with it, so the reachable case stands on its own. */}
      <style>{`[data-plus-menu="${id}"] [data-slot="attach"]{opacity:${(1 - attach).toFixed(3)};transform:scale(${(1 - 0.35 * attach).toFixed(3)})}
[data-slot="ios-messages-app"]:has([data-plus-menu="${id}"]) [data-slot="attach"]{opacity:${(1 - attach).toFixed(3)};transform:scale(${(1 - 0.35 * attach).toFixed(3)})}`}</style>
      {composer !== undefined && <div data-slot="composer-slot" className="pointer-events-auto absolute bottom-0 left-0 w-full">{composer}</div>}
      {/* A scrim, not a control: it is invisible, it fills the screen, and both Escape and the close
          control below do the same job, so it stays out of the tab order and the accessibility tree. */}
      {alive && <div aria-hidden="true" data-slot="dismiss" onClick={onDismiss} className="pointer-events-auto absolute inset-0 cursor-default" />}
      {/* The control that opened the sheet closes it again. It paints nothing: the `+` it stands on is
          the composer's own, faded out above, and the capture shows no other control while the sheet
          is open. The sheet covers its top once it has grown, which is why it is drawn under it. */}
      {alive && onDismiss && (
        <button type="button" data-slot="close" aria-label="Close attachments" onClick={onDismiss}
          className="pointer-events-auto absolute cursor-default bg-transparent focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#0088ff]"
          style={{ left: fromLeft, top: fromTop, width: from.size, height: from.size, borderRadius: from.size / 2 }} />
      )}
      <div ref={sheet} data-slot="sheet" role="menu" aria-label="Attachments" onKeyDown={onKeyDown} className="absolute overflow-hidden"
        style={{
          left: box.left, top: box.top, width: box.width, height: box.height, borderRadius: box.radius, ...continuous,
          background: `rgb(var(--ios-pm-glass) / calc(${(1 - glass).toFixed(4)} * ${mo.buttonAlpha} + ${glass.toFixed(4)} * var(--ios-pm-alpha)))`,
          boxShadow: `0 5px 30px 6px rgb(0 0 0 / calc(var(--ios-pm-shadow-alpha) * ${t.toFixed(4)})), var(--ios-pm-rim)`,
          backdropFilter: filter,
          WebkitBackdropFilter: filter,
          opacity: glass,
          // A closed sheet is not just invisible: hidden takes its seven rows out of the tab order
          // and out of the accessibility tree, which `opacity: 0` on its own would not.
          visibility: t > 0 ? undefined : "hidden",
          pointerEvents: t > 0.5 ? "auto" : "none",
        }}>
        {/* The rows are laid out against the settled sheet and held there while the box grows around
            them, so they fade in where they belong instead of sliding out of the `+` with the box. */}
        <div data-slot="sheet-content" className="absolute"
          style={{ left: m.left - box.left, top: m.top - box.top, width: m.width, height: m.height }}>
          {items.map((item, index) => {
            const center = m.firstRowCenter + index * m.rowPitch - m.top;
            const iconSize = item.iconSize ?? m.iconSize;
            const iconCenterX = item.iconCenterX ?? m.iconCenterX;
            // Staggered away from the `+`, so the row the growing box uncovers first is also the
            // first to arrive. Which end iOS starts from is not recorded anywhere here; this is the
            // order the geometry argues for, not a measurement.
            const row = easeOut(clamp01((t - mo.rowStart - (items.length - 1 - index) * mo.rowStagger) / mo.rowSpan));
            return (
              <button key={item.id} type="button" role="menuitem" data-slot="item" data-item={item.id} onClick={item.onSelect}
                tabIndex={index === focusIndex ? 0 : -1} onFocus={() => setFocusIndex(index)}
                className="absolute left-0 flex w-full items-center text-left focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-[#0088ff]"
                style={{
                  top: center - m.rowPitch / 2, height: m.rowPitch,
                  // A settled row carries neither, so the sheet at rest renders exactly as it did
                  // before there was an entrance at all.
                  opacity: row >= 1 ? undefined : row,
                  transform: row >= 1 ? undefined : `translateY(${((1 - row) * mo.rowLift).toFixed(2)}px)`,
                }}>
                <span aria-hidden="true" className="absolute flex items-center justify-center"
                  style={{ left: iconCenterX - m.left - iconSize / 2, top: (m.rowPitch - iconSize) / 2, width: iconSize, height: iconSize }}>
                  <AppIcon icon={item.icon} size={iconSize} />
                </span>
                <RowLabel label={item.label} />
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}

export type PhotoPickerGridProps = Omit<ComponentProps<"div">, "children"> & {
  /** Solid placeholder fills, one per tile. Never ship photographs in the registry. */
  tiles?: string[];
  columns?: number;
  tileSize?: number;
  gap?: number;
  /** The sheet's drag bar, drawn over the first row of tiles as the capture shows it. */
  grabber?: boolean;
  onSelect?: (index: number) => void;
};

/** Measured placeholders that sit in the same tonal range as the capture's landscape thumbnails. */
export const photoPickerPlaceholders = [
  "linear-gradient(160deg, #c8175f 0%, #e8408a 45%, #7a8f2e 100%)",
  "linear-gradient(180deg, #8fa2ad 0%, #4e6b5a 55%, #26361f 100%)",
  "linear-gradient(200deg, #8d9aa1 0%, #55605c 50%, #2a3128 100%)",
  "linear-gradient(170deg, #9fb0b8 0%, #5c7a5f 45%, #2c3a24 100%)",
  "linear-gradient(190deg, #b7c9cf 0%, #7f9a63 55%, #b52f57 100%)",
  "linear-gradient(150deg, #7fa04a 0%, #3f5c25 60%, #d9c02f 100%)",
];

export function PhotoPickerGrid({
  tiles = photoPickerPlaceholders, columns = 3, tileSize = photoPickerMetrics.tileSize, gap = photoPickerMetrics.gap,
  grabber = true, onSelect, className, style, ...props
}: PhotoPickerGridProps) {
  const g = photoPickerMetrics;
  return (
    // A group of buttons, not a listbox: choosing a photo inserts it, it does not leave one option
    // marked selected, and a listbox would owe the keyboard a roving selection it never has.
    <div data-slot="photo-picker-grid" role="group" aria-label="Recent photos"
      className={cn("relative grid select-none", className)}
      style={{ gridTemplateColumns: `repeat(${columns}, ${tileSize}px)`, gap, fontFamily: font, ...style }} {...props}>
      {tiles.map((fill, index) => (
        <button key={index} type="button" aria-label={`Photo ${index + 1}`} data-slot="tile"
          onClick={() => onSelect?.(index)}
          className="focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-[#0088ff]"
          style={{ width: tileSize, height: tileSize, borderRadius: g.radius, background: fill, ...continuous }} />
      ))}
      {grabber && (
        <span aria-hidden="true" data-slot="grabber" className="pointer-events-none absolute left-1/2 [background:rgba(0,0,0,0.3)] dark:[background:rgba(255,255,255,0.3)]"
          style={{ top: g.grabberTop, width: g.grabberWidth, height: g.grabberHeight, marginLeft: -g.grabberWidth / 2, borderRadius: g.grabberHeight / 2 }} />
      )}
    </div>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState, type ComponentProps, type CSSProperties, type KeyboardEvent } from "react";
import { cn } from "@/lib/utils";
import { fontStack } from "@/components/imessage/tokens";

/**
 * The Photos picker iOS 26 opens inside the Messages composer.
 *
 * Measured from `references/ios/captures/photo-picker-light.png` (iOS 26.0, iPhone 17 Pro, 402×874 pt
 * at 3x). Every number below is a sub-pixel read of that frame unless it says otherwise; device pixels
 * are quoted where the point value is a third.
 *
 * ## What the capture actually shows
 *
 * A white panel, inset **5.333 (16 px)** from the screen's left, right and bottom edges, holding a
 * three-column grid of square thumbnails flush to its own left, right and top edges. Over the middle
 * of the first row sits a drag grabber. That is the whole of it: **no header, no title, no "Recents"
 * label, no "All Photos" button, no camera tile, no search field, no send or count button, and no
 * selection indicator on any tile.** Anything this file draws beyond the panel, the grid and the
 * grabber is marked unverified below and is not in `SPEC.md` as a measurement.
 *
 * The capture shows only two rows with empty white under them. That is the library, not the layout:
 * the iOS Simulator ships exactly six sample photos. The grid scrolls **vertically** and a real
 * library keeps going; at the capture's panel height a third row is visible for 121.3 of its 129.56.
 *
 * ## Panel
 *
 * | Part | Value | How |
 * |---|---|---|
 * | Inset (left, right, bottom) | 5.3333 (16 px) | white run x 16–1189, bottom-most white row 2605 of 2622 |
 * | Width at a 402 screen | 391.3333 | 1174 px |
 * | Top / height in the capture | 485 / 383.6667 | grid top 1455 px, panel bottom 2606 px |
 * | Fill | `#ffffff` | flat, sampled all over the empty area below the grid |
 * | Top corners | superellipse n 2.204, R **39.0** (rms 0.84 px) | 109 sub-pixel boundary points on the top-right corner |
 * | Bottom corners | superellipse n 2.204, R **57.5833** (rms 0.90 px) | 183 points on the bottom-left corner |
 * | Shadow / dim | none | the blurred backdrop reads a flat 244–246 right up to the panel edge |
 *
 * The plain circle is fitted separately, because it is what the panel actually renders (see the
 * clip-path note in the panel's own style): **36.1667** top (rms 0.94 px) and **53.5** bottom (rms
 * 1.27 px). The bottom corner is the device's own corner made concentric with the panel: 57.58 + 5.33
 * = 62.9, which is the iPhone 17 Pro display radius.
 *
 * ## Grid
 *
 * Three columns, flush to the panel on three sides, **1.6207 (4.862 px)** between tiles on both axes.
 * The three gaps are measured independently over 100+ sub-pixel boundary points each and agree:
 * 4.870, 4.859 across, 4.858 down. Measured edges at 3x: columns 16.0 | 404.238 → 409.108 |
 * 796.900 → 801.759 | 1190.0, rows 1455.0 → 1843.636 | 1848.494 → 2237.24.
 *
 * That makes a tile **129.364 wide** (`(width - 2 × gap) / 3`) and **129.5633 tall**: the columns
 * average 388.09 device px and the rows 388.69, a real 0.6 px difference that shows up the same way in
 * both rows. Treating the tile as square puts the second row's bottom 1.2 px above the capture, so the
 * grid keeps the measured aspect instead. Tile corners are **≈2.1** (a circle fitted to the sub-pixel
 * coverage of the highest-contrast interior corner bottoms out at 6.3 device px); they are not the 12
 * the spec's prose carries, which is off by a factor of six and obvious in a side-by-side.
 *
 * ## Grabber
 *
 * **36 × 5**, pill radius 2.5, centred on the panel with its top **4.6667 (14 px)** below the panel
 * top. The size is a framework number, not a fit: `-[_UIGrabber intrinsicContentSize]` in UIKitCore
 * returns exactly `{36, 5}`, and the capture's ink (106 × 14 px at a 25/255 threshold, centred on
 * x 602.5 of a panel centred on 603.0) is that pill minus its anti-aliased rim.
 *
 * Its colour is **not** a flat fill. `_UIGrabber` builds itself out of a luma-tracking vibrancy view
 * (`-[_UIGrabber _visualEffectView]`, `_lumaTrackingEnabled`, `_setBackgroundLuminanceLevel:`), and the
 * capture agrees: over the photo it sits on, the pill darkens all three channels by the same 60/255
 * (196,190,223 → 136,129,163), which no single translucent colour reproduces. The closest flat fill is
 * 30% black, which lands the red and green channels within 2/255 and leaves blue 7/255 short. That is
 * a fit, and it is the same one `ios-plus-menu.tsx` already uses.
 *
 * ## Selection, unverified
 *
 * Nothing in `references/` captures a selected tile, and the iOS 26 picker's own grid is SwiftUI
 * (`PhotosUICore.LemonadePickerView`), so there is no Objective-C metric to read the badge out of
 * either. `PXPhotosGridMessagesLayoutSpec`, which does expose `itemCornerRadius`, `interItemSpacing`
 * and `padding`, is the wrong grid: its `numberOfColumnsForNumberOfItems:` reads
 * `PXMessagesUISettings.minItemSize/minColumns/maxColumns`, so it lays out the photo stack inside a
 * balloon, not this picker. So `photoPickerMetrics.badge` is a **fit, not a measurement**: the ordinary
 * iOS selection badge, a filled disc at the tile's bottom trailing corner carrying a white check, or
 * the 1-based pick order when `ordered` is set. Its blue is the kit's measured `#0088ff`.
 *
 * ## Motion, unverified
 *
 * No capture or recording in this repo holds the picker opening or closing, so both durations are
 * borrowed from the kit's measured neighbours (the long-press menu's 380 ms open and 220 ms exit) and
 * that is the whole of their authority. The panel translates up from its own height and fades; the
 * animation is a single Web Animations timeline so `progress` can pause and seek it to one exact
 * frame, and `prefers-reduced-motion` skips it. Closing is driven by the `open` prop during render, so
 * the exit always gets a committed frame before `onExited` fires.
 */
export const photoPickerMetrics = {
  /** The screen the numbers were measured on. Points equal CSS px. */
  screen: { width: 402, height: 874 },
  /** Left, right and bottom inset from the screen edge (16 device px at 3x). */
  inset: 5.3333,
  /** Where the panel's top edge falls in the capture, and how tall it is there. */
  top: 485,
  height: 383.6667,
  width: 391.3333,
  /**
   * `topRadius` and `bottomRadius` are the continuous corner the capture actually draws. `round*` is
   * the best plain circle for the same arc, and it is what the panel renders: see the clip-path note
   * on the panel for why the shape gives way to sub-pixel edges here.
   */
  topRadius: 39,
  bottomRadius: 57.5833,
  roundTopRadius: 36.1667,
  roundBottomRadius: 53.5,
  columns: 3,
  gap: 1.6207,
  /** Implied by width, columns and gap; quoted because the capture measures it directly. */
  tileWidth: 129.364,
  /**
   * Tiles are not quite square in the capture, and both axes are measured over 100+ boundary points:
   * columns average 388.09 device px, rows 388.69. `tileAspect` is that ratio, so a second row lands
   * on the measured 2237.24 instead of 1.2 px above it.
   */
  tileHeight: 129.5633,
  tileAspect: 129.364 / 129.5633,
  tileRadius: 2.1,
  grabber: { width: 36, height: 5, radius: 2.5, top: 4.6667 },
  /** Unverified: nothing captures a selected tile. See the file comment. */
  badge: { size: 22, inset: 6, fontSize: 13, checkStroke: 2 },
  /** Unverified: borrowed from the long-press menu's measured 380 / 220. */
  timing: { enter: 380, exit: 220 },
} as const;

/**
 * Light values are measured off the capture. The dark set is unverified: no dark capture of the picker
 * exists, so the panel takes iOS's grouped-background dark grey and the grabber flips to 30% white.
 * They are custom properties so a `.dark` ancestor flips the panel without the caller passing anything.
 */
const vars =
  "[--ios-pp-panel:#ffffff] [--ios-pp-grabber:rgba(0,0,0,0.3)] [--ios-pp-tile:#e9e9eb] [--ios-pp-badge:#0088ff] [--ios-pp-glyph:#ffffff] [--ios-pp-rim:rgba(0,0,0,0.22)] " +
  "dark:[--ios-pp-panel:#1c1c1e] dark:[--ios-pp-grabber:rgba(255,255,255,0.3)] dark:[--ios-pp-tile:#2c2c2e] dark:[--ios-pp-badge:#0088ff] dark:[--ios-pp-glyph:#ffffff] dark:[--ios-pp-rim:rgba(0,0,0,0.35)]";

/** Keeps a hidden string in the accessible name without depending on the consumer's utility classes. */
const offscreen: CSSProperties = {
  position: "absolute",
  width: 1,
  height: 1,
  margin: -1,
  padding: 0,
  overflow: "hidden",
  clipPath: "inset(50%)",
  whiteSpace: "nowrap",
  border: 0,
};

export type PhotoPickerPhoto = {
  /** Stable identity for selection. Falls back to the index. */
  id?: string;
  /** A URL, or nothing for a solid `fill`. The registry itself ships no photographs. */
  src?: string;
  alt?: string;
  /** Any CSS background, used when there is no `src`. */
  fill?: string;
};

/**
 * Placeholder tiles in the tonal range of the capture's landscapes, so the geometry can be reviewed
 * without shipping anyone's photographs in a registry item.
 */
export const photoPickerSamples: PhotoPickerPhoto[] = [
  { id: "bloom", fill: "linear-gradient(160deg, #c8175f 0%, #e8408a 45%, #7a8f2e 100%)" },
  { id: "falls", fill: "linear-gradient(180deg, #8fa2ad 0%, #4e6b5a 55%, #26361f 100%)" },
  { id: "cascade", fill: "linear-gradient(200deg, #8d9aa1 0%, #55605c 50%, #2a3128 100%)" },
  { id: "canyon", fill: "linear-gradient(170deg, #9fb0b8 0%, #5c7a5f 45%, #2c3a24 100%)" },
  { id: "dune", fill: "linear-gradient(190deg, #b7c9cf 0%, #7f9a63 55%, #b52f57 100%)" },
  { id: "leaf", fill: "linear-gradient(150deg, #7fa04a 0%, #3f5c25 60%, #d9c02f 100%)" },
];

export type PhotoPickerProps = Omit<ComponentProps<"div">, "onSelect" | "children"> & {
  photos?: PhotoPickerPhoto[];
  /** Controlled selection, as photo ids, in the order they were picked. */
  selected?: string[];
  defaultSelected?: string[];
  /** Fires with the whole selection, plus the photo that just changed and its new state. */
  onSelectionChange?: (selected: string[], photo: PhotoPickerPhoto, isSelected: boolean) => void;
  /** False keeps one tile chosen at a time. */
  multiple?: boolean;
  /** Number the badges in pick order, the way an ordered multi-select does. */
  ordered?: boolean;
  columns?: number;
  /** Panel box. Defaults are the capture's; the tile size follows from `width`, `columns` and the gap. */
  width?: number;
  height?: number;
  inset?: number;
  /** The drag bar over the first row. */
  grabber?: boolean;
  /** False plays the exit timeline and then calls `onExited`. */
  open?: boolean;
  onExited?: () => void;
  /**
   * Seek whichever direction `open` selects to this fraction (0..1) instead of playing it, which is
   * what the harness does. A seeked exit poses the panel and never reports through `onExited`.
   */
  progress?: number;
  /** Accessible name for the grid. */
  label?: string;
};

const clamp01 = (value: number) => Math.max(0, Math.min(1, value));
const idOf = (photo: PhotoPickerPhoto, index: number) => photo.id ?? String(index);

function Check({ size }: { size: number }) {
  // Drawn, not an SF Symbol, and unverified like the rest of the badge: a 2 pt stroke on its own box.
  return (
    <svg aria-hidden="true" width={size} height={size} viewBox="0 0 22 22" fill="none">
      <path
        d="M6 11.4l3.4 3.4L16.2 8"
        stroke="currentColor"
        strokeWidth={photoPickerMetrics.badge.checkStroke}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

export function PhotoPicker({
  photos = photoPickerSamples,
  selected: selectedProp,
  defaultSelected,
  onSelectionChange,
  multiple = true,
  ordered = false,
  columns = photoPickerMetrics.columns,
  width = photoPickerMetrics.width,
  height = photoPickerMetrics.height,
  inset = photoPickerMetrics.inset,
  grabber = true,
  open = true,
  onExited,
  progress,
  label = "Recent photos",
  className,
  style,
  ...props
}: PhotoPickerProps) {
  const m = photoPickerMetrics;
  const [internal, setInternal] = useState<string[]>(defaultSelected ?? []);
  const selected = selectedProp ?? internal;
  const [active, setActive] = useState(0);
  const panel = useRef<HTMLDivElement>(null);
  const exited = useRef(false);
  /**
   * The callback lives in a ref, not in the timeline effect's dependencies. A caller that passes an
   * inline arrow hands us a new identity on the render `onExited` itself causes, and a dependency on
   * it would tear the finished exit down and start it again from the top.
   */
  const exitedCallback = useRef(onExited);
  useEffect(() => {
    exitedCallback.current = onExited;
  });

  const toggle = useCallback(
    (photo: PhotoPickerPhoto, index: number) => {
      const id = idOf(photo, index);
      const isSelected = selected.includes(id);
      const next = isSelected
        ? selected.filter(entry => entry !== id)
        : multiple
          ? [...selected, id]
          : [id];
      if (selectedProp === undefined) setInternal(next);
      onSelectionChange?.(next, photo, !isSelected);
    },
    [selected, selectedProp, multiple, onSelectionChange],
  );

  /**
   * One tab stop for the whole grid, arrows to move inside it, the way a native grid behaves. The
   * roving index is clamped during render, so a library that shrinks under it cannot strand the tab
   * stop on a tile that is gone.
   */
  const activeIndex = Math.min(active, Math.max(0, photos.length - 1));
  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const step =
      event.key === "ArrowRight" ? 1
      : event.key === "ArrowLeft" ? -1
      : event.key === "ArrowDown" ? columns
      : event.key === "ArrowUp" ? -columns
      : 0;
    let next = step ? activeIndex + step : activeIndex;
    if (event.key === "Home") next = 0;
    if (event.key === "End") next = photos.length - 1;
    if (!step && event.key !== "Home" && event.key !== "End") return;
    if (next < 0 || next >= photos.length) return;
    event.preventDefault();
    setActive(next);
    event.currentTarget.querySelector<HTMLButtonElement>(`[data-index="${next}"]`)?.focus();
  };

  /**
   * One Web Animations timeline, run forwards or backwards, so `document.getAnimations()` reaches it
   * and `progress` can pause and seek either direction to a frame that renders identically every run.
   * Which direction it runs is read off the `open` prop during render, so the closing pose gets its
   * committed frames before `onExited` lets the caller unmount anything.
   */
  useEffect(() => {
    const node = panel.current;
    if (!node) return;
    // Reopening arms the exit again, so a panel that opens and closes twice reports twice.
    if (open) exited.current = false;
    const closing = !open;
    const duration = closing ? m.timing.exit : m.timing.enter;
    const away = { transform: `translateY(${height}px)`, opacity: 0 };
    const settled = { transform: "translateY(0px)", opacity: 1 };
    const finish = () => {
      if (exited.current) return;
      exited.current = true;
      exitedCallback.current?.();
    };
    // Scrubbing is inspection, not a dismissal: a seeked exit poses the panel and reports nothing.
    const reports = closing && progress === undefined;
    const reduced = typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduced) {
      if (!reports) return;
      const frame = requestAnimationFrame(finish);
      return () => cancelAnimationFrame(frame);
    }
    const animation = node.animate(closing ? [settled, away] : [away, settled], {
      duration,
      easing: closing ? "cubic-bezier(0.4, 0, 1, 1)" : "cubic-bezier(0.32, 0.72, 0, 1)",
      fill: "both",
    });
    if (progress !== undefined) {
      animation.pause();
      animation.currentTime = clamp01(progress) * duration;
      return () => animation.cancel();
    }
    if (!closing) return () => animation.cancel();
    animation.addEventListener("finish", finish);
    return () => animation.removeEventListener("finish", finish);
  }, [open, progress, height, m.timing.enter, m.timing.exit]);

  /**
   * The row height comes from the tile's own measured aspect, not from `aspect-square`: the capture's
   * rows really are 0.6 device px taller than its columns are wide.
   */
  const gap = m.gap;
  const tileWidth = (width - (columns - 1) * gap) / columns;
  const tileHeight = tileWidth / m.tileAspect;

  return (
    <div
      ref={panel}
      data-slot="photo-picker"
      data-state={open ? "open" : "closed"}
      className={cn("ios-photo-picker absolute", vars, className)}
      style={{
        // Left plus width, never left plus right: two fractional insets resolve independently and the
        // panel ends up a device pixel wider than the capture's 1174.
        left: inset,
        bottom: inset,
        width,
        height,
        background: "var(--ios-pp-panel)",
        fontFamily: fontStack,
        /*
         * The rounding is a clip path, not `border-radius`, and that is a fidelity decision rather
         * than a style one. Chrome paints a `border-radius` box snapped out to whole device pixels: at
         * this panel's measured left of 15.984 device px it fills pixel 15 completely, and the same
         * snapping on each tile eats the gaps, turning the measured 4.86 device px into 3. `clip-path`
         * renders sub-pixel, so both land where the capture puts them (pixel 15 comes out 241 against
         * the backdrop's 244, which is the 1.6% of a pixel the panel really covers).
         *
         * The cost is the corner profile. `clip-path: inset(... round)` can only draw a circle, and the
         * capture's corner is one of Apple's continuous ones: fitting the traced arc gives the
         * superellipse 0.84 device px rms on the top corner and 0.90 on the bottom, against the best
         * circle's 0.94 and 1.27. Trading 0.1 to 0.37 px of rms on two arcs for a device pixel on every
         * straight edge and every gap is the right way round, so the circle wins here.
         */
        clipPath: `inset(0 round ${m.roundTopRadius}px ${m.roundTopRadius}px ${m.roundBottomRadius}px ${m.roundBottomRadius}px)`,
        ...style,
      }}
      {...props}
    >
      <div
        data-slot="photo-picker-scroller"
        className="h-full w-full overflow-y-auto overflow-x-hidden [overscroll-behavior:contain]"
      >
        {/*
          A group of toggles, not a listbox: each tile keeps its own pressed state and the grid never
          owes the keyboard a single mandatory selection.
        */}
        <div
          data-slot="photo-picker-grid"
          role="group"
          aria-label={label}
          onKeyDown={onKeyDown}
          className="grid select-none"
          style={{ gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))`, gridAutoRows: `${tileHeight}px`, gap }}
        >
          {photos.map((photo, index) => {
            const id = idOf(photo, index);
            const order = selected.indexOf(id);
            const isSelected = order >= 0;
            const name = photo.alt ?? `Photo ${index + 1}`;
            return (
              <button
                key={id}
                type="button"
                data-slot="photo-picker-tile"
                data-index={index}
                data-selected={isSelected ? "true" : "false"}
                aria-label={name}
                aria-pressed={isSelected}
                tabIndex={index === activeIndex ? 0 : -1}
                onFocus={() => setActive(index)}
                onClick={() => toggle(photo, index)}
                className="relative block size-full p-0 focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-[#0088ff]"
                style={{
                  background: photo.src ? "var(--ios-pp-tile)" : (photo.fill ?? "var(--ios-pp-tile)"),
                  // Clipped, not rounded, for the same reason the panel is; the focus ring is drawn
                  // inside the tile so the clip cannot swallow it.
                  clipPath: `inset(0 round ${m.tileRadius}px)`,
                }}
              >
                {photo.src ? (
                  // eslint-disable-next-line @next/next/no-img-element
                  <img src={photo.src} alt="" aria-hidden="true" className="absolute inset-0 size-full object-cover" draggable={false} />
                ) : null}
                {/* `aria-pressed` already says selected, so the hidden text only carries the pick order. */}
                {ordered && isSelected ? <span style={offscreen}>{`${order + 1} of ${selected.length}`}</span> : null}
                {/*
                  Unverified geometry and colour, and the 150 ms is a fit too. The badge never
                  unmounts: it is always in the tree and only its opacity and scale change, so a
                  deselect gets the same committed frames a select does instead of vanishing on the
                  render that drops it.
                */}
                <span
                  aria-hidden="true"
                  data-slot="photo-picker-badge"
                  className="pointer-events-none absolute flex items-center justify-center rounded-full motion-safe:transition-[opacity,transform] motion-safe:duration-150"
                  style={{
                    right: m.badge.inset,
                    bottom: m.badge.inset,
                    width: m.badge.size,
                    height: m.badge.size,
                    background: "var(--ios-pp-badge)",
                    color: "var(--ios-pp-glyph)",
                    fontSize: m.badge.fontSize,
                    fontWeight: 600,
                    lineHeight: 1,
                    boxShadow: "0 0 0 0.5px var(--ios-pp-rim)",
                    opacity: isSelected ? 1 : 0,
                    transform: isSelected ? "scale(1)" : "scale(0.6)",
                  }}
                >
                  {ordered ? (isSelected ? order + 1 : "") : <Check size={m.badge.size} />}
                </span>
              </button>
            );
          })}
        </div>
      </div>

      {grabber ? (
        <span
          aria-hidden="true"
          data-slot="photo-picker-grabber"
          className="pointer-events-none absolute left-1/2"
          style={{
            top: m.grabber.top,
            width: m.grabber.width,
            height: m.grabber.height,
            marginLeft: -m.grabber.width / 2,
            borderRadius: m.grabber.radius,
            background: "var(--ios-pp-grabber)",
          }}
        />
      ) : null}
    </div>
  );
}

"use client";

import { Fragment, useCallback, useEffect, useId, useMemo, useRef, useState, type ComponentProps, type CSSProperties, type KeyboardEvent, type PointerEvent as ReactPointerEvent } from "react";
import { cn } from "@/lib/utils";
import { emojiFontStack, fontStack } from "@/components/imessage/tokens";

/**
 * The iOS 26 sticker picker, the sheet the plus menu's "Stickers" row opens.
 *
 * ## Provenance, in the order this repo prefers it
 *
 * **1. Measured, from `references/ios/captures/plus-menu-open-light.png` (402x874 @3x).** The sheet is
 * the plus menu's own sheet, so its box is the measurement `ios-plus-menu.tsx` already carries:
 * x 8.6667-331.3333, y 371-831.6667 (322.6667 x 460.6667), continuous corner 24, glass
 * rgb(255 255 255 / 0.62) light and rgb(28 28 28 / 0.72) dark over a nominal 45 blur, one soft shadow
 * fitted at 6.6% in light and a bright inset rim in dark. Nothing behind it dims. The picker is
 * presented the same way, so it inherits all of that rather than inventing a second sheet.
 * The entrance grows out of the Stickers row's own artwork: that row is the third of seven, so its
 * icon is the measured Oe39 disc centred (63.1667, 425.8333 + 2 x 66.5 = 558.8333).
 *
 * **2. From the frameworks.** macOS Messages is a Mac Catalyst app on ChatKit, so a Catalyst probe
 * (`clang -target arm64-apple-ios26.0-macabi`) can dlopen
 * `/System/iOSSupport/System/Library/PrivateFrameworks/ChatKit.framework/ChatKit`, swizzle
 * `-[UIDevice userInterfaceIdiom]` to Phone so `+[CKUIBehavior sharedBehaviors]` vends
 * `CKUIBehaviorPhone`, and read the values off the runtime. Everything below names the selector it
 * came from:
 *
 * | Value | Selector |
 * |---|---|
 * | tile corner radius 8 | `-[CKUIBehaviorPhone stickersCellCornerRadius]` |
 * | grid gaps 4 | `-[CKUIBehaviorPhone attachmentBrowserGridInterItemSpacing]` and `attachmentBrowserGridMinimumLineSpacing` |
 * | grid inset 8 on all four sides | `-[CKUIBehaviorPhone attachmentBrowserGridSectionInset]` |
 * | tab strip 38 tall | `+[CKAppStripLayout minHeight]` |
 * | tab 52 x 38, 2 between, 1 x 38 separator | `-[CKAppStripLayout _specForLayoutMode:]` mode 0 (mode 1, the magnified strip, is 84 x 68 with 4 and 6) |
 * | strip gutter 8 | `-[CKUIBehaviorPhone browserSwitcherGutterWidth]` |
 * | emoji sticker box 48 x 48 | `-[CKUIBehaviorPhone emojiStickerTranscriptBalloonSize]` |
 * | drag rotation 3 to 10 degrees | `-[CKUIBehaviorPhone minStickerReactionRotation]` / `maxStickerReactionRotation` |
 * | drag easing cubic-bezier(0.14028, 0.004662, 0.57534, 0.96737) | the `CAMediaTimingFunction` `+[CKBrowserDragStickerView springAnimationWithKeyPath:speed:]` builds, read out of ChatKit's `__const` at the four `adrp`/`ldr` pairs at +128..+156 under lldb |
 * | search row 44, field 34, field type 17pt medium | `-[UISearchBar sizeThatFits:]` at width 322.6667, `-[UISearchTextField sizeThatFits:]`, and `-[UISearchBar searchTextField].font` in the same probe |
 * | field fill rgba(118,118,128,0.12) / (0.24) | `+[UIColor tertiarySystemFillColor]` resolved against each `UIUserInterfaceStyle` |
 * | separator #c6c6c8 / #38383a | `+[UIColor opaqueSeparatorColor]`, same resolution |
 *
 * Two framework numbers that back each other up: six columns inside the measured sheet puts an emoji
 * tile at (322.6667 - 2x8 - 5x4) / 6 = 47.7778, a quarter point off the 48 x 48 ChatKit gives an emoji
 * sticker in the transcript. The column count is still a choice (see below); the tile size it lands on
 * is not an accident.
 *
 * The label colours are NOT taken from that probe. `+[UIColor labelColor]` and `separatorColor` come
 * back with the *macOS* values under Catalyst (0.847 alpha black, 0.098 alpha black), so this file
 * uses the kit's own measured iOS labels instead: #000000 / #f4f3f4 from `ios-plus-menu.tsx` and the
 * #8a8a8e / #97979d search gray from `ios-conversation-list.tsx`. The `systemFill` family does come
 * back with the iOS values (118,118,128 at 0.12 and 0.24), which is why it is used.
 *
 * **3. Reused from measurements elsewhere in the kit.** The grabber is `photo-picker.tsx`'s: 36 x 5,
 * radius 2.5, its top 4.6667 below the panel, the size itself `-[_UIGrabber intrinsicContentSize]`.
 * The magnifier is the one traced for `ios-conversation-list.tsx`'s search pill (circle r 5.883 at
 * (6.745, 7.219), stroke 1.725; handle 11.4,12.01 to 15.17,15.78, stroke 2.467), drawn here at 0.72
 * of that size to suit a 34 pt field instead of a 48 pt one. Enter 380 ms and exit 220 ms are the
 * long-press menu's measured `messageActionsTiming` open and exit, the same borrow `photo-picker.tsx`
 * makes.
 *
 * **4. Judgement, and nothing here is measured.** Marked `@unverified` on each metric as well:
 *
 * - **The column counts.** Three for art stickers (the count the Photos picker measures) and six for
 *   emoji. Nothing in `references/` captures this grid, and the picker's own UI is out of process:
 *   `_UIStickerPickerViewController` is a shell around `_UIStickerPickerServiceRemoteViewController`,
 *   and the service that draws the card (`com.apple.StickerKit.StickerPickerService`) is not
 *   installed on macOS, so no Mac-side framework holds its layout.
 * - **Which tabs exist and their order.** Recents, Emoji, Memoji, Live Stickers, then app packs, from
 *   documented behaviour. The tab artwork is drawn here, not Apple's.
 * - **The vertical stack inside the sheet**: grabber, then the search row at 14, then the grid, then
 *   the strip pinned to the bottom. Only the pieces have measured sizes; their order and the 14 are a
 *   choice.
 * - **The drag lift of 1.4.** `-[CKBrowserDragStickerView animateScaleDown]` settles the drag view at
 *   0.7142857142857143 of its scale (the `__const` double the `ldr d1, [x8, #0x770]` at +164 loads),
 *   and 1 / 0.714285... is 1.4. What that scale is relative to was not traced, so 1.4 is
 *   ChatKit-derived rather than measured, and the ghost's shadow is invented outright.
 * - **Every duration except the 380 and the 220**, and the whole empty state.
 *
 * ## Motion
 *
 * One Web Animations timeline, so `document.getAnimations()` reaches it and `progress` pauses and
 * seeks it to a frame that renders identically on every run: nothing in it reads a clock, a random
 * number or a layout. The direction is read off the `open` prop **during render**, not in an effect,
 * so a dismissal always gets committed frames before `onExited` lets the caller unmount the sheet.
 *
 * The sheet itself never moves: it is already open behind the plus menu's rows. What animates is the
 * contents, scaling up from the Stickers row's own icon centre while they fade in, with the tab strip
 * riding up from the sheet's bottom edge behind them. `prefers-reduced-motion` skips to the end pose.
 *
 * The drag ghost is an interaction, not a presentation, so it is live only: scrubbing `progress`
 * disables it. Its return to the tile is still a Web Animations run for the same reason.
 */

/** Apple's continuous corner. Browsers without `corner-shape` fall back to a plain round corner. */
const continuous = { cornerShape: "superellipse(1.14)" } as CSSProperties;

/**
 * Light values are measured or framework values; see the file comment for which is which. Written out
 * in full because Tailwind only compiles class names it can read literally in the source.
 *
 * `--ios-sp-rim` and `--ios-sp-shadow-alpha` mirror `ios-plus-menu.tsx`: `box-shadow` takes a comma
 * separated list and `none` is only legal on its own, so both slots always hold a real shadow and the
 * unused one is fully transparent.
 */
const vars =
  "[--ios-sp-label:#000000] [--ios-sp-glass:255_255_255] [--ios-sp-alpha:0.62] [--ios-sp-shadow-alpha:0.066] [--ios-sp-rim:0_0_0_0_rgba(0,0,0,0)] " +
  "[--ios-sp-field:rgba(118,118,128,0.12)] [--ios-sp-muted:#8a8a8e] [--ios-sp-separator:#c6c6c8] [--ios-sp-tab-selected:rgba(120,120,128,0.16)] [--ios-sp-tile:rgba(118,118,128,0.12)] [--ios-sp-ghost-shadow:rgba(0,0,0,0.28)] " +
  "dark:[--ios-sp-label:#f4f3f4] dark:[--ios-sp-glass:28_28_28] dark:[--ios-sp-alpha:0.72] dark:[--ios-sp-shadow-alpha:0] dark:[--ios-sp-rim:inset_0_0_0_1px_rgba(255,255,255,0.09)] " +
  "dark:[--ios-sp-field:rgba(118,118,128,0.24)] dark:[--ios-sp-muted:#97979d] dark:[--ios-sp-separator:#38383a] dark:[--ios-sp-tab-selected:rgba(120,120,128,0.32)] dark:[--ios-sp-tile:rgba(118,118,128,0.24)] dark:[--ios-sp-ghost-shadow:rgba(0,0,0,0.5)]";

export const stickerPickerMetrics = {
  /** The screen the sheet's numbers were measured on. Points equal CSS px. */
  screen: { width: 402, height: 874 },
  /** Measured: the plus menu's sheet in `plus-menu-open-light.png`. */
  sheet: { left: 8.6667, top: 371, width: 322.6667, height: 460.6667, radius: 24 },
  /** Measured: the plus menu's Stickers row artwork, the third Oe39 disc down. */
  origin: { centerX: 63.1667, centerY: 558.8333, size: 39 },
  /** Measured in `photo-picker.tsx`; the 36 x 5 is `-[_UIGrabber intrinsicContentSize]`. */
  grabber: { width: 36, height: 5, radius: 2.5, top: 4.6667 },
  /**
   * `rowHeight` and `fieldHeight` are `-[UISearchBar sizeThatFits:]` and
   * `-[UISearchTextField sizeThatFits:]`; `fontSize` and `weight` are that bar's own search field
   * font (SF Medium 17), which is also the weight `ios-conversation-list.tsx` measured on the list's
   * search pill. `top`, `radius` and `glyphScale` are judgement: iOS 26 draws every field as a
   * capsule, so the radius is half the height.
   * @unverified top, radius, glyphScale
   */
  search: { top: 14, rowHeight: 44, fieldHeight: 34, fontSize: 17, weight: 500, radius: 17, glyphScale: 0.72, textInset: 34 },
  /**
   * `inset` and `gap` are `-[CKUIBehaviorPhone attachmentBrowserGridSectionInset]` and
   * `attachmentBrowserGridInterItemSpacing`; `tileRadius` is `stickersCellCornerRadius`. The two
   * column counts are judgement, and `emojiGlyph` (the glyph's share of its tile) is too.
   * @unverified columns, emojiColumns, emojiGlyph
   */
  grid: { inset: 8, gap: 4, tileRadius: 8, columns: 3, emojiColumns: 6, emojiGlyph: 0.68 },
  /**
   * The minified app strip out of `-[CKAppStripLayout _specForLayoutMode:]` mode 0, whose height is
   * also `+[CKAppStripLayout minHeight]`, with `-[CKUIBehaviorPhone browserSwitcherGutterWidth]` for
   * the gutter. `iconSize` and `selectionInset` are judgement, and the hairline over the strip is one
   * device pixel at 3x.
   * @unverified iconSize, selectionInset, hairline
   */
  strip: { height: 38, itemWidth: 52, itemHeight: 38, spacing: 2, separatorWidth: 1, gutter: 8, iconSize: 26, selectionInset: 3, hairline: 0.3333 },
  /**
   * `minRotation` and `maxRotation` are ChatKit's sticker reaction rotation bounds. `liftScale` is
   * derived from ChatKit (see the file comment); the threshold and the shadow are invented.
   * @unverified threshold, shadowBlur, shadowLift
   */
  drag: { liftScale: 1.4, minRotation: 3, maxRotation: 10, threshold: 6, shadowBlur: 18, shadowLift: 8 },
  /**
   * 380 and 220 are the long-press menu's measured open and exit, borrowed exactly as
   * `photo-picker.tsx` borrows them. `settle` is judgement.
   * @unverified settle
   */
  timing: { enter: 380, exit: 220, settle: 260 },
  /** The timing function `+[CKBrowserDragStickerView springAnimationWithKeyPath:speed:]` installs. */
  dragEasing: "cubic-bezier(0.14028, 0.004662, 0.57534, 0.96737)",
  /** The kit's entrance curve, shared with `photo-picker.tsx`. */
  enterEasing: "cubic-bezier(0.32, 0.72, 0, 1)",
  exitEasing: "cubic-bezier(0.4, 0, 1, 1)",
} as const;

export type StickerKind = "emoji" | "art";

export type Sticker = {
  id: string;
  /** `emoji` draws `glyph` as text; `art` draws a placeholder tile with the glyph on top. */
  kind?: StickerKind;
  glyph: string;
  /** Accessible name, and what the search field matches against together with `keywords`. */
  label: string;
  keywords?: string;
  /** Any CSS background for an `art` sticker. The registry ships no photographs. */
  fill?: string;
};

export type StickerTabIcon = "recents" | "emoji" | "memoji" | "live" | "pack";

export type StickerTab = {
  id: string;
  label: string;
  icon: StickerTabIcon;
  stickers: Sticker[];
  /** Overrides the tab's column count. Emoji tabs default to six, everything else to three. */
  columns?: number;
  /** Draws the strip's 1 x 38 separator before this tab, the way the app strip splits its sections. */
  separatorBefore?: boolean;
};

