type DragState = {
  sticker: Sticker;
  pointerId: number;
  /** Root relative, so the ghost and the drop point share one coordinate space. */
  x: number;
  y: number;
  size: number;
  rotation: number;
  source: { left: number; top: number; size: number };
};

export type StickerPlacement = {
  /** Where the sticker was let go, in the picker root's own coordinates. */
  x: number;
  y: number;
  /** The angle it was carrying, in degrees. */
  rotation: number;
  /** Its drawn size at the moment of the drop. */
  size: number;
};

export type StickerPickerProps = Omit<ComponentProps<"div">, "onSelect" | "children"> & {
  tabs?: StickerTab[];
  /** Controlled active tab id. */
  tab?: string;
  defaultTab?: string;
  onTabChange?: (tabId: string) => void;
  /** Controlled search text. A non-empty query searches every tab, the way the field says it does. */
  query?: string;
  defaultQuery?: string;
  onQueryChange?: (query: string) => void;
  /** A tap, Enter or Space on a sticker. This is the path the keyboard has to the same result. */
  onSelect?: (sticker: Sticker) => void;
  /** A sticker dragged out of the sheet and let go. Pointer only; see the file comment. */
  onPlace?: (sticker: Sticker, placement: StickerPlacement) => void;
  /** Escape and a tap outside the sheet. */
  onDismiss?: () => void;
  /** False plays the exit and then calls `onExited`, so the caller can unmount the sheet. */
  open?: boolean;
  onExited?: () => void;
  /**
   * Seek whichever direction `open` selects to this fraction (0..1) instead of playing it, which is
   * what the harness does. A seeked exit poses the sheet and never reports through `onExited`, and it
   * turns the drag affordance off.
   */
  progress?: number;
  /** The sheet box. Defaults are the plus menu's measured one. */
  left?: number;
  top?: number;
  width?: number;
  height?: number;
  /** The sheet's drag bar. */
  grabber?: boolean;
  /** False drops the search row and gives the grid its height. */
  search?: boolean;
  /** Accessible name for the sheet. */
  label?: string;
  searchPlaceholder?: string;
  emptyLabel?: string;
};

export function StickerPicker({
  tabs = stickerPickerTabs,
  tab: tabProp,
  defaultTab,
  onTabChange,
  query: queryProp,
  defaultQuery,
  onQueryChange,
  onSelect,
  onPlace,
  onDismiss,
  open = true,
  onExited,
  progress,
  left = stickerPickerMetrics.sheet.left,
  top = stickerPickerMetrics.sheet.top,
  width = stickerPickerMetrics.sheet.width,
  height = stickerPickerMetrics.sheet.height,
  grabber = true,
  search = true,
  label = "Stickers",
  searchPlaceholder = "Search",
  emptyLabel = "No Stickers",
  className,
  style,
  ...props
}: StickerPickerProps) {
  const m = stickerPickerMetrics;
  const id = useId();

  const [internalTab, setInternalTab] = useState(defaultTab ?? tabs[0]?.id ?? "");
  const activeTabId = tabProp ?? internalTab;
  const [internalQuery, setInternalQuery] = useState(defaultQuery ?? "");
  const query = queryProp ?? internalQuery;

  const root = useRef<HTMLDivElement>(null);
  const sheet = useRef<HTMLDivElement>(null);
  const content = useRef<HTMLDivElement>(null);
  const strip = useRef<HTMLDivElement>(null);

  /**
   * The sheet outlives the `open` prop so the dismissal has frames to run in, and `closing` is derived
   * DURING RENDER rather than in an effect: an effect leaves one committed frame with the sheet
   * already gone and the exit never runs. Same rule as `ios-plus-menu.tsx`.
   */
  const [seenOpen, setSeenOpen] = useState(open);
  const [closing, setClosing] = useState(false);
  if (seenOpen !== open) {
    setSeenOpen(open);
    setClosing(!open);
  }

  /**
   * The callback lives in a ref, not in the timeline effect's dependencies. A caller that passes an
   * inline arrow hands us a new identity on the render `onExited` itself causes, and a dependency on
   * it would tear the finished exit down and start it again from the top.
   */
  const exitedCallback = useRef(onExited);
  useEffect(() => {
    exitedCallback.current = onExited;
  });
  const reported = useRef(false);

  const activeTab = tabs.find(entry => entry.id === activeTabId) ?? tabs[0];
  const searching = query.trim().length > 0;
  const matches = useMemo(() => {
    if (!searching) return activeTab?.stickers ?? [];
    const needle = query.trim().toLowerCase();
    const seen = new Set<string>();
    const found: Sticker[] = [];
    for (const entry of tabs) {
      for (const sticker of entry.stickers) {
        if (seen.has(sticker.id)) continue;
        if (!`${sticker.label} ${sticker.keywords ?? ""}`.toLowerCase().includes(needle)) continue;
        seen.add(sticker.id);
        found.push(sticker);
      }
    }
    return found;
  }, [searching, query, tabs, activeTab]);

  const columns = searching ? m.grid.columns : (activeTab?.columns ?? (activeTab?.icon === "emoji" ? m.grid.emojiColumns : m.grid.columns));
  const tileSize = (width - 2 * m.grid.inset - (columns - 1) * m.grid.gap) / columns;

  const searchHeight = search ? m.search.top + m.search.rowHeight : 0;

  /**
   * One Web Animations timeline over the sheet's contents and its strip, run forwards or backwards.
   * Both keyframe sets are constants, so `document.getAnimations()` reaches them and a seeked frame is
   * a pure function of `progress`. The direction comes off `open`, which is a render value.
   */
  useEffect(() => {
    const sheetNode = sheet.current;
    const contentNode = content.current;
    const stripNode = strip.current;
    if (!sheetNode || !contentNode || !stripNode) return;
    if (open) reported.current = false;
    const isClosing = !open;
    const duration = isClosing ? m.timing.exit : m.timing.enter;
    const originX = m.origin.centerX - left;
    const originY = m.origin.centerY - top;
    // The contents grow out of the Stickers row's icon rather than out of the sheet's own centre.
    const away: Keyframe = { opacity: 0, transform: "scale(0.92)" };
    const settled: Keyframe = { opacity: 1, transform: "scale(1)" };
    const stripAway: Keyframe = { opacity: 0, transform: `translateY(${m.strip.height}px)` };
    const stripSettled: Keyframe = { opacity: 1, transform: "translateY(0px)" };
    const finish = () => {
      if (reported.current) return;
      reported.current = true;
      exitedCallback.current?.();
    };
    // Scrubbing is inspection, not a dismissal: a seeked exit poses the sheet and reports nothing.
    const reports = isClosing && progress === undefined;
    const reduced = typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches;
    contentNode.style.transformOrigin = `${originX}px ${originY}px`;
    if (reduced) {
      if (!reports) return;
      const frame = requestAnimationFrame(finish);
      return () => cancelAnimationFrame(frame);
    }
    const easing = isClosing ? m.exitEasing : m.enterEasing;
    const options: KeyframeAnimationOptions = { duration, easing, fill: "both" };
    const fade: Keyframe[] = [{ opacity: 0 }, { opacity: 1 }];
    const sheetAnimation = sheetNode.animate(isClosing ? [...fade].reverse() : fade, options);
    const contentAnimation = contentNode.animate(isClosing ? [settled, away] : [away, settled], options);
    const stripAnimation = stripNode.animate(isClosing ? [stripSettled, stripAway] : [stripAway, stripSettled], options);
    const animations = [sheetAnimation, contentAnimation, stripAnimation];
    if (progress !== undefined) {
      const time = clamp01(progress) * duration;
      for (const animation of animations) {
        animation.pause();
        animation.currentTime = time;
      }
      return () => {
        for (const animation of animations) animation.cancel();
      };
    }
    if (!isClosing) {
      return () => {
        for (const animation of animations) animation.cancel();
      };
    }
    contentAnimation.addEventListener("finish", finish);
    return () => contentAnimation.removeEventListener("finish", finish);
  }, [open, progress, left, top, m.timing.enter, m.timing.exit, m.origin.centerX, m.origin.centerY, m.strip.height, m.enterEasing, m.exitEasing]);

  // Escape closes it, so the sheet never depends on a tap outside to get out of the way.
  useEffect(() => {
    if (!open || !onDismiss) return;
    const onKey = (event: globalThis.KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      onDismiss();
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [open, onDismiss]);

  const selectTab = useCallback(
    (next: string) => {
      if (tabProp === undefined) setInternalTab(next);
      onTabChange?.(next);
    },
    [tabProp, onTabChange],
  );

  const setQuery = useCallback(
    (next: string) => {
      if (queryProp === undefined) setInternalQuery(next);
      onQueryChange?.(next);
    },
    [queryProp, onQueryChange],
  );

  // One tab stop for the grid, arrows to move inside it, the way a native grid behaves. The roving
  // index is clamped during render, so a tab that shrinks under it cannot strand the tab stop.
  const [active, setActive] = useState(0);
  const activeIndex = Math.min(active, Math.max(0, matches.length - 1));
  const onGridKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const step =
      event.key === "ArrowRight" ? 1
      : event.key === "ArrowLeft" ? -1
      : event.key === "ArrowDown" ? columns
      : event.key === "ArrowUp" ? -columns
      : 0;
    let next = step ? activeIndex + step : activeIndex;
    if (event.key === "Home") next = 0;
    if (event.key === "End") next = matches.length - 1;
    if (!step && event.key !== "Home" && event.key !== "End") return;
    if (next < 0 || next >= matches.length) return;
    event.preventDefault();
    setActive(next);
    event.currentTarget.querySelector<HTMLButtonElement>(`[data-index="${next}"]`)?.focus();
  };

  const onTabsKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const index = tabs.findIndex(entry => entry.id === activeTabId);
    const step = event.key === "ArrowRight" ? 1 : event.key === "ArrowLeft" ? -1 : 0;
    let next = step ? index + step : index;
    if (event.key === "Home") next = 0;
    if (event.key === "End") next = tabs.length - 1;
    if (!step && event.key !== "Home" && event.key !== "End") return;
    if (next < 0 || next >= tabs.length) return;
    event.preventDefault();
    selectTab(tabs[next].id);
    event.currentTarget.querySelector<HTMLButtonElement>(`[data-tab="${tabs[next].id}"]`)?.focus();
  };

  /**
   * The drag affordance. Pointer only, and off while `progress` is scrubbing: a drag is an interaction
   * and would put a pointer's position into a frame the harness expects to be a pure function of one
   * scalar. Everything it can do, a tap can also do, so the keyboard loses nothing.
   */
  const [drag, setDrag] = useState<DragState | null>(null);
  const pending = useRef<{ sticker: Sticker; pointerId: number; startX: number; startY: number; source: DragState["source"] } | null>(null);
  const suppressClick = useRef(false);
  const ghost = useRef<HTMLDivElement>(null);
  const dragEnabled = progress === undefined && (onPlace !== undefined);

  const rootPoint = (clientX: number, clientY: number) => {
    const rect = root.current?.getBoundingClientRect();
    return { x: clientX - (rect?.left ?? 0), y: clientY - (rect?.top ?? 0) };
  };

  const onTilePointerDown = (event: ReactPointerEvent<HTMLButtonElement>, sticker: Sticker) => {
    // Cleared here, not after the click it suppresses: a drag that ends off the tile may never produce
    // a click at all, and a flag left standing would swallow the next real tap.
    suppressClick.current = false;
    if (!dragEnabled || event.button !== 0) return;
    const rect = root.current?.getBoundingClientRect();
    const tile = event.currentTarget.getBoundingClientRect();
    if (!rect) return;
    pending.current = {
      sticker,
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      // The position comes off the live rect, the size off the layout. Lifting a tile mid-entrance
      // would otherwise scale the ghost by whatever the entrance had reached.
      source: { left: tile.left - rect.left, top: tile.top - rect.top, size: tileSize },
    };
    event.currentTarget.setPointerCapture(event.pointerId);
  };

  const onTilePointerMove = (event: ReactPointerEvent<HTMLButtonElement>) => {
    const start = pending.current;
    if (!start || start.pointerId !== event.pointerId) return;
    const point = rootPoint(event.clientX, event.clientY);
    if (!drag) {
      const moved = Math.hypot(event.clientX - start.startX, event.clientY - start.startY);
      if (moved < m.drag.threshold) return;
      suppressClick.current = true;
      setDrag({
        sticker: start.sticker,
        pointerId: event.pointerId,
        x: point.x,
        y: point.y,
        size: start.source.size * m.drag.liftScale,
        rotation: stickerDragRotation(start.sticker.id),
        source: start.source,
      });
      return;
    }
    setDrag(current => (current ? { ...current, x: point.x, y: point.y } : current));
  };

  const endDrag = (event: ReactPointerEvent<HTMLButtonElement>) => {
    const start = pending.current;
    if (start && start.pointerId === event.pointerId) pending.current = null;
    if (!drag || drag.pointerId !== event.pointerId) return;
    const point = rootPoint(event.clientX, event.clientY);
    const insideSheet =
      point.x >= left && point.x <= left + width && point.y >= top && point.y <= top + height;
    if (!insideSheet) {
      onPlace?.(drag.sticker, { x: point.x, y: point.y, rotation: drag.rotation, size: drag.size });
      setDrag(null);
      return;
    }
    // Let go over the sheet: the sticker goes home. A Web Animations run, so this is reachable through
    // `document.getAnimations()` like everything else that moves here.
    const node = ghost.current;
    const reduced = typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (!node || reduced) {
      setDrag(null);
      return;
    }
    const home = drag.source;
    const animation = node.animate(
      [
        { transform: `translate(${drag.x - drag.size / 2}px, ${drag.y - drag.size / 2}px) rotate(${drag.rotation}deg) scale(1)` },
        { transform: `translate(${home.left}px, ${home.top}px) rotate(0deg) scale(${home.size / drag.size})` },
      ],
      { duration: m.timing.settle, easing: m.dragEasing, fill: "both" },
    );
    animation.addEventListener("finish", () => setDrag(null));
  };

  const alive = open || closing;

  return (
    <div
      ref={root}
      data-slot="sticker-picker"
      data-picker={id}
      data-state={open ? "open" : closing ? "closing" : "closed"}
      className={cn("absolute inset-0 z-20 select-none", vars, className)}
      style={{ fontFamily: fontStack, pointerEvents: "none", ...style }}
      {...props}
    >
      {/* A scrim, not a control: invisible, full screen, and both Escape and the caller's own close
          control do the same job, so it stays out of the tab order and the accessibility tree. */}
      {alive && onDismiss ? (
        <div aria-hidden="true" data-slot="dismiss" onClick={onDismiss} className="pointer-events-auto absolute inset-0 cursor-default" />
      ) : null}

      <div
        ref={sheet}
        data-slot="sheet"
        role="group"
        aria-label={label}
        // A closed sheet is not just invisible: `inert` takes its field, grid and tabs out of the tab
        // order and out of the accessibility tree, which `opacity: 0` on its own would not.
        inert={!open}
        className="pointer-events-auto absolute overflow-hidden"
        style={{
          left,
          top,
          width,
          height,
          borderRadius: m.sheet.radius,
          ...continuous,
          background: "rgb(var(--ios-sp-glass) / var(--ios-sp-alpha))",
          boxShadow: "0 5px 30px 6px rgb(0 0 0 / var(--ios-sp-shadow-alpha)), var(--ios-sp-rim)",
          backdropFilter: "blur(45px) saturate(1.9)",
          WebkitBackdropFilter: "blur(45px) saturate(1.9)",
        }}
      >
        <div ref={content} data-slot="sheet-content" className="absolute inset-0">
          {grabber ? (
            <span
              aria-hidden="true"
              data-slot="grabber"
              className="pointer-events-none absolute left-1/2 [background:rgba(0,0,0,0.3)] dark:[background:rgba(255,255,255,0.3)]"
              style={{
                top: m.grabber.top,
                width: m.grabber.width,
                height: m.grabber.height,
                marginLeft: -m.grabber.width / 2,
                borderRadius: m.grabber.radius,
              }}
            />
          ) : null}

          {search ? (
            <div data-slot="search-row" className="absolute flex items-center" style={{ left: m.grid.inset, right: m.grid.inset, top: m.search.top, height: m.search.rowHeight }}>
              <div
                className="relative w-full"
                style={{ height: m.search.fieldHeight, borderRadius: m.search.radius, background: "var(--ios-sp-field)" }}
              >
                <span aria-hidden="true" className="pointer-events-none absolute flex" style={{ left: 10, top: (m.search.fieldHeight - 18.6667 * m.search.glyphScale) / 2 }}>
                  <SearchGlyph scale={m.search.glyphScale} />
                </span>
                <input
                  type="search"
                  data-slot="search-field"
                  aria-label={`Search ${label}`}
                  placeholder={searchPlaceholder}
                  value={query}
                  onChange={event => setQuery(event.target.value)}
                  className="size-full bg-transparent outline-none placeholder:[color:var(--ios-sp-muted)] focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-[#0088ff] [&::-webkit-search-cancel-button]:appearance-none"
                  style={{
                    paddingLeft: m.search.textInset,
                    paddingRight: 10,
                    borderRadius: m.search.radius,
                    fontSize: m.search.fontSize,
                    fontWeight: m.search.weight,
                    letterSpacing: 0,
                    color: "var(--ios-sp-label)",
                  }}
                />
              </div>
            </div>
          ) : null}

          <div
            data-slot="grid-scroller"
            className="absolute overflow-y-auto overflow-x-hidden [overscroll-behavior:contain]"
            style={{ left: 0, right: 0, top: searchHeight, bottom: m.strip.height, padding: m.grid.inset }}
          >
            {matches.length === 0 ? (
              <p data-slot="empty" className="w-full text-center" style={{ marginTop: 48, fontSize: 15, color: "var(--ios-sp-muted)" }}>
                {emptyLabel}
              </p>
            ) : (
              <div
                data-slot="grid"
                role="group"
                aria-label={searching ? `${label} results` : activeTab?.label ?? label}
                onKeyDown={onGridKeyDown}
                className="grid"
                style={{ gridTemplateColumns: `repeat(${columns}, ${tileSize}px)`, gap: m.grid.gap }}
              >
                {matches.map((sticker, index) => (
                  <button
                    key={sticker.id}
                    type="button"
                    data-slot="sticker"
                    data-index={index}
                    data-sticker={sticker.id}
                    data-dragging={drag?.sticker.id === sticker.id ? "true" : undefined}
                    aria-label={sticker.label}
                    tabIndex={index === activeIndex ? 0 : -1}
                    onFocus={() => setActive(index)}
                    onPointerDown={event => onTilePointerDown(event, sticker)}
                    onPointerMove={onTilePointerMove}
                    onPointerUp={endDrag}
                    onPointerCancel={endDrag}
                    onClick={() => {
                      if (suppressClick.current) {
                        suppressClick.current = false;
                        return;
                      }
                      onSelect?.(sticker);
                    }}
                    className="block touch-none p-0 focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-[#0088ff]"
                    style={{ width: tileSize, height: tileSize, opacity: drag?.sticker.id === sticker.id ? 0 : undefined }}
                  >
                    <StickerArt sticker={sticker} size={tileSize} />
                  </button>
                ))}
              </div>
            )}
          </div>

          <div
            ref={strip}
            data-slot="tab-strip"
            role="tablist"
            aria-label={`${label} categories`}
            aria-orientation="horizontal"
            onKeyDown={onTabsKeyDown}
            className="absolute bottom-0 left-0 flex w-full items-stretch overflow-x-auto"
            style={{
              height: m.strip.height,
              paddingLeft: m.strip.gutter,
              paddingRight: m.strip.gutter,
              gap: m.strip.spacing,
              boxShadow: `inset 0 ${m.strip.hairline}px 0 0 var(--ios-sp-separator)`,
            }}
          >
            {tabs.map(entry => {
              const selected = entry.id === activeTabId;
              return (
                <Fragment key={entry.id}>
                  {entry.separatorBefore ? (
                    <span aria-hidden="true" data-slot="tab-separator" className="block shrink-0 self-center" style={{ width: m.strip.separatorWidth, height: m.strip.itemHeight, background: "var(--ios-sp-separator)" }} />
                  ) : null}
                  <button
                    type="button"
                    role="tab"
                    data-slot="tab"
                    data-tab={entry.id}
                    aria-selected={selected}
                    aria-label={entry.label}
                    tabIndex={entry.id === activeTabId ? 0 : -1}
                    onClick={() => {
                      selectTab(entry.id);
                      setQuery("");
                    }}
                    className="flex shrink-0 items-center justify-center focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-[#0088ff]"
                    style={{
                      width: m.strip.itemWidth,
                      height: m.strip.itemHeight,
                      borderRadius: m.grid.tileRadius,
                      ...continuous,
                      // The selection sits inside the item box, so the strip's own 38 pitch is intact.
                      background: selected ? "var(--ios-sp-tab-selected)" : "transparent",
                      backgroundClip: "padding-box",
                      padding: m.strip.selectionInset,
                      color: selected ? "var(--ios-sp-label)" : "var(--ios-sp-muted)",
                    }}
                  >
                    <TabGlyph icon={entry.icon} size={m.strip.iconSize} />
                  </button>
                </Fragment>
              );
            })}
          </div>
        </div>
      </div>

      {/*
        The lifted sticker. It lives outside the sheet so it can be carried over the transcript, and it
        is inert to the accessibility tree: the button it came from still carries the name, and letting
        go over the transcript reaches the same handler a tap does.
      */}
      {drag ? (
        <div
          ref={ghost}
          aria-hidden="true"
          data-slot="drag-ghost"
          className="pointer-events-none absolute left-0 top-0"
          style={{
            width: drag.size,
            height: drag.size,
            transform: `translate(${drag.x - drag.size / 2}px, ${drag.y - drag.size / 2}px) rotate(${drag.rotation}deg)`,
            filter: `drop-shadow(0 ${m.drag.shadowLift}px ${m.drag.shadowBlur}px var(--ios-sp-ghost-shadow))`,
          }}
        >
          <StickerArt sticker={drag.sticker} size={drag.size} />
        </div>
      ) : null}
    </div>
  );
}

"use client";

import { createContext, useContext, useEffect, useLayoutEffect, useRef, useState, type ComponentProps, type CSSProperties, type KeyboardEvent, type ReactNode } from "react";
import { cn } from "@/lib/utils";

/**
 * iOS 26 message selection mode, measured from `references/ios/captures/select-mode-dark.png`
 * (402×874 @3x).
 *
 * - A Ø21.67 circle sits centred on x 23.83, vertically centred on each bubble body. Unselected is
 *   a 1.67pt ring (#464649 over black); selected is a solid #0091ff disc with a 9.67 white check
 *   (1.5pt stroke).
 * - The bubbles do **not** move: the last one still ends at x 386, exactly where it sits normally.
 * - The nav bar's back button is gone; a Ø44 glass circle with a 17×17 ✕ takes its place at
 *   (364, 84), i.e. mirrored to the trailing edge.
 * - The bottom toolbar is two Ø48 glass circles centred (52, 822) and (350, 822): a 21×24 trash and
 *   a 23×19.67 forward arrow. In dark the glass body reads #191919 (rgba(28,28,28,0.9) over black)
 *   with a #f4f3f4 glyph, and its outermost ring reads #2e2e2e–#363636: the 1px inset rim.
 *
 * ## Motion: what is measured and what is not
 *
 * **Measured**: both end poses. At rest the screen is the capture above, to the point; at `t = 0`
 * every travel distance below is read off that same capture, so the circles leave from the screen's
 * own leading edge and the toolbar leaves from its own bottom edge rather than from nowhere.
 *
 * **NOT measured**: the durations, the easings, and the order things move in. No capture in this
 * repo records select mode in motion. The numbers in `selectModeMotion` are borrowed, not derived:
 *
 * - `enter` 260 / `exit` 200 with `cubic-bezier(0.32, 0.72, 0, 1)` in and `cubic-bezier(0.4, 0, 1, 1)`
 *   out are the measured "Send with effect" screen's timings (`ios-effects-picker.tsx`), which
 *   `message-reply.tsx` already reuses for the same reason.
 * - `fill` 220 with `cubic-bezier(0.2, 0.95, 0.3, 1)` is the long-press menu's spring curve from
 *   `message-actions.tsx`, at the same 220 the effects screen moves its preview rows.
 * - The close button grows from 0.86, which is the plus menu sheet's scale in `ios-plus-menu.tsx`.
 *
 * Everything animated is one number, `--ios-sel-t`, going 0 → 1: the circles slide in from the
 * leading edge and fade while the log shifts by `shift`, so the two never cross; the ✕ grows in at
 * the trailing edge of the nav bar; the toolbar rises from below while the composer it replaces goes
 * down. `active={false}` reverses all of it and then calls `onExited`.
 *
 * `progress` (0..1) seeks that timeline instead of playing it, which is what the harness scrubs. A
 * seeked frame carries no transition at all, so the same checkpoint renders identically every run;
 * the live path is a plain CSS transition, so `document.getAnimations()` can reach every part of it.
 * `prefers-reduced-motion: reduce` drops the transitions and the surface simply appears.
 *
 * The parent has to keep this mounted until `onExited`, and it has to derive that "closing" state
 * DURING RENDER, not in an effect: an effect leaves one committed frame with the rows already gone
 * and the exit never runs. `ios-messages-app.tsx` does the same for the long-press overlay.
 *
 *     const [seen, setSeen] = useState(selecting);
 *     const [closing, setClosing] = useState(false);
 *     if (seen !== selecting) { setSeen(selecting); setClosing(!selecting); }   // during render
 *     {(selecting || closing) && (
 *       <IosSelectMode active={selecting} onExited={() => setClosing(false)}>…</IosSelectMode>
 *     )}
 */

const font = "-apple-system, BlinkMacSystemFont, sans-serif";

/**
 * `box-shadow` only accepts `none` on its own, so `none, <shadow>` drops the whole declaration and
 * the glass loses both its shadow and its rim. Every slot holds a real shadow and the unused one is
 * fully transparent. The classes are written out in full: Tailwind only compiles what it can read
 * literally in the source.
 */
const vars =
  "[--ios-sel-ring:rgba(60,60,67,0.3)] [--ios-sel-check:#ffffff] [--ios-sel-tint:#0088ff] " +
  "[--ios-sel-glass:rgba(255,255,255,0.9)] [--ios-sel-rim:0_0_0_0_rgba(0,0,0,0)] [--ios-sel-shadow:0_5px_20px_6px_rgba(0,0,0,0.055)] [--ios-sel-glyph:#1a1919] " +
  "dark:[--ios-sel-ring:#464649] dark:[--ios-sel-tint:#0091ff] " +
  "dark:[--ios-sel-glass:rgba(28,28,28,0.9)] dark:[--ios-sel-rim:inset_0_0_0_1px_rgba(255,255,255,0.09)] dark:[--ios-sel-shadow:0_0_0_0_rgba(0,0,0,0)] dark:[--ios-sel-glyph:#f4f3f4]";

/** Measured selection geometry, in points. */
export const selectionMetrics = { circleSize: 21.6667, circleCenterX: 23.8333, ringWidth: 1.6667, checkSize: 9.6667, toolbarButton: 48, toolbarCenterY: 822 } as const;

const ENTER_CURVE = [0.32, 0.72, 0, 1] as const;
const EXIT_CURVE = [0.4, 0, 1, 1] as const;
const FILL_CURVE = [0.2, 0.95, 0.3, 1] as const;
const curveText = (curve: readonly number[]) => `cubic-bezier(${curve.join(", ")})`;

/**
 * Durations and travel. The two distances are measured; the four times and three curves are not.
 * See the file comment for where each one was borrowed from.
 */
export const selectModeMotion = {
  enter: 260,
  exit: 200,
  /** One selection circle filling, or emptying. */
  fill: 220,
  ease: curveText(ENTER_CURVE),
  exitEase: curveText(EXIT_CURVE),
  fillEase: curveText(FILL_CURVE),
  /**
   * How far a circle travels. Measured: at 0 its trailing edge sits on the screen's leading edge,
   * so it is the settled centre plus its own radius.
   */
  circleSlide: selectionMetrics.circleCenterX + selectionMetrics.circleSize / 2,
  /**
   * How far the toolbar travels. Measured: the buttons' 798 top edge (centre 822 less the Ø48's
   * radius) down to the 874 screen bottom.
   */
  toolbarRise: 76,
  /** The ✕ grows from here, the plus menu sheet's scale. Not measured. */
  closeScale: 0.86,
} as const;

function clamp01(value: number) {
  return Math.max(0, Math.min(1, value));
}

/**
 * A CSS `cubic-bezier` evaluated in JS, so a seeked frame lands on the pose the played transition
 * would have been in at that fraction of its own duration. Newton first, bisection when Newton
 * wanders off the curve (which it does near a zero-slope control point like this one's `0, 1`).
 */
function cubicBezier(x1: number, y1: number, x2: number, y2: number) {
  const cx = 3 * x1, bx = 3 * (x2 - x1) - cx, ax = 1 - cx - bx;
  const cy = 3 * y1, by = 3 * (y2 - y1) - cy, ay = 1 - cy - by;
  const atX = (t: number) => ((ax * t + bx) * t + cx) * t;
  const slopeX = (t: number) => (3 * ax * t + 2 * bx) * t + cx;
  return (progress: number) => {
    const p = clamp01(progress);
    if (p === 0 || p === 1) return p;
    let t = p;
    for (let i = 0; i < 8; i++) {
      const error = atX(t) - p;
      if (Math.abs(error) < 1e-7) break;
      const slope = slopeX(t);
      if (Math.abs(slope) < 1e-7) break;
      t -= error / slope;
    }
    if (!(t >= 0 && t <= 1) || Math.abs(atX(t) - p) > 1e-5) {
      let low = 0, high = 1;
      for (let i = 0; i < 30; i++) {
        t = (low + high) / 2;
        if (atX(t) < p) low = t; else high = t;
      }
    }
    return ((ay * t + by) * t + cy) * t;
  };
}

const enterCurve = cubicBezier(...ENTER_CURVE);
const exitCurve = cubicBezier(...EXIT_CURVE);

/** Live, so a viewer who turns motion off mid-session gets the settled pose without a reload. */
function usePrefersReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    if (typeof matchMedia !== "function") return;
    const query = matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => setReduced(query.matches);
    sync();
    query.addEventListener("change", sync);
    return () => query.removeEventListener("change", sync);
  }, []);
  return reduced;
}

export type SelectModeMotionProps = {
  /** True enters select mode, false plays the exit and then calls `onExited`. */
  active?: boolean;
  /**
   * Seek the transition currently running to this fraction (0..1) instead of playing it, which is
   * what the harness does. A seeked exit is a picture, not a lifecycle: it never calls `onExited`.
   */
  progress?: number;
  onExited?: () => void;
};

export type SelectModeTransition = {
  /** 0 = no select mode, 1 = settled. Published as `--ios-sel-t`; every animated style reads it. */
  t: number;
  /** `<duration> <easing>` for the direction now running, or "" when the pose is seeked or reduced. */
  timing: string;
};

const SelectModeContext = createContext<SelectModeTransition | null>(null);

/**
 * The whole entrance and exit as one number. Call it once at the top of a select-mode screen (or let
 * `IosSelectMode` do it) and every piece below picks the result up from context.
 */
export function useSelectModeTransition({ active = true, progress, onExited }: SelectModeMotionProps = {}): SelectModeTransition {
  const reduced = usePrefersReducedMotion();
  const seeking = progress !== undefined;

  // Derived DURING RENDER, not in an effect: `onExited` must fire for an open surface that closes
  // and never for one that mounted closed, and the exit has to be committed on the frame `active`
  // goes false or there is nothing left on screen to animate out.
  const [seenActive, setSeenActive] = useState(active);
  const [closing, setClosing] = useState(false);
  if (seenActive !== active) {
    setSeenActive(active);
    setClosing(!active);
  }

  const exited = useRef(onExited);
  useEffect(() => { exited.current = onExited; }, [onExited]);
  useEffect(() => {
    if (!closing || seeking) return;
    const timer = setTimeout(() => { setClosing(false); exited.current?.(); }, reduced ? 0 : selectModeMotion.exit);
    return () => clearTimeout(timer);
  }, [closing, seeking, reduced]);

  const t = seeking
    ? (active ? enterCurve(progress) : 1 - exitCurve(progress))
    : (active ? 1 : 0);
  const timing = seeking || reduced
    ? ""
    : `${active ? selectModeMotion.enter : selectModeMotion.exit}ms ${active ? selectModeMotion.ease : selectModeMotion.exitEase}`;
  return { t, timing };
}

/** `transition` for the properties given, or nothing at all when the frame is seeked. */
function transitionFor(timing: string, ...properties: string[]) {
  return timing ? properties.map(property => `${property} ${timing}`).join(", ") : undefined;
}

/** Own props win over the context, so one piece can be driven on its own inside a settled screen. */
function useSelectMotion(props: SelectModeMotionProps): SelectModeTransition {
  const own = useSelectModeTransition(props);
  const inherited = useContext(SelectModeContext);
  return props.active !== undefined || props.progress !== undefined || !inherited ? own : inherited;
}

/** The driver as inline custom properties, so a style rule elsewhere can read the same number. */
function motionVars(transition: SelectModeTransition): CSSProperties {
  return {
    "--ios-sel-t": transition.t.toFixed(4),
    "--ios-sel-transition": transition.timing ? `opacity ${transition.timing}` : "none",
  } as CSSProperties;
}

/**
 * Wrap a whole select-mode screen in this and every piece below animates together off one timeline.
 * It generates no box of its own (`display: contents`), so it can go around a screen whose children
 * are absolutely positioned in the frame's coordinates without moving any of them.
 *
 * A nav bar rendered inside it loses its back button to a cross-fade on the same timeline, which is
 * what the capture's settled state shows: no back button, a ✕ at the trailing edge instead.
 */
export function IosSelectMode({ active = true, progress, onExited, children }: SelectModeMotionProps & { children: ReactNode }) {
  const transition = useSelectModeTransition({ active, progress, onExited });
  return (
    <SelectModeContext.Provider value={transition}>
      <div data-slot="ios-select-mode" data-active={active || undefined} data-progress={transition.t.toFixed(3)} style={{ display: "contents", ...motionVars(transition) }}>
        <style>{
          '[data-slot="ios-select-mode"] [data-slot="ios-nav-bar"] [data-slot="back"]{opacity:calc(1 - var(--ios-sel-t));transition:var(--ios-sel-transition)}' +
          '[data-slot="ios-select-mode"][data-active] [data-slot="ios-nav-bar"] [data-slot="back"]{pointer-events:none}'
        }</style>
        {children}
      </div>
    </SelectModeContext.Provider>
  );
}

export type SelectionCircleProps = Omit<ComponentProps<"button">, "children" | "onChange"> & {
  selected?: boolean;
  onChange?: (next: boolean) => void;
  /** Accessible name, e.g. the message text. */
  label?: string;
  size?: number;
  /** Seek the fill (0..1) instead of transitioning it, the way `progress` seeks the entrance. */
  fillProgress?: number;
};

/**
 * The circle. Selecting fills it rather than swapping one glyph for another: the tint disc grows
 * from 0.4 out to the ring it sits inside, and the check wipes along its own path behind it. Both
 * are one number, `--ios-sel-fill`, so `fillProgress` seeks the whole thing.
 */
export function SelectionCircle({ selected = false, onChange, label, size = selectionMetrics.circleSize, fillProgress, className, style, ...rest }: SelectionCircleProps) {
  const reduced = usePrefersReducedMotion();
  const stroke = selectionMetrics.ringWidth * (size / selectionMetrics.circleSize);
  const fill = fillProgress === undefined ? (selected ? 1 : 0) : clamp01(fillProgress);
  const timing = fillProgress === undefined && !reduced ? `${selectModeMotion.fill}ms ${selectModeMotion.fillEase}` : "";
  return (
    <button type="button" data-slot="selection-circle" role="checkbox" aria-checked={selected} aria-label={label ?? (selected ? "Deselect message" : "Select message")}
      onClick={() => onChange?.(!selected)}
      className={cn("relative shrink-0 rounded-full focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#0088ff]", vars, className)}
      style={{ width: size, height: size, boxShadow: `inset 0 0 0 ${stroke}px var(--ios-sel-ring)`, "--ios-sel-fill": fill.toFixed(4), ...style } as CSSProperties}
      {...rest}>
      {/* The disc covers the ring completely at 1, which is why the ring can stay put underneath. */}
      <span aria-hidden="true" data-slot="fill" className="absolute inset-0 rounded-full"
        style={{ background: "var(--ios-sel-tint)", opacity: "var(--ios-sel-fill)", transform: "scale(calc(0.4 + 0.6 * var(--ios-sel-fill)))", transition: transitionFor(timing, "opacity", "transform") }} />
      <svg aria-hidden="true" data-slot="check" className="absolute" width={size} height={size} viewBox="0 0 21.6667 21.6667" fill="none"
        stroke="var(--ios-sel-check)" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" style={{ left: 0, top: 0 }}>
        {/* `pathLength` makes the dash lengths a fraction of the stroke, so the wipe needs no
            measurement of the path and stays right at any `size`. */}
        <path d="M6 11.4 9.35 14.75 15.67 6.92" pathLength={1}
          style={{ strokeDasharray: "1px 1px", strokeDashoffset: "calc((1 - var(--ios-sel-fill)) * 1px)", opacity: "var(--ios-sel-fill)", transition: transitionFor(timing, "stroke-dashoffset", "opacity") }} />
      </svg>
    </button>
  );
}

export type MessageSelectionRowProps = Omit<ComponentProps<"div">, "onChange"> & SelectModeMotionProps & {
  selected?: boolean;
  onChange?: (next: boolean) => void;
  /** Off in the capture: bubbles keep their normal position while the circles overlay the gutter. */
  shift?: number;
  label?: string;
  circleCenterX?: number;
  /** Seek this row's fill, e.g. to screenshot a selection mid-tick. */
  fillProgress?: number;
  children: ReactNode;
};

/**
 * One row of the selection list: the circle in the left gutter plus the message itself.
 *
 * The circle is centred on the bubble **body**, not on the row. The two only agree when the row is
 * a bare bubble: a reaction balloon adds 28 of headroom above the body and a status line adds a
 * row of type below it, and in `select-mode-dark.png` neither moves the circle. The reacted "Ok"
 * bubble makes the difference visible: its body runs y 552.67–592.33 and the capture's circle is
 * centred on 572.33, which is the body's centre, while the row's centre sits 13.83 higher.
 *
 * Entering, the circle slides out of the leading edge and fades while the content moves right by
 * `shift` on the same curve, so the two are never on top of each other on the way in. `shift` is 0
 * in the capture, which makes that half of the motion a no-op unless a caller asks for it.
 */
export function MessageSelectionRow({ selected = false, onChange, shift = 0, label, circleCenterX = selectionMetrics.circleCenterX, fillProgress, active, progress, onExited, className, style, children, ...props }: MessageSelectionRowProps) {
  const transition = useSelectMotion({ active, progress, onExited });
  const size = selectionMetrics.circleSize;
  const row = useRef<HTMLDivElement>(null);
  useLayoutEffect(() => {
    const root = row.current;
    if (!root) return;
    const measure = () => {
      const body = root.querySelector<HTMLElement>('[data-slot="bubble"], [data-slot="emoji"]');
      const box = root.getBoundingClientRect();
      const centre = body ? body.getBoundingClientRect().top + body.getBoundingClientRect().height / 2 - box.top : box.height / 2;
      root.style.setProperty("--ios-sel-centre", `${centre.toFixed(2)}px`);
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(root);
    document.fonts?.ready.then(measure).catch(() => {});
    return () => observer.disconnect();
  }, [children]);
  const arrived = transition.t > 0.5;
  return (
    <div ref={row} data-slot="message-selection-row" data-selected={selected || undefined}
      className={cn("relative w-full", vars, className)} style={{ fontFamily: font, ...motionVars(transition), ...style }} {...props}>
      {/* `flex` keeps the wrapper exactly as tall as the circle: an inline box would add leading and pull the centre up. */}
      <span data-slot="selection-slot" className="absolute flex" inert={!arrived}
        style={{
          left: circleCenterX - size / 2, top: "var(--ios-sel-centre, 50%)",
          transform: `translateY(-50%) translateX(calc((var(--ios-sel-t) - 1) * ${selectModeMotion.circleSlide}px))`,
          opacity: "var(--ios-sel-t)",
          transition: transitionFor(transition.timing, "transform", "opacity"),
        }}>
        <SelectionCircle selected={selected} onChange={onChange} label={label} fillProgress={fillProgress} />
      </span>
      <div data-slot="row-content"
        style={shift ? { transform: `translateX(calc(var(--ios-sel-t) * ${shift}px))`, transition: transitionFor(transition.timing, "transform") } : undefined}>
        {children}
      </div>
    </div>
  );
}

function GlassButton({ size, label, onClick, disabled = false, tabIndex, style, children }: { size: number; label: string; onClick?: () => void; disabled?: boolean; tabIndex?: number; style?: CSSProperties; children: ReactNode }) {
  return (
    // `aria-disabled` rather than `disabled`: a toolbar keeps every button reachable so the arrow
    // keys can still walk past one that has nothing to act on.
    <button type="button" aria-label={label} aria-disabled={disabled || undefined} tabIndex={tabIndex} onClick={disabled ? undefined : onClick}
      className="absolute flex items-center justify-center rounded-full focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#0088ff]"
      style={{ width: size, height: size, background: "var(--ios-sel-glass)", boxShadow: "var(--ios-sel-rim), var(--ios-sel-shadow)", backdropFilter: "blur(24px)", WebkitBackdropFilter: "blur(24px)", color: "var(--ios-sel-glyph)", pointerEvents: "auto", ...style }}>
      {children}
    </button>
  );
}

export type IosSelectionCloseButtonProps = Omit<ComponentProps<"div">, "children"> & SelectModeMotionProps & { onClose?: () => void };

/**
 * The ✕ that replaces the nav bar's back button, at the trailing edge (364, 84). It grows in on the
 * screen's timeline, and Escape does what tapping it does: select mode is never a place you can be
 * stuck in with only a pointer.
 */
export function IosSelectionCloseButton({ onClose, active, progress, onExited, className, style, ...props }: IosSelectionCloseButtonProps) {
  const transition = useSelectMotion({ active, progress, onExited });
  const arrived = transition.t > 0.5;
  useEffect(() => {
    if (!onClose || !arrived) return;
    const onKey = (event: globalThis.KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      onClose();
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [onClose, arrived]);
  const grow = selectModeMotion.closeScale;
  return (
    // The wrapper spans the screen only so the button can be placed in its coordinates; it must not
    // swallow the taps meant for the selection circles underneath.
    <div data-slot="ios-selection-close" className={cn("pointer-events-none absolute inset-0 select-none", vars, className)}
      style={{ fontFamily: font, ...motionVars(transition), ...style }} {...props}>
      <GlassButton size={44} label="Done selecting" onClick={onClose}
        style={{
          left: 342, top: 62,
          opacity: "var(--ios-sel-t)",
          transform: `scale(calc(${grow} + ${(1 - grow).toFixed(4)} * var(--ios-sel-t)))`,
          transition: transitionFor(transition.timing, "opacity", "transform"),
          pointerEvents: arrived ? "auto" : "none",
        }}>
        {/* The capture puts the ✕ ink on x 355.0–372.0, y 76.0–93.0: a whole point of it is left of
            the circle's own centre once Blink has snapped the centred 17 box up from 355.5 to 356. */}
        <svg aria-hidden="true" width="17" height="17" viewBox="0 0 17 17" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" style={{ transform: "translateX(-1px)" }}>
          <path d="M1.1 1.1 15.9 15.9M15.9 1.1 1.1 15.9" />
        </svg>
      </GlassButton>
    </div>
  );
}

export type IosSelectionToolbarProps = Omit<ComponentProps<"div">, "children"> & SelectModeMotionProps & {
  count?: number;
  onDelete?: () => void;
  onForward?: () => void;
  /**
   * The composer row this toolbar replaces. Passed in rather than left to the caller so the two
   * cross on one timeline: the toolbar rises out of the bottom edge as the composer drops through
   * it. `ios-plus-menu.tsx` takes the same slot for the same reason.
   *
   * Hand it a composer in normal flow, not one that positions itself: the slot drops by its own
   * height, and a child that has taken itself out of flow leaves the slot no height to drop by.
   */
  composer?: ReactNode;
};

/**
 * The bottom toolbar: trash at (52, 822), forward at (350, 822), both Ø48 glass circles. It rises
 * from below the screen; give it the `composer` it replaces and that goes down as it comes up.
 */
export function IosSelectionToolbar({ count = 0, onDelete, onForward, composer, active, progress, onExited, className, style, ...props }: IosSelectionToolbarProps) {
  const transition = useSelectMotion({ active, progress, onExited });
  const arrived = transition.t > 0.5;
  const disabled = count === 0;
  // A toolbar is one tab stop; the arrow keys move between its buttons.
  const [focusIndex, setFocusIndex] = useState(0);
  const bar = useRef<HTMLDivElement>(null);
  function onKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
    const buttons = Array.from(bar.current?.querySelectorAll<HTMLButtonElement>("button") ?? []);
    if (!buttons.length) return;
    event.preventDefault();
    const from = buttons.indexOf(document.activeElement as HTMLButtonElement);
    const current = from < 0 ? focusIndex : from;
    const next = event.key === "Home" ? 0 : event.key === "End" ? buttons.length - 1 : event.key === "ArrowRight" ? (current + 1) % buttons.length : (current - 1 + buttons.length) % buttons.length;
    setFocusIndex(next);
    buttons[next]?.focus();
  }
  const button = (index: number): CSSProperties => ({
    top: -24, opacity: disabled ? 0.4 : 1,
    pointerEvents: arrived ? "auto" : "none",
    left: index === 0 ? 28 : 326,
  });
  return (
    <>
      {composer !== undefined && (
        // Not `display: none` at the far end: it has to be on screen to be seen leaving, so it is
        // pushed a whole height down and made inert instead.
        <div data-slot="composer-slot" className="absolute bottom-0 left-0 w-full" inert={arrived}
          style={{
            ...motionVars(transition),
            transform: "translateY(calc(var(--ios-sel-t) * 100%))",
            opacity: "max(0, 1 - var(--ios-sel-t) * 2.5)",
            transition: transitionFor(transition.timing, "transform", "opacity"),
          }}>
          {composer}
        </div>
      )}
      <div ref={bar} data-slot="ios-selection-toolbar" role="toolbar" aria-label="Selected messages" onKeyDown={onKeyDown}
        className={cn("pointer-events-none absolute bottom-0 left-0 h-[52px] w-full select-none", vars, className)}
        style={{
          fontFamily: font, ...motionVars(transition),
          transform: `translateY(calc((1 - var(--ios-sel-t)) * ${selectModeMotion.toolbarRise}px))`,
          // Up at full strength for most of the travel, but never painted outside a frame that
          // does not clip: the fade is spent in the first 40%.
          opacity: "min(1, var(--ios-sel-t) * 2.5)",
          transition: transitionFor(transition.timing, "transform", "opacity"),
          ...style,
        }} {...props}>
        <GlassButton size={48} label={`Delete ${count} message${count === 1 ? "" : "s"}`} disabled={disabled} onClick={onDelete}
          tabIndex={focusIndex === 0 ? 0 : -1} style={button(0)}>
          <svg aria-hidden="true" width="21" height="24" viewBox="0 0 21 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" style={{ transform: "translate(-0.6667px, -0.6667px)" }}>
            <path d="M0.8 4.8h19.4" />
            <path d="M7.2 4.8V2.6a1.8 1.8 0 0 1 1.8-1.8h3a1.8 1.8 0 0 1 1.8 1.8v2.2" />
            <path d="M2.9 4.8 4 21a2.2 2.2 0 0 0 2.2 2.2h8.6A2.2 2.2 0 0 0 17 21l1.1-16.2" />
            <path d="M7.7 9v9.4M10.5 9v9.4M13.3 9v9.4" />
          </svg>
        </GlassButton>
        <GlassButton size={48} label={`Forward ${count} message${count === 1 ? "" : "s"}`} disabled={disabled} onClick={onForward}
          tabIndex={focusIndex === 1 ? 0 : -1} style={button(1)}>
          <svg aria-hidden="true" width="23" height="19.6667" viewBox="0 0 23 19.6667" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinejoin="round" strokeLinecap="round" style={{ transform: "translateY(0.6667px)" }}>
            <path d="M13.1 0.9v4.9C5.9 6.2 1.5 10.4 0.9 18.8c2.4-4.5 6.3-6.6 12.2-6.6v4.9l9-8.1z" />
          </svg>
        </GlassButton>
      </div>
    </>
  );
}

"use client";

import { useEffect, useId, useRef, useState, type ComponentProps, type CSSProperties, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import { Avatar } from "@/components/imessage/avatar";
import { IosMicIcon } from "@/components/imessage/ios-composer";

/**
 * iOS 26 Messages search: the state the conversation list enters when the search field is pulled
 * down or tapped, and the results screen that replaces the list once there is a query.
 *
 * ## Where the numbers come from
 *
 * **Measured from a capture.** The search field itself is the one in
 * `references/ios/captures/list-light.png` / `list-dark.png`, carried over from
 * `ios-conversation-list.tsx` unchanged: a 48pt glass capsule inset 28 from both screen edges, radius
 * 24 (a plain circle, n = 2.045), resting at y 798-846; magnifier ring Ø13.49 centred (54.75, 820.22)
 * with a 1.725 stroke and a 2.467 handle; "Search" 17pt weight 500 at x 46.8; the mic 12.6667 x
 * 18.3333 inset 23.3333 from the pill's trailing edge. The 12pt gap to the button beside it is the
 * measured gap to the compose circle. Every row metric below that is shared with the conversation
 * list is also measured from those two frames: the 86.6667 row, the Ø45 avatar at x 26, the 17pt
 * semibold name at x 83, the 15pt secondary time whose ink ends at x 364, the chevron at x 376, the
 * 15pt/20 preview, and the separator from x 83 to 386. Colours are the list's measured tokens, and
 * the #0088ff / #0091ff tint is the measured iOS link colour (SPEC.md, "iOS colors").
 *
 * **Read out of the framework.** Nothing in `references/` holds a search *result*, so the results
 * screen is built from ChatKit 26.5 instead of a screenshot. Values were read at runtime off
 * `[[CKUIBehaviorPhone alloc] init]` (a Mac Catalyst probe that dlopens
 * `/System/iOSSupport/System/Library/PrivateFrameworks/ChatKit.framework/ChatKit`); every one of them
 * resolves to `-[CKUIBehavior …]`, which is the iPhone value because `CKUIBehaviorPhone` overrides
 * none of them. Each is named on the constant it feeds in `iosSearchMetrics`. The section titles, the
 * "See All" and "Cancel" labels and the "No Results" copy are the framework's own English strings out
 * of `ChatKit.framework/Versions/A/Resources/ChatKit.loctable`.
 *
 * Two structural facts also come from disassembly rather than guesswork:
 *
 * - `+[CKConversationSearchResultCell conversationListCellClass]` returns the ordinary conversation
 *   list cell at the default content size (it only swaps to `CKConversationLargeTextSearchCell` when
 *   `isAccessibilityPreferredContentSizeCategory` is YES), and
 *   `-[CKUIBehavior searchMessageCellHeightForDisplayScale:]` returns **86.66667** at scale 3, the
 *   conversation list's own row pitch. So a result row is a conversation row, at the measured pitch.
 * - `-[CKMessageSearchResultCell _annotatedResultStringForResult:searchText:]` builds the snippet by
 *   passing `searchMessagesBalloonFont` as **both** the primary and the annotated font and only
 *   swapping the colour: `secondaryLabelColor` to `labelColor` for an incoming message, and
 *   `searchMessagesFromMeUnannotatedLabelColor` (white at 0.6) to `+[UIColor whiteColor]` for one you
 *   sent. The match is therefore recoloured, never bolded. Before that it trims the snippet with
 *   `ck_trimmedStringWithPreferredLength:anchoredAroundSubstring:` at `searchMessagesMaxSummaryLength`
 *   (200), anchored on the match, which `trimAroundMatch` below reproduces.
 *
 * **Judgement, not measured.** Called out again on each constant: where the active field sits under
 * the status bar; the crossfade offsets and the 260/200 ms durations (reused from the measured
 * `effectsPickerMetrics.timing` of the "Send with effect" screen, which is a different screen, so they
 * carry no authority here); the Ø17 clear button; laying the Photos and Links sections out as
 * horizontal strips and the tile size that follows from `searchDefaultMaxResults`; and applying the
 * Documents cell's paddings to a link card. Do not quote any of those as measured.
 *
 * ## Motion
 *
 * One Web Animations timeline over four elements, so `document.getAnimations()` reaches it and
 * `progress` pauses and seeks every part to the same frame on every run. Closing runs the same
 * keyframes with `direction: "reverse"` and is read off the `open` prop **during render**, so the exit
 * always gets committed frames before `onExited` lets the caller unmount. `prefers-reduced-motion`
 * builds no animation at all: the screen is simply there, and a close still reports on the next frame.
 */

/** Section kinds, named after ChatKit's own controllers (`CKConversationSearchController` and friends). */
export type IosSearchSectionKind = "conversations" | "messages" | "photos" | "links";

export type IosSearchConversationResult = {
  id: string;
  name: string;
  initials?: string;
  /** The matching line. The part of it that matches the query is recoloured, not bolded. */
  preview: string;
  time: string;
};

export type IosSearchMessageResult = {
  id: string;
  /** Who sent it. */
  name: string;
  initials?: string;
  /** The chat it is in, shown ahead of the sender. */
  conversation?: string;
  text: string;
  time: string;
  /** Your own message: the balloon takes the outgoing fill and the match turns pure white. */
  fromMe?: boolean;
};

export type IosSearchPhotoResult = { id: string; src?: string; name: string; time: string };

export type IosSearchLinkResult = { id: string; title: string; domain: string; time: string; src?: string };

export type IosSearchResult =
  | IosSearchConversationResult
  | IosSearchMessageResult
  | IosSearchPhotoResult
  | IosSearchLinkResult;

export type IosSearchSection =
  | { kind: "conversations"; title?: string; results: IosSearchConversationResult[] }
  | { kind: "messages"; title?: string; results: IosSearchMessageResult[] }
  | { kind: "photos"; title?: string; results: IosSearchPhotoResult[] }
  | { kind: "links"; title?: string; results: IosSearchLinkResult[] };

/**
 * Every number the screen draws with, and where each one came from. "ChatKit" means it was read off
 * `-[CKUIBehavior …]` through the Phone behaviour; "measured" means a capture in `references/`.
 */
export const iosSearchMetrics = {
  /** The screen these were measured on. Points equal CSS px. */
  screen: { width: 402, height: 874 },
