} as const;

/** ChatKit's own English section titles, out of `ChatKit.loctable`. */
export const iosSearchSectionTitles: Record<IosSearchSectionKind, string> = {
  // SEARCH_CONVERSATIONS_TITLE. The framework calls this section Conversations, not Contacts.
  conversations: "Conversations",
  messages: "Messages", // SEARCH_MESSAGES_TITLE
  photos: "Photos", // SEARCH_PHOTOS_TITLE
  links: "Links", // SEARCH_LINKS_TITLE
};

/** ChatKit strings: SEARCH, CANCEL, SEARCH_SHOW_MORE, SEARCH_RESULTS_INDEXING_TITLE. */
export const iosSearchStrings = {
  placeholder: "Search",
  cancel: "Cancel",
  seeAll: "See All",
  noResults: "No Results",
} as const;

export type IosSearchProps = Omit<ComponentProps<"div">, "onSelect" | "onChange"> & {
  /** The query. Uncontrolled when omitted. */
  query?: string;
  defaultQuery?: string;
  onQueryChange?: (query: string) => void;
  sections?: IosSearchSection[];
  onSelect?: (result: IosSearchResult, kind: IosSearchSectionKind) => void;
  onSeeAll?: (kind: IosSearchSectionKind) => void;
  /** Cancel, and Escape, leave search. */
  onCancel?: () => void;
  /** False plays the exit and then calls `onExited`. */
  open?: boolean;
  onExited?: () => void;
  /** Seek the transition to this fraction (0..1) instead of playing it, which is what the harness does. */
  progress?: number;
  /** Space above the field for the status bar. */
  topInset?: number;
  /** Where the field rests on the list before it rises. Measured at y 798. */
  restingFieldTop?: number;
  /** Rows per section before "See All" appears. ChatKit's own default is 4. */
  maxResults?: number;
  placeholder?: string;
  cancelLabel?: string;
  /** Shown before anything is typed. Native fills this with suggestions, which this kit does not model. */
  emptyState?: ReactNode;
  /** Second line under "No Results". Native only fills it while the index is still building. */
  noResultsDetail?: string;
};

const font = '-apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro", "Helvetica Neue", Helvetica, Arial, sans-serif';

/**
 * Light values are the conversation list's measured tokens; dark values are its measured dark set.
 * The balloon fills are the kit's measured palette (`tokens.ts`): iOS gray #e9e9eb / #262629, and the
 * blue, which `tokens.ts` still carries from macOS because no iOS capture holds a blue bubble.
 */
const vars =
  "[--ios-search-bg:#ffffff] [--ios-search-label:#000000] [--ios-search-secondary:#8a8a8e] [--ios-search-chevron:#c5c5c7] [--ios-search-separator:#e8e8e8] " +
  "[--ios-search-glass:rgba(255,255,255,0.9)] [--ios-search-rim:none] [--ios-search-shadow:0_6px_36px_4px_rgba(0,0,0,0.065)] [--ios-search-field:#8a8a8e] " +
  "[--ios-search-tint:#0088ff] [--ios-search-dim:rgba(0,0,0,0.2)] [--ios-search-clear:#c5c5c7] " +
  "[--ios-search-incoming:#e9e9eb] [--ios-search-incoming-text:#000000] [--ios-search-blue-top:#77c7f5] [--ios-search-blue-bottom:#3682f7] [--ios-search-tile:#e9e9eb] " +
  "dark:[--ios-search-bg:#000000] dark:[--ios-search-label:#ffffff] dark:[--ios-search-secondary:#8d8d93] dark:[--ios-search-chevron:#464649] dark:[--ios-search-separator:#2a2a2c] " +
  "dark:[--ios-search-glass:rgba(28,28,28,0.9)] dark:[--ios-search-rim:inset_0_0_0_1px_rgba(255,255,255,0.09)] dark:[--ios-search-shadow:none] dark:[--ios-search-field:#97979d] " +
  "dark:[--ios-search-tint:#0091ff] dark:[--ios-search-dim:rgba(0,0,0,0.5)] dark:[--ios-search-clear:#464649] " +
  "dark:[--ios-search-incoming:#262629] dark:[--ios-search-incoming-text:#ffffff] dark:[--ios-search-blue-top:#589af7] dark:[--ios-search-blue-bottom:#3d8ef7] dark:[--ios-search-tile:#1c1c1e]";

const clamp01 = (value: number) => Math.max(0, Math.min(1, value));

function reducedMotion() {
  return typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches === true;
}

function initialsOf(name: string): string {
  return name.trim().split(/\s+/).slice(0, 2).map(part => part[0] ?? "").join("").toUpperCase();
}

/** Where the query lands in a piece of text. Falls back to each word when the whole phrase misses. */
function matchRanges(text: string, query: string): Array<[number, number]> {
  const needle = query.trim().toLowerCase();
  if (!needle) return [];
  const haystack = text.toLowerCase();
  const find = (term: string) => {
    const found: Array<[number, number]> = [];
    for (let at = haystack.indexOf(term); at !== -1; at = haystack.indexOf(term, at + term.length)) found.push([at, at + term.length]);
    return found;
  };
  const whole = find(needle);
  if (whole.length > 0) return whole;
  const words = needle.split(/\s+/).filter(Boolean);
  return words.flatMap(find).sort((a, b) => a[0] - b[0]);
}

/**
 * ChatKit's `ck_trimmedStringWithPreferredLength:anchoredAroundSubstring:`: a snippet longer than
 * `max` is cut down to a window centred on the match, with an ellipsis on whichever side was cut.
 */
export function trimAroundMatch(text: string, query: string, max = iosSearchMetrics.message.maxSummaryLength): string {
  if (text.length <= max) return text;
  const first = matchRanges(text, query)[0];
  const anchor = first ? first[0] : 0;
  const start = Math.max(0, Math.min(text.length - max, anchor - Math.floor((max - (first ? first[1] - first[0] : 0)) / 2)));
  const end = Math.min(text.length, start + max);
  return `${start > 0 ? "…" : ""}${text.slice(start, end).trim()}${end < text.length ? "…" : ""}`;
}

/**
 * The annotated snippet. Same font throughout, only the colour changes, which is what
 * `-[CKMessageSearchResultCell _annotatedResultStringForResult:searchText:]` does.
 */
function Highlight({ text, query, match }: { text: string; query: string; match: string }) {
  const ranges = matchRanges(text, query);
  if (ranges.length === 0) return <>{text}</>;
  const parts: ReactNode[] = [];
  let at = 0;
  ranges.forEach(([start, end], index) => {
    if (start < at) return;
    if (start > at) parts.push(text.slice(at, start));
    parts.push(
      <span key={`${start}-${index}`} data-slot="match" style={{ color: match }}>
        {text.slice(start, end)}
      </span>,
    );
    at = end;
  });
  if (at < text.length) parts.push(text.slice(at));
  return <>{parts}</>;
}

/** The measured list chevron, reused byte for byte. */
function Chevron({ style }: { style?: CSSProperties }) {
  return (
    <svg aria-hidden="true" data-slot="chevron" className="absolute" style={style} width="11" height="16" viewBox="-2 -2 11 16" fill="none" stroke="var(--ios-search-chevron)" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M1 1 6 6 1 11" />
    </svg>
  );
}

/** The measured list separator, from x 83 to 386 at the row's bottom edge. */
function RowSeparator() {
  const m = iosSearchMetrics.row;
  return <span aria-hidden="true" data-slot="separator" className="absolute" style={{ left: m.separatorLeft, right: m.separatorRight, bottom: 0, height: 1, transform: "translateY(-0.3333px)", background: "var(--ios-search-separator)" }} />;
}

function ConversationRow({ result, query, onSelect }: { result: IosSearchConversationResult; query: string; onSelect?: () => void }) {
  const m = iosSearchMetrics.row;
  return (
    <button type="button" onClick={onSelect} aria-label={`${result.name}, ${result.time}, ${result.preview}`}
      className="absolute inset-0 w-full text-left focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-blue-500">
      <Avatar aria-hidden="true" size={m.avatar} initials={result.initials ?? initialsOf(result.name)} className="absolute" style={{ left: m.avatarLeft, top: m.avatarTop }} />
      <span aria-hidden="true" data-slot="name" className="absolute truncate" style={{ left: m.textLeft, right: 96, top: m.nameTop, transform: "translateY(0.3333px)", fontSize: m.nameSize, lineHeight: 1, fontWeight: m.nameWeight, letterSpacing: 0, color: "var(--ios-search-label)" }}>
        {result.name}
      </span>
      <span aria-hidden="true" data-slot="time" className="absolute whitespace-nowrap" style={{ right: m.timeRight, top: m.timeTop, transform: "translateY(0.3333px)", fontSize: m.timeSize, lineHeight: 1, letterSpacing: 0, color: "var(--ios-search-secondary)" }}>
        {result.time}
      </span>
      <Chevron style={{ left: m.chevronLeft, top: m.chevronTop, transform: "translateX(0.3333px)" }} />
      <span aria-hidden="true" data-slot="preview" className="absolute overflow-hidden" style={{ left: m.textLeft, right: 34, top: m.previewTop, transform: "translateY(-0.3333px)", fontSize: m.previewSize, lineHeight: `${m.previewLine}px`, letterSpacing: 0, color: "var(--ios-search-secondary)", display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical" } as CSSProperties}>
        <Highlight text={result.preview} query={query} match="var(--ios-search-label)" />
      </span>
      <RowSeparator />
    </button>
  );
}

function MessageRow({ result, query, onSelect }: { result: IosSearchMessageResult; query: string; onSelect?: () => void }) {
  const row = iosSearchMetrics.row;
  const m = iosSearchMetrics.message;
  const snippet = trimAroundMatch(result.text, query);
  // Every spacing here is a framework value; the balloon's own vertical padding is what the 86.6667
  // row has left once they are taken out, so it is derived rather than invented.
  const balloonTop = m.topSpacing + m.labelLine + m.senderToBalloon;
  const balloonHeight = row.height - balloonTop - m.bottomSpacing;
  const label = [result.conversation, result.name].filter(Boolean).join(", ");
  return (
    <button type="button" onClick={onSelect} aria-label={`${label}, ${result.time}, ${snippet}`}
      className="absolute inset-0 w-full text-left focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-blue-500">
      {/* Ø28 centred in the measured 26-71 avatar gutter so the text column still starts at x 83. */}
      <Avatar aria-hidden="true" size={m.avatar} initials={result.initials ?? initialsOf(result.name)} className="absolute" style={{ left: row.avatarLeft + (row.avatar - m.avatar) / 2, top: m.topSpacing }} />
      <span aria-hidden="true" data-slot="message-heading" className="absolute flex items-baseline overflow-hidden whitespace-nowrap" style={{ left: row.textLeft, right: row.timeRight + 40, top: m.topSpacing, height: m.labelLine, gap: m.conversationToSender, fontSize: m.labelFontSize, lineHeight: `${m.labelLine}px`, letterSpacing: 0 }}>
        {result.conversation && <span data-slot="conversation" className="shrink-0 truncate" style={{ fontWeight: m.conversationWeight, color: "var(--ios-search-label)" }}>{result.conversation}</span>}
        <span data-slot="sender" className="truncate" style={{ color: "var(--ios-search-secondary)" }}>{result.name}</span>
      </span>
      <span aria-hidden="true" data-slot="time" className="absolute whitespace-nowrap" style={{ right: row.timeRight, top: m.topSpacing, fontSize: m.labelFontSize, lineHeight: `${m.labelLine}px`, letterSpacing: 0, color: "var(--ios-search-secondary)" }}>
        {result.time}
      </span>
      {/*
        The track carries the geometry so the balloon inside it can hug its own text and still stop
        short: an absolutely positioned box cannot take `left`, `right` and a shrink-to-fit width at
        once. The chevron sits at the row's trailing edge and the framework's 12pt balloon-to-chevron
        gap becomes the track's right inset, with `searchMessagesHorizontalBalloonMargin` as the
        ceiling on top of that.
      */}
      <span aria-hidden="true" data-slot="balloon-track" className="absolute flex items-center"
        style={{ left: row.textLeft, right: iosSearchMetrics.screen.width - row.chevronLeft + m.balloonToChevron, top: balloonTop, height: balloonHeight }}>
        <span data-slot="balloon" className="flex h-full items-center overflow-hidden"
          style={{
            maxWidth: `min(100%, ${iosSearchMetrics.screen.width - m.horizontalBalloonMargin}px)`,
            paddingLeft: m.balloonPaddingX,
            paddingRight: m.balloonPaddingX,
            borderRadius: Math.min(m.balloonRadius, balloonHeight / 2),
            background: result.fromMe ? "linear-gradient(var(--ios-search-blue-top), var(--ios-search-blue-bottom))" : "var(--ios-search-incoming)",
            fontSize: m.balloonFontSize,
            lineHeight: `${m.balloonLine}px`,
            letterSpacing: 0,
            color: result.fromMe ? "rgba(255,255,255,0.6)" : "var(--ios-search-secondary)",
          }}>
          <span className="truncate">
            <Highlight text={snippet} query={query} match={result.fromMe ? "#ffffff" : "var(--ios-search-label)"} />
          </span>
        </span>
      </span>
      <Chevron style={{ left: row.chevronLeft, top: balloonTop + balloonHeight / 2 - 8, transform: "translateX(0.3333px)" }} />
      <RowSeparator />
    </button>
  );
}

function PhotoTile({ result, onSelect }: { result: IosSearchPhotoResult; onSelect?: () => void }) {
  const m = iosSearchMetrics.photos;
  return (
    <button type="button" onClick={onSelect} aria-label={`Photo from ${result.name}, ${result.time}`}
      className="relative shrink-0 overflow-hidden focus-visible:outline-2 focus-visible:outline-blue-500"
      style={{ width: m.tile, height: m.tile, borderRadius: m.radius, background: "var(--ios-search-tile)" }}>
      {result.src && (
        // eslint-disable-next-line @next/next/no-img-element -- registry components stay framework-neutral
        <img src={result.src} alt="" className="size-full object-cover" draggable={false} />
      )}
    </button>
  );
}

function LinkCard({ result, query, onSelect }: { result: IosSearchLinkResult; query: string; onSelect?: () => void }) {
  const m = iosSearchMetrics.links;
  const width = iosSearchMetrics.photos.tile * m.widthScale;
  const thumbHeight = iosSearchMetrics.photos.tile * m.heightScale;
  return (
    <button type="button" onClick={onSelect} aria-label={`${result.title}, ${result.domain}, ${result.time}`}
      className="relative shrink-0 text-left focus-visible:outline-2 focus-visible:outline-blue-500" style={{ width }}>
      <span aria-hidden="true" className="block overflow-hidden" style={{ height: thumbHeight, borderRadius: m.radius, background: "var(--ios-search-tile)" }}>
        {result.src && (
          // eslint-disable-next-line @next/next/no-img-element -- registry components stay framework-neutral
          <img src={result.src} alt="" className="size-full object-cover" draggable={false} />
        )}
      </span>
      <span aria-hidden="true" className="block truncate" style={{ marginTop: m.titleTop, fontSize: m.labelFontSize, lineHeight: `${m.labelLine}px`, fontWeight: 600, letterSpacing: 0, color: "var(--ios-search-label)" }}>
        <Highlight text={result.title} query={query} match="var(--ios-search-tint)" />
      </span>
      <span aria-hidden="true" className="block truncate" style={{ marginTop: m.subtitleTop, fontSize: m.labelFontSize, lineHeight: `${m.labelLine}px`, letterSpacing: 0, color: "var(--ios-search-secondary)" }}>
        {result.domain} · {result.time}
      </span>
    </button>
  );
}

function SectionHeader({ id, title, kind, showSeeAll, onSeeAll }: { id: string; title: string; kind: IosSearchSectionKind; showSeeAll: boolean; onSeeAll?: (kind: IosSearchSectionKind) => void }) {
  const m = iosSearchMetrics.header;
  return (
    <div data-slot="section-header" className="sticky top-0 z-10" style={{ height: m.height, background: "var(--ios-search-bg)" }}>
      <h2 id={id} className="absolute m-0 truncate" style={{ left: m.margin, right: m.margin + 80, top: (m.height - m.fontSize) / 2, fontSize: m.fontSize, lineHeight: 1, fontWeight: m.weight, letterSpacing: 0, color: "var(--ios-search-label)" }}>
        {title}
      </h2>
      {showSeeAll && onSeeAll && (
        <button type="button" data-slot="see-all" onClick={() => onSeeAll(kind)} aria-label={`${iosSearchStrings.seeAll} ${title}`}
          className="absolute rounded focus-visible:outline-2 focus-visible:outline-blue-500"
          style={{ right: m.margin, top: (m.height - m.buttonFontSize) / 2, fontSize: m.buttonFontSize, lineHeight: 1, letterSpacing: 0, color: "var(--ios-search-tint)" }}>
          {iosSearchStrings.seeAll}
        </button>
      )}
    </div>
  );
}

export function IosSearch({
  query: queryProp,
  defaultQuery = "",
  onQueryChange,
  sections = [],
  onSelect,
  onSeeAll,
  onCancel,
  open = true,
  onExited,
  progress,
  topInset = 54,
  restingFieldTop = iosSearchMetrics.field.restingTop,
  maxResults = iosSearchMetrics.maxResults,
  placeholder = iosSearchStrings.placeholder,
  cancelLabel = iosSearchStrings.cancel,
  emptyState = null,
  noResultsDetail,
  className,
  style,
  ...props
}: IosSearchProps) {
  const m = iosSearchMetrics;
  const id = useId();
  const [internalQuery, setInternalQuery] = useState(defaultQuery);
  const query = queryProp ?? internalQuery;
  const setQuery = (next: string) => {
    if (queryProp === undefined) setInternalQuery(next);
    onQueryChange?.(next);
  };

  const scrim = useRef<HTMLDivElement>(null);
  const surface = useRef<HTMLDivElement>(null);
  const fieldRow = useRef<HTMLDivElement>(null);
  const pill = useRef<HTMLDivElement>(null);
  const cancel = useRef<HTMLButtonElement>(null);
  const input = useRef<HTMLInputElement>(null);
  const exited = useRef(false);
  // Kept in a ref so a caller passing a fresh closure does not restart the timeline: an inline arrow
  // has a new identity on every render, and a dependency on it would tear a finished exit down and
  // start it again from the top.
  const exitedCallback = useRef(onExited);
  useEffect(() => {
    exitedCallback.current = onExited;
  });

  const [cancelWidth, setCancelWidth] = useState(0);
  useEffect(() => {
    const node = cancel.current;
    if (!node) return;
    const sync = () => setCancelWidth(node.offsetWidth);
    sync();
    const observer = new ResizeObserver(sync);
    observer.observe(node);
    return () => observer.disconnect();
  }, [cancelLabel]);

  const fieldTop = topInset + m.field.topFromInset;
  const rowWidth = m.screen.width - m.field.inset * 2;
  const pillWidth = cancelWidth > 0 ? rowWidth - cancelWidth - m.field.gap : rowWidth;
  const rise = restingFieldTop - fieldTop;
  const resultsTop = fieldTop + m.field.height + m.resultsTopPadding;

  /** Escape leaves search, wherever focus happens to be. */
  useEffect(() => {
    if (!open || !onCancel) return;
    const onKey = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      onCancel();
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [open, onCancel]);

  /** Opening for real takes the caret; a scrubbed frame must not, or the harness moves focus. */
  useEffect(() => {
    if (!open || progress !== undefined) return;
    input.current?.focus({ preventScroll: true });
  }, [open, progress]);

  /**
   * One timeline over the scrim, the surface, the field row and the pill. Closing runs the same
   * keyframes in reverse, so a seek lands on the same frame in either direction, and the direction is
   * read off `open` during render rather than in an effect that would skip the exit's frames.
   */
  useEffect(() => {
    if (open) exited.current = false;
    const closing = !open;
    const duration = closing ? m.timing.exit : m.timing.enter;
    const finish = () => {
      if (exited.current) return;
      exited.current = true;
      exitedCallback.current?.();
    };
    // Scrubbing is inspection, not a dismissal: a seeked exit poses the screen and reports nothing.
    const reports = closing && progress === undefined;
    if (reducedMotion()) {
      if (!reports) return;
      const frame = requestAnimationFrame(finish);
      return () => cancelAnimationFrame(frame);
    }
    const tracks: Array<[HTMLElement | null, Keyframe[]]> = [
      // Judgement: the dim leads and the opaque surface follows, so the list is visibly dimmed
      // before it is replaced. Neither offset is measured.
      [scrim.current, [{ opacity: 0, offset: 0 }, { opacity: 1, offset: 0.5 }, { opacity: 1, offset: 1 }]],
      [surface.current, [{ opacity: 0, offset: 0 }, { opacity: 0, offset: 0.15 }, { opacity: 1, offset: 1 }]],
      [fieldRow.current, [{ transform: `translateY(${rise}px)` }, { transform: "translateY(0px)" }]],
      [pill.current, [{ width: `${m.field.restingWidth}px` }, { width: `${pillWidth}px` }]],
      [cancel.current, [{ opacity: 0, transform: `translateX(${m.field.gap}px)` }, { opacity: 1, transform: "translateX(0px)" }]],
    ];
    const animations = tracks
      .filter((track): track is [HTMLElement, Keyframe[]] => track[0] !== null)
      .map(([node, frames]) => node.animate(frames, { duration, easing: "cubic-bezier(0.32, 0.72, 0, 1)", fill: "both", direction: closing ? "reverse" : "normal" }));
    if (progress !== undefined) {
      for (const animation of animations) {
        animation.pause();
        animation.currentTime = clamp01(progress) * duration;
      }
      return () => { for (const animation of animations) animation.cancel(); };
    }
    if (!closing) return () => { for (const animation of animations) animation.cancel(); };
    const first = animations[0];
    first?.addEventListener("finish", finish);
    return () => first?.removeEventListener("finish", finish);
  }, [open, progress, rise, pillWidth, m.field.gap, m.field.restingWidth, m.timing.enter, m.timing.exit]);

  const typed = query.trim().length > 0;
  const shown = sections.map(section => ({ section, visible: section.results.slice(0, maxResults) })).filter(entry => entry.visible.length > 0);
  const total = sections.reduce((count, section) => count + section.results.length, 0);

  return (
    <div data-slot="ios-search" data-state={open ? "open" : "closed"} className={cn("absolute inset-0 isolate select-none overflow-hidden", vars, className)}
      style={{ fontFamily: font, ...style }} {...props}>
      <div ref={scrim} aria-hidden="true" data-slot="scrim" className="absolute inset-0" style={{ background: "var(--ios-search-dim)" }} />

      {/* The opaque page and everything on it fade together, so the list never shows through a gap
          between two rows on the way in. */}
      <div ref={surface} data-slot="surface" className="absolute inset-0" style={{ background: "var(--ios-search-bg)" }}>
      <div data-slot="results" className="absolute overflow-y-auto" style={{ left: 0, right: 0, top: resultsTop, bottom: 0 }}>
        {!typed && emptyState}
        {typed && total === 0 && (
          <div data-slot="no-results" role="status" className="flex h-full flex-col items-center justify-center px-8 text-center">
            <p className="m-0" style={{ fontSize: m.empty.titleFontSize, lineHeight: 1.2, letterSpacing: 0, color: "var(--ios-search-label)" }}>{iosSearchStrings.noResults}</p>
            {noResultsDetail && <p className="m-0" style={{ marginTop: 8, fontSize: m.empty.subtitleFontSize, lineHeight: 1.3, letterSpacing: 0, color: "var(--ios-search-secondary)" }}>{noResultsDetail}</p>}
          </div>
        )}
        {typed && shown.map(({ section, visible }) => {
          const title = section.title ?? iosSearchSectionTitles[section.kind];
          const headingId = `${id}-${section.kind}`;
          const seeAll = section.results.length > visible.length;
          return (
            <section key={section.kind} data-slot="section" data-kind={section.kind} aria-labelledby={headingId} className="relative">
              <SectionHeader id={headingId} title={title} kind={section.kind} showSeeAll={seeAll} onSeeAll={onSeeAll} />
              {section.kind === "conversations" && (
                <ul role="list" aria-labelledby={headingId} className="relative m-0 list-none p-0" style={{ height: visible.length * m.row.height }}>
                  {visible.map((result, index) => (
                    <li key={result.id} role="listitem" className="absolute left-0 right-0 top-0" style={{ height: m.row.height, transform: `translateY(${index * m.row.height}px)` }}>
                      <ConversationRow result={result as IosSearchConversationResult} query={query} onSelect={() => onSelect?.(result, section.kind)} />
                    </li>
                  ))}
                </ul>
              )}
              {section.kind === "messages" && (
                <ul role="list" aria-labelledby={headingId} className="relative m-0 list-none p-0" style={{ height: visible.length * m.row.height }}>
                  {visible.map((result, index) => (
                    <li key={result.id} role="listitem" className="absolute left-0 right-0 top-0" style={{ height: m.row.height, transform: `translateY(${index * m.row.height}px)` }}>
                      <MessageRow result={result as IosSearchMessageResult} query={query} onSelect={() => onSelect?.(result, section.kind)} />
                    </li>
                  ))}
                </ul>
              )}
              {section.kind === "photos" && (
                <ul role="list" aria-labelledby={headingId} className="m-0 flex list-none overflow-x-auto p-0" style={{ gap: m.photos.gap, paddingLeft: m.header.margin, paddingRight: m.header.margin, paddingBottom: m.sectionGap }}>
                  {visible.map(result => (
                    <li key={result.id} role="listitem" className="shrink-0">
                      <PhotoTile result={result as IosSearchPhotoResult} onSelect={() => onSelect?.(result, section.kind)} />
                    </li>
                  ))}
                </ul>
              )}
              {section.kind === "links" && (
                <ul role="list" aria-labelledby={headingId} className="m-0 flex list-none overflow-x-auto p-0" style={{ gap: m.links.gap, paddingLeft: m.header.margin, paddingRight: m.header.margin, paddingBottom: m.sectionGap }}>
                  {visible.map(result => (
                    <li key={result.id} role="listitem" className="shrink-0">
                      <LinkCard result={result as IosSearchLinkResult} query={query} onSelect={() => onSelect?.(result, section.kind)} />
                    </li>
                  ))}
                </ul>
              )}
            </section>
          );
        })}
      </div>
      </div>

      <div ref={fieldRow} data-slot="field-row" role="search" className="absolute z-20" style={{ left: m.field.inset, right: m.field.inset, top: fieldTop, height: m.field.height }}>
        <div ref={pill} data-slot="field" className="absolute left-0 top-0 h-full rounded-full" style={{ width: pillWidth }}>
          <span aria-hidden="true" className="pointer-events-none absolute inset-0 -z-10 rounded-[inherit]" style={{ boxShadow: "var(--ios-search-shadow)" }} />
          <span aria-hidden="true" className="pointer-events-none absolute inset-0 rounded-[inherit]" style={{ background: "var(--ios-search-glass)", boxShadow: "var(--ios-search-rim)", backdropFilter: "blur(24px)", WebkitBackdropFilter: "blur(24px)" }} />
          <svg aria-hidden="true" className="absolute" style={{ left: m.field.glyphLeft, top: m.field.glyphTop }} width="18.3333" height="18.6667" viewBox="-1 -1 18.3333 18.6667" fill="none" stroke="var(--ios-search-field)" strokeLinecap="round">
            <circle cx="6.745" cy="7.219" r="5.883" strokeWidth="1.725" />
            <path d="M11.4 12.01 15.17 15.78" strokeWidth="2.467" />
          </svg>
          {!typed && (
            <span aria-hidden="true" data-slot="placeholder" className="absolute" style={{ left: m.field.textLeft, top: m.field.textTop, transform: "translateY(0.3333px)", fontSize: 17, lineHeight: 1, fontWeight: 500, letterSpacing: 0, color: "var(--ios-search-field)" }}>
              {placeholder}
            </span>
          )}
          <input
            ref={input}
            type="text"
            role="searchbox"
            autoComplete="off"
            autoCorrect="off"
            spellCheck={false}
            aria-label={placeholder}
            value={query}
            onChange={event => setQuery(event.target.value)}
            className="absolute border-0 bg-transparent p-0 outline-none select-text"
            style={{
              left: m.field.textLeft,
              right: m.field.micRight + m.field.micWidth + 8,
              // The measured placeholder's line box starts at 15.8333; a 20pt line box centres on it
              // from 14.3333. Weight 500 is the placeholder's measured weight, reused for typed text,
              // which no capture holds.
              top: 14.3333,
              height: 20,
              fontFamily: font,
              fontSize: 17,
              lineHeight: "20px",
              fontWeight: 500,
              letterSpacing: 0,
              color: "var(--ios-search-label)",
              caretColor: "var(--ios-search-tint)",
            }}
          />
          {typed ? (
            <button type="button" data-slot="clear" aria-label="Clear search" onClick={() => { setQuery(""); input.current?.focus(); }}
              className="absolute flex items-center justify-center rounded-full focus-visible:outline-2 focus-visible:outline-blue-500"
              style={{ right: m.field.micRight + (m.field.micWidth - m.field.clearSize) / 2, top: (m.field.height - m.field.clearSize) / 2, width: m.field.clearSize, height: m.field.clearSize, background: "var(--ios-search-clear)" }}>
              <svg aria-hidden="true" width="9" height="9" viewBox="0 0 9 9" fill="none" stroke="var(--ios-search-glass)" strokeWidth="1.6" strokeLinecap="round">
                <path d="M1 1 8 8M8 1 1 8" />
              </svg>
            </button>
          ) : (
            <span aria-hidden="true" className="absolute" style={{ right: m.field.micRight, top: m.field.micTop, color: "var(--ios-search-field)", display: "flex" }}>
              <IosMicIcon width={m.field.micWidth} height={m.field.micHeight} />
            </span>
          )}
        </div>
        <button ref={cancel} type="button" data-slot="cancel" onClick={onCancel}
          className="absolute right-0 top-0 h-full whitespace-nowrap rounded focus-visible:outline-2 focus-visible:outline-blue-500"
          style={{ fontSize: 17, lineHeight: 1, letterSpacing: 0, color: "var(--ios-search-tint)" }}>
          {cancelLabel}
        </button>
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useLayoutEffect, useRef, useState, type ComponentProps, type KeyboardEvent, type PointerEvent, type ReactNode } from "react";
import { cn } from "@/lib/utils";

/**
 * "Swipe left to reveal times", measured from `references/ios/captures/swipe-timestamps-light.png`
 * (402×874 @3x).
 *
 * - Every bubble shifts left by exactly 58 (the last one's body right edge goes 386 → 328).
 * - The per-message time is 11pt secondary (#8a8a8e light / #8d8d93 dark), right-aligned with its
 *   ink ending at x 385, and its ink is centred on the bubble body's centre (measured on all eight
 *   bubbles: 235.17 / 295.5 / 339.83 / 384.17 / 464 / 572.5 / 626.5 / 686.67).
 * - iOS formats the time with a narrow no-break space before AM/PM.
 *
 * The drag rubber-bands past full reveal and past zero, and releasing runs a ~300 ms spring
 * (ζ 0.9, ω 20 rad/s). `prefers-reduced-motion` snaps instead. Keyboard users get ArrowLeft /
 * ArrowRight (and Enter/Space to toggle) on the element the hook's `handlers` are spread onto.
 */

const font = "-apple-system, BlinkMacSystemFont, sans-serif";

/** Measured reveal geometry, in points. `timeInset` is from the screen's trailing edge. */
/** `baselineNudge` corrects Chrome's baseline, which sits two thirds of a point below native's. */
export const swipeTimesMetrics = { distance: 58, timeInset: 16, fontSize: 11, lineHeight: 13, letterSpacing: 0.1, baselineNudge: -0.6667 } as const;

export type SwipeToRevealOptions = {
  /** How far the bubbles travel at full reveal. */
  distance?: number;
  /** Controlled 0..1. When set, dragging is disabled and the value is used verbatim. */
  progress?: number;
  /** Fraction of `distance` past which a release settles open. */
  threshold?: number;
  onChange?: (open: boolean) => void;
};

export type SwipeToRevealTimes = {
  /** 0 = hidden, 1 = fully revealed. May exceed 1 slightly while rubber-banding. */
  progress: number;
  /** Signed px shift for the bubble column (negative moves left). */
  offset: number;
  open: boolean;
  setOpen: (next: boolean) => void;
  handlers: {
    onPointerDown: (event: PointerEvent<HTMLElement>) => void;
    onPointerMove: (event: PointerEvent<HTMLElement>) => void;
    onPointerUp: (event: PointerEvent<HTMLElement>) => void;
    onPointerCancel: (event: PointerEvent<HTMLElement>) => void;
    onKeyDown: (event: KeyboardEvent<HTMLElement>) => void;
    tabIndex: number;
    role: string;
    "aria-label": string;
    style: { touchAction: "pan-y" };
  };
};

/** Rubber band: full travel inside [0, 1], a quarter of it outside. */
function band(raw: number) {
  if (raw < 0) return raw * 0.25;
  if (raw > 1) return 1 + (raw - 1) * 0.25;
  return raw;
}

export function useSwipeToRevealTimes({ distance = swipeTimesMetrics.distance, progress: controlled, threshold = 0.4, onChange }: SwipeToRevealOptions = {}): SwipeToRevealTimes {
  const [value, setValue] = useState(0);
  const current = useRef(0);
  const drag = useRef<{ id: number; startX: number; base: number; lastX: number; time: number; velocity: number } | null>(null);
  const spring = useRef({ raf: 0, target: 0, velocity: 0, last: 0 });

  const write = useCallback((next: number) => { current.current = next; setValue(next); }, []);
  const stop = useCallback(() => { cancelAnimationFrame(spring.current.raf); spring.current.raf = 0; }, []);
  useEffect(() => stop, [stop]);

  const settle = useCallback((target: number, velocity: number) => {
    stop();
    if (typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches) { write(target); return; }
    const s = spring.current;
    s.target = target; s.velocity = velocity; s.last = performance.now();
    const step = (now: number) => {
      const dt = Math.min(0.032, (now - s.last) / 1000);
      s.last = now;
      // ζ 0.9, ω 20 rad/s: about 300 ms to rest with no visible overshoot.
      s.velocity += (400 * (s.target - current.current) - 36 * s.velocity) * dt;
      const next = current.current + s.velocity * dt;
      if (Math.abs(s.target - next) < 0.0008 && Math.abs(s.velocity) < 0.01) { write(s.target); s.raf = 0; return; }
      write(next);
      s.raf = requestAnimationFrame(step);
    };
    s.raf = requestAnimationFrame(step);
  }, [stop, write]);

  const setOpen = useCallback((next: boolean) => { settle(next ? 1 : 0, 0); onChange?.(next); }, [settle, onChange]);

  const locked = controlled !== undefined;
  const progress = locked ? controlled : value;

  const handlers: SwipeToRevealTimes["handlers"] = {
    tabIndex: 0,
    role: "group",
    "aria-label": "Conversation. Swipe left, or press the left arrow key, to show message times.",
    style: { touchAction: "pan-y" },
    onPointerDown(event) {
      if (locked || event.button !== 0) return;
      stop();
      drag.current = { id: event.pointerId, startX: event.clientX, base: current.current, lastX: event.clientX, time: performance.now(), velocity: 0 };
      event.currentTarget.setPointerCapture?.(event.pointerId);
    },
    onPointerMove(event) {
      const d = drag.current;
      if (!d || d.id !== event.pointerId) return;
      const now = performance.now();
      const dt = Math.max(1, now - d.time);
      d.velocity = ((d.lastX - event.clientX) / distance / dt) * 1000;
      d.lastX = event.clientX; d.time = now;
      write(band(d.base + (d.startX - event.clientX) / distance));
    },
    onPointerUp(event) {
      const d = drag.current;
      if (!d || d.id !== event.pointerId) return;
      drag.current = null;
      event.currentTarget.releasePointerCapture?.(event.pointerId);
      const next = current.current + d.velocity * 0.12 > threshold;
      settle(next ? 1 : 0, d.velocity);
      onChange?.(next);
    },
    onPointerCancel(event) {
      const d = drag.current;
      if (!d || d.id !== event.pointerId) return;
      drag.current = null;
      settle(0, 0);
      onChange?.(false);
    },
    onKeyDown(event) {
      if (locked) return;
      if (event.key === "ArrowLeft") { event.preventDefault(); setOpen(true); }
      else if (event.key === "ArrowRight" || event.key === "Escape") { event.preventDefault(); setOpen(false); }
      else if (event.key === "Enter" || event.key === " ") { event.preventDefault(); setOpen(progress < 0.5); }
    },
  };

  return { progress, offset: -progress * distance, open: progress > 0.5, setOpen, handlers };
}

export type SwipeTimesProps = Omit<ComponentProps<"div">, "children"> & {
  /** Already formatted, e.g. "1:25 AM" with a narrow no-break space. */
  time: ReactNode;
  /** 0..1 from `useSwipeToRevealTimes`. */
  progress?: number;
  distance?: number;
  /** Ink inset from the container's trailing edge. */
  timeInset?: number;
  children: ReactNode;
};

/**
 * One message row of the reveal: shifts its message left and slides the time in from the trailing
 * edge, vertically centred on the bubble body. Clip the scrolling container: at rest the time column
 * sits one full `distance` off-screen.
 */
export function SwipeTimes({ time, progress = 0, distance = swipeTimesMetrics.distance, timeInset = swipeTimesMetrics.timeInset, className, style, children, ...props }: SwipeTimesProps) {
  const t = Math.max(0, progress);
  const row = useRef<HTMLDivElement>(null);
  // Native centres the time on the bubble *body*, not on the row: a reaction balloon or a status
  // line grows the row without moving the body, and the time stays put.
  useLayoutEffect(() => {
    const root = row.current;
    if (!root) return;
    const measure = () => {
      const body = root.querySelector<HTMLElement>('[data-slot="bubble"], [data-slot="emoji"]');
      const box = root.getBoundingClientRect();
      const centre = body ? body.getBoundingClientRect().top + body.getBoundingClientRect().height / 2 - box.top : box.height / 2;
      root.style.setProperty("--swipe-centre", `${centre.toFixed(2)}px`);
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(root);
    document.fonts?.ready.then(measure).catch(() => {});
    return () => observer.disconnect();
  }, [children, time]);
  return (
    <div ref={row} data-slot="swipe-times" data-progress={t.toFixed(3)}
      className={cn("relative w-full [--ios-sw-secondary:#8a8a8e] dark:[--ios-sw-secondary:#8d8d93]", className)}
      style={{ fontFamily: font, ...style }} {...props}>
      <div data-slot="swipe-content" style={{ transform: `translateX(${(-t * distance).toFixed(2)}px)`, willChange: "transform" }}>{children}</div>
      <span data-slot="time" aria-hidden={t < 0.5 || undefined} className="pointer-events-none absolute whitespace-nowrap text-right"
        style={{
          // The column travels with the bubbles: it starts one full `distance` off the trailing edge.
          right: timeInset, top: "var(--swipe-centre, 50%)",
          transform: `translate(${((1 - Math.min(1, t)) * distance).toFixed(2)}px, calc(-50% + ${swipeTimesMetrics.baselineNudge}px))`,
          fontSize: swipeTimesMetrics.fontSize, lineHeight: `${swipeTimesMetrics.lineHeight}px`, letterSpacing: swipeTimesMetrics.letterSpacing,
          color: "var(--ios-sw-secondary)", opacity: Math.max(0, Math.min(1, t * 4)),
        }}>
        {time}
      </span>
    </div>
  );
}

"use client";

import type { ComponentProps, ReactNode } from "react";
import { cn } from "@/lib/utils";
import { usePlatform, type Platform } from "@/components/imessage/platform";

/**
 * In-conversation notices.
 *
 * **Unknown sender** — measured from `references/ios/captures/incoming-light.png` / `-dark.png`
 * (402×874 @3x): centred secondary text whose ink runs 721.33–731.67 on line 1 and 734.67–745 on
 * line 2 (ascender 8.33, x-height 6.0 → 11pt, 13.33 pitch), colour #8a8a8e / #8d8d93. Line 1's ink
 * spans x 22.67–379 and line 2 ("be spam.") x 177–224, so the paragraph is centred on x 201 and
 * wraps inside the 370pt content width. The last bubble body ends at 702.67, 16 above the text box.
 * The "Report Spam" pill is 91 × 22.33 centred on (200.83, 766.83) — a capsule filled with the
 * incoming gray (#e9e9eb / #262629) carrying a 69pt-wide #0088ff / #0091ff label.
 *
 * **Not delivered** — measured from `references/macos/captures/attachment-not-delivered-dark-2x.png`
 * (960×640 @2x): a Ø17 red ring badge (#eb534e) centred 9.5 past the bubble's trailing edge, on the
 * body's vertical centre, plus "Not Delivered" in the same 10pt semibold slot "Delivered" uses,
 * right-aligned 16.5 inside the badge's trailing edge. iOS scales that to the 11pt status world.
 */

const font = "-apple-system, BlinkMacSystemFont, sans-serif";

const noticeVars =
  "[--ios-nt-secondary:#8a8a8e] [--ios-nt-pill:#e9e9eb] [--ios-nt-link:#0088ff] " +
  "dark:[--ios-nt-secondary:#8d8d93] dark:[--ios-nt-pill:#262629] dark:[--ios-nt-link:#0091ff]";

/** Measured notice geometry, in points. */
export const unknownSenderMetrics = {
  fontSize: 11, lineHeight: 13.3333, contentWidth: 370, topGap: 16,
  pillWidth: 91, pillHeight: 22.3333, pillGap: 10.3333, pillFontSize: 11, letterSpacing: 0.1,
  /**
   * Centring a 91 wide pill in the 370 wide content column puts its left edge on 155.5, half a
   * point off the device grid at 3x. Native rounds that painted edge down to the pixel below and
   * fills x 466–738 of the capture (155.33–246.33); Blink rounds the whole background box up to
   * 156 instead. Snapping happens before the transform, so two thirds of a point here lands the
   * composited capsule back on the capture's edges. It is a rasterising correction for the
   * measured 370 column, not a layout offset.
   */
  pillNudgeX: -0.6667,
} as const;

export type UnknownSenderNoticeProps = Omit<ComponentProps<"div">, "children" | "title"> & {
  /** The grey paragraph. Defaults to the exact string iOS shows. */
  message?: ReactNode;
  /** Omit to hide the button. */
  action?: string;
  onAction?: () => void;
  /** Space above the paragraph, from the previous bubble's body bottom. */
  topGap?: number;
};

export function UnknownSenderNotice({
  message = "If you did not expect this message from an unknown sender, it may be spam.",
  action = "Report Spam", onAction, topGap = unknownSenderMetrics.topGap, className, style, ...props
}: UnknownSenderNoticeProps) {
  const m = unknownSenderMetrics;
  return (
    <div data-slot="unknown-sender-notice" role="note"
      className={cn("flex w-full select-none flex-col items-center", noticeVars, className)}
      style={{ fontFamily: font, paddingTop: topGap, ...style }} {...props}>
      <p data-slot="notice-text" className="m-0 text-center"
        style={{ maxWidth: m.contentWidth, fontSize: m.fontSize, lineHeight: `${m.lineHeight}px`, letterSpacing: m.letterSpacing, color: "var(--ios-nt-secondary)" }}>
        {message}
      </p>
      {action && (
        <button type="button" data-slot="notice-action" onClick={onAction}
          className="relative flex items-center justify-center rounded-full focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#0088ff]"
          style={{
            marginTop: m.pillGap, width: m.pillWidth, height: m.pillHeight, borderRadius: m.pillHeight / 2,
            color: "var(--ios-nt-link)",
            fontSize: m.pillFontSize, lineHeight: `${m.pillHeight}px`, fontWeight: 600, letterSpacing: 0,
          }}>
          {/* The fill carries `pillNudgeX`; the label must not, since its own ink already lands on the capture. */}
          <span aria-hidden="true" data-slot="notice-action-fill" className="absolute inset-0"
            style={{ borderRadius: m.pillHeight / 2, background: "var(--ios-nt-pill)", transform: `translateX(${m.pillNudgeX}px)` }} />
          {/* Chrome's baseline sits two thirds of a point below native's in this line box. */}
          <span className="relative" style={{ transform: "translateY(-0.6667px)" }}>{action}</span>
        </button>
      )}
    </div>
  );
}

/** Status typography per platform, matching `bubbleMetrics` so the label lands where "Delivered" would. */
const statusStyle: Record<Platform, { fontSize: number; lineHeight: number; letterSpacing: number; gap: number; inset: number; badge: number; badgeGap: number }> = {
  ios: { fontSize: 11, lineHeight: 13, letterSpacing: -0.25, gap: 4.65, inset: 19.3, badge: 18, badgeGap: 8 },
  macos: { fontSize: 10, lineHeight: 12, letterSpacing: -0.45, gap: 4, inset: 16.5, badge: 17, badgeGap: 9.5 },
};

export type FailedSendBadgeProps = Omit<ComponentProps<"button">, "children"> & {
  size?: number;
  platform?: Platform;
  label?: string;
};

/** The red (!) ring that sits beside a message that failed to send. */
export function FailedSendBadge({ size, platform: platformProp, label = "Message not delivered. Try again.", className, style, ...props }: FailedSendBadgeProps) {
  const contextPlatform = usePlatform();
  const platform = platformProp ?? contextPlatform;
  const d = size ?? statusStyle[platform].badge;
  return (
    <button type="button" data-slot="failed-send-badge" aria-label={label} title={label}
      className={cn("inline-flex shrink-0 items-center justify-center rounded-full align-middle focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#eb534e]", className)}
      style={{ width: d, height: d, ...style }} {...props}>
      <svg aria-hidden="true" width={d} height={d} viewBox="0 0 17 17" fill="none" stroke="#eb534e" strokeWidth="1.15" strokeLinecap="round">
        <circle cx="8.5" cy="8.5" r="7.9" />
        <path d="M8.5 4.3v5.1" />
        <path d="M8.5 12.35v0.05" strokeWidth="1.5" />
      </svg>
    </button>
  );
}

export type NotDeliveredProps = Omit<ComponentProps<"div">, "children"> & {
  label?: string;
  platform?: Platform;
  /** Trailing inset of the label's ink. Defaults to the platform's "Delivered" inset. */
  inset?: number;
};

/**
 * The red status line that replaces "Delivered". Drop it in the same slot: it uses the platform's
 * status typography so the ink lands on the measured baseline.
 */
export function NotDelivered({ label = "Not Delivered", platform: platformProp, inset, className, style, ...props }: NotDeliveredProps) {
  const contextPlatform = usePlatform();
  const platform = platformProp ?? contextPlatform;
  const s = statusStyle[platform];
  return (
    <div data-slot="not-delivered" className={cn("select-none text-right", className)}
      style={{
        fontFamily: font, fontSize: s.fontSize, lineHeight: `${s.lineHeight}px`, fontWeight: 600,
        letterSpacing: s.letterSpacing, marginTop: s.gap, paddingInlineEnd: inset ?? s.inset, color: "#eb534e", ...style,
      }} {...props}>
      {label}
    </div>
  );
}

"use client";

import type { ComponentProps, ReactNode } from "react";
import { cn } from "@/lib/utils";
import { usePlatform, type Platform } from "@/components/imessage/platform";
import { bubbleMetrics, fontStack } from "@/components/imessage/tokens";
import { unknownSenderMetrics } from "@/components/imessage/ios-notices";
import type { TapbackType } from "@/components/imessage/tapback";

/**
 * The centred grey lines a transcript carries that are not bubbles: group renames, joins and
 * leaves, the group photo, a missed call, a reaction summary, and the unknown-sender notice.
 *
 * ## What is measured, and what is not
 *
 * **The type, colour, centring and the space above are measured**, from the unknown-sender notice in
 * `references/ios/captures/incoming-light.png` (402x874 @3x). Re-read for this component, scanning
 * every row for non-white ink across the full width:
 *
 * - line 1 ("If you did not expect this message from an unknown sender, it may") has ink on device
 *   rows 2163-2195, i.e. pt y 721.0-731.67, with the x-height band running 723.67-729.33 and the
 *   baseline at 729.5. Line 2 ("be spam.") runs 2204-2234 = pt 734.67-745.0.
 * - line pitch is therefore 734.67 - 721.33 = **13.3333**, and x-height is 729.5 - 723.67 = **5.83**,
 *   which at SF Pro Text's 0.53 em x-height is 11.0 pt exactly (12 pt would read 6.36). The ascender
 *   run 729.5 - 721.0 = 8.5 agrees at SF's 0.75 em. So the family is **11 pt, not the 12 pt SPEC.md's
 *   prose line says**; `unknownSenderMetrics` in `ios-notices.tsx` measured the same 11.
 * - line 1 spans x 22.33-379.0 and line 2 x 176.67-224.0, so both centre on x 200.5 in a 402 wide
 *   screen: the paragraph is **centred**, and it wraps inside the 370 column that the measured 16 pt
 *   edge inset leaves (402 - 2x16 = 370).
 * - the last bubble body above it ends at pt y 702.67 and the line box starts at 718.67, so the
 *   **space above is 16**.
 * - colour #8a8a8e light / #8d8d93 dark (SPEC.md "Secondary label (Delivered, date, spam notice)"),
 *   which is the palette's `--im-secondary`.
 *
 * **The space below is not measured.** Nothing sits under the notice in that capture except its
 * "Report Spam" pill, 10.33 below. This file mirrors the measured 16 above as 16 below; treat it as
 * judgement.
 *
 * **The bold run is not measured.** No capture holds a system message with a name in it. Weight 600
 * is reused, not guessed: it is the measured weight of the other ink in this same 11 pt secondary
 * slot, the "Delivered" status label (SPEC.md, iOS bubble geometry) and the "Report Spam" label.
 *
 * **macOS is sized from the macOS secondary label, not measured for this surface.** It takes
 * `bubbleMetrics.macos.statusFontSize` / `statusLineHeight` / `statusLetterSpacing`, the measured
 * 9 pt on an 11 pt line box that "Delivered" and the macOS date header both use, and the measured
 * secondary colour #808080 / #9a9a9a. Its 11.5 gaps are the measured between-cluster gap, reused the
 * way `dateSeparatorMetrics.macos.midGapAbove` reuses it, because a system line is its own cluster.
 * Note that on iOS the notice's 16 is 1.57x that platform's 10.2 cluster gap, so if macOS follows the
 * same ratio the true number is nearer 18. Nothing in `references/` settles it.
 *
 * ## Which strings this supports
 *
 * Only `unknownSender` is a captured string. Every other sentence below follows Apple's documented
 * behaviour for group conversations and tapback summaries, and is **wording, not a measurement**:
 *
 * | event | renders (bold shown in brackets) |
 * |---|---|
 * | `unknownSender` | If you did not expect this message from an unknown sender, it may be spam. |
 * | `conversationNamed` | You named the conversation "Design Crew". / [Alex Morgan] named the conversation "Design Crew". |
 * | `participantAdded` | You added [Sam Rivera] to the conversation. |
 * | `participantRemoved` | You removed [Sam Rivera] from the conversation. |
 * | `participantLeft` | [Alex Morgan] left the conversation. / You left the conversation. |
 * | `groupPhotoChanged` | You changed the group photo. |
 * | `missedCall` | Missed Call / Missed Video Call / Missed FaceTime |
 * | `reaction` | You loved "Tuesday morning at 9?" / [Alex Morgan] laughed at "…" |
 *
 * A participant's name renders bold; "You" never does, which is the rule Messages follows for the
 * first person. `actor` left out means you. The conversation name and a quoted message stay in the
 * regular weight inside curly quotes, matching how SPEC.md records the macOS sidebar preview
 * ("You loved “…”"). "Missed FaceTime" is the same wording `facetime-card.tsx` already uses.
 *
 * The unknown-sender sentence lives here as plain text so the family is complete. The version with
 * the measured "Report Spam" pill under it is `UnknownSenderNotice` in `ios-notices.tsx`; use that
 * one when the button belongs on screen.
 *
 * Nothing here animates, so there is no reduced-motion or seek behaviour to respect.
 */

export type SystemMessageMetrics = {
  fontSize: number;
  lineHeight: number;
  letterSpacing: number;
  weight: number;
  /** Weight for a participant's name inside the sentence. */
  emphasisWeight: number;
  /** Space from the row above to the line box, and from the line box to the row below. */
  gapAbove: number;
  gapBelow: number;
  /** Inset from the pane edge, which is what wraps the sentence. */
  inset: number;
};

export const systemMessageMetrics: Record<Platform, SystemMessageMetrics> = {
  ios: {
    // Measured: the unknown-sender notice, via `unknownSenderMetrics`.
    fontSize: unknownSenderMetrics.fontSize,
    lineHeight: unknownSenderMetrics.lineHeight,
    letterSpacing: unknownSenderMetrics.letterSpacing,
    weight: 400,
    // Reused: the measured semibold of the 11pt "Delivered" label and the "Report Spam" pill.
    emphasisWeight: 600,
    gapAbove: unknownSenderMetrics.topGap,
    // Judgement: mirrors the measured 16 above. Nothing sits below the notice in the capture.
    gapBelow: unknownSenderMetrics.topGap,
    // Measured: 402 - 2x16 is the 370 column the notice wraps inside.
    inset: bubbleMetrics.ios.edgeInset,
  },
  macos: {
    // Reused: the measured macOS secondary label, 9pt on an 11pt line box with no tracking.
    fontSize: bubbleMetrics.macos.statusFontSize,
    lineHeight: bubbleMetrics.macos.statusLineHeight,
    letterSpacing: bubbleMetrics.macos.statusLetterSpacing,
    weight: 400,
    emphasisWeight: 600,
    // Reused: the measured between-cluster gap. A system line is its own cluster.
    gapAbove: bubbleMetrics.macos.gapBetweenGroups,
    gapBelow: bubbleMetrics.macos.gapBetweenGroups,
    inset: bubbleMetrics.macos.edgeInset,
  },
};

/**
 * Palette first, then the measured value for that platform and theme, so a bare
 * `<SystemMessage>` outside an app shell still paints the right grey.
 */
const secondaryVars: Record<Platform, string> = {
  ios: "[--im-sys-label:var(--im-secondary,#8a8a8e)] dark:[--im-sys-label:var(--im-secondary,#8d8d93)]",
  macos: "[--im-sys-label:var(--im-secondary,#808080)] dark:[--im-sys-label:var(--im-secondary,#9a9a9a)]",
};

/** The one captured string, kept verbatim. */
export const unknownSenderText =
  "If you did not expect this message from an unknown sender, it may be spam.";

/** Apple's past-tense tapback wording, keyed by the kit's own `TapbackType`. */
export const reactionVerbs: Record<TapbackType, string> = {
  love: "loved",
  like: "liked",
  dislike: "disliked",
  laugh: "laughed at",
  emphasize: "emphasized",
  question: "questioned",
};

export type MissedCallKind = "audio" | "video" | "facetime";

/**
 * One thing that happened to the conversation rather than in it. `actor` is the person who did it;
 * leave it out (or pass "You") for the first person, which never renders bold.
 */
export type SystemMessageEvent =
  | { type: "unknownSender" }
  | { type: "conversationNamed"; actor?: string; name: string }
  | { type: "participantAdded"; actor?: string; participant: string }
  | { type: "participantRemoved"; actor?: string; participant: string }
  | { type: "participantLeft"; actor?: string }
  | { type: "groupPhotoChanged"; actor?: string }
  | { type: "missedCall"; kind?: MissedCallKind }
  | { type: "reaction"; actor?: string; reaction: TapbackType; excerpt: string };

/** A run of the sentence. `emphasis` runs carry a participant's name and render semibold. */
export type SystemMessageSegment = { text: string; emphasis?: boolean };

const quoted = (text: string) => `“${text}”`;

/** "You" is the first person and stays in the regular weight; anyone else is a name, so it bolds. */
function person(name: string | undefined): SystemMessageSegment {
  const text = name ?? "You";
  return text === "You" ? { text } : { text, emphasis: true };
}

const missedCallText: Record<MissedCallKind, string> = {
  audio: "Missed Call",
  video: "Missed Video Call",
  // The same wording `facetime-card.tsx` uses for a missed FaceTime.
  facetime: "Missed FaceTime",
};

/** Turns an event into the runs of its sentence, so a name can render bold inside it. */
export function formatSystemMessage(event: SystemMessageEvent): SystemMessageSegment[] {
  switch (event.type) {
    case "unknownSender":
      return [{ text: unknownSenderText }];
    case "conversationNamed":
      return [person(event.actor), { text: ` named the conversation ${quoted(event.name)}.` }];
    case "participantAdded":
      return [person(event.actor), { text: " added " }, person(event.participant), { text: " to the conversation." }];
    case "participantRemoved":
      return [person(event.actor), { text: " removed " }, person(event.participant), { text: " from the conversation." }];
    case "participantLeft":
      return [person(event.actor), { text: " left the conversation." }];
    case "groupPhotoChanged":
      return [person(event.actor), { text: " changed the group photo." }];
    case "missedCall":
      return [{ text: missedCallText[event.kind ?? "audio"] }];
    case "reaction":
      return [person(event.actor), { text: ` ${reactionVerbs[event.reaction]} ${quoted(event.excerpt)}` }];
  }
}

/** The same sentence as one string, for a sidebar preview, an aria label, or a test. */
export function systemMessageText(event: SystemMessageEvent): string {
  return formatSystemMessage(event).map(segment => segment.text).join("");
}

export type SystemMessageProps = Omit<ComponentProps<"div">, "children"> & {
  /** The event to describe. Omit and pass `children` to render your own sentence in this style. */
  event?: SystemMessageEvent;
  platform?: Platform;
  /** Override the platform's spacing, e.g. to close it up against a date header. */
  gapAbove?: number;
  gapBelow?: number;
  /** Cap the wrapped column. Left open, the platform's edge inset does the wrapping. */
  maxWidth?: number;
  children?: ReactNode;
};

export function SystemMessage({
  event, platform: platformProp, gapAbove, gapBelow, maxWidth, children, className, style, ...props
}: SystemMessageProps) {
  const contextPlatform = usePlatform();
  const platform = platformProp ?? contextPlatform;
  const m = systemMessageMetrics[platform];
  const segments = event ? formatSystemMessage(event) : undefined;
  return (
    <div
      data-slot="system-message"
      data-platform={platform}
      data-kind={event?.type}
      role="note"
      className={cn("flex w-full select-none flex-col items-center", secondaryVars[platform], className)}
      style={{
        fontFamily: fontStack,
        // The inset is what wraps the sentence, so the padding has to come out of the full width
        // even where the host has no global reset. Without this the column is 402 wide inside a
        // 402 frame and the measured 370 wrap turns into an overflow.
        boxSizing: "border-box",
        paddingTop: gapAbove ?? m.gapAbove,
        paddingBottom: gapBelow ?? m.gapBelow,
        paddingInline: m.inset,
        ...style,
      }}
      {...props}
    >
      <p
        data-slot="system-message-text"
        className="m-0 text-center"
        style={{
          maxWidth,
          fontSize: m.fontSize,
          lineHeight: `${m.lineHeight}px`,
          fontWeight: m.weight,
          letterSpacing: m.letterSpacing,
          color: "var(--im-sys-label)",
        }}
      >
        {segments
          ? segments.map((segment, index) =>
              segment.emphasis ? (
                <strong key={`${index}-${segment.text}`} style={{ fontWeight: m.emphasisWeight }}>
                  {segment.text}
                </strong>
              ) : (
                <span key={`${index}-${segment.text}`}>{segment.text}</span>
              ),
            )
          : children}
      </p>
    </div>
  );
}

"use client";

import type { ComponentProps, CSSProperties } from "react";
import { cn } from "@/lib/utils";
import { Avatar, type AvatarProps } from "@/components/imessage/avatar";

/**
 * The two avatar surfaces a group conversation has and a one-to-one does not: the stacked group
 * photo, and the small per-sender photo beside an incoming bubble.
 *
 * Nothing in `references/` captures a group conversation. `grouped-light.png` is named for message
 * *grouping* (clusters and tails) and is a two-person thread, so every number below was read out of
 * the frameworks on this machine rather than off a screenshot. The probes ran as a Mac Catalyst
 * binary (`clang -target arm64-apple-ios26.0-macabi`) that dlopens ChatKit and asks
 * `CKUIBehaviorPhone` — the iPhone behaviour object — directly, so these are the phone values and
 * not the Mac ones.
 *
 * ## The stack
 *
 * A group photo is not a ChatKit drawing at all: `CKAvatarView` is a `CNAvatarView` subclass, and
 * ContactsUICore lays the faces out through
 * `+[CNUIAvatarLayoutManager layoutConfigurationsForType:withItemCount:]`. Type 2 is
 * `SnowglobeAvatarLayoutConfigurations`, the one Messages uses (type 3, its sibling, is named
 * `SnowglobeGroupTypingIndicatorAvatarLayoutConfigurations`, which only a Messages transcript has).
 * Each entry is a `CNUIAvatarLayoutItemConfiguration` carrying `x`, `y`, `size` and `baseSize`, and
 * `-itemFrameInContainingBounds:isRTL:` turns one into a frame:
 *
 * ```
 * s = bounds.width / baseSize          baseSize is 88 for every Snowglobe entry
 * d = size * s
 * frame = (bounds.midX + x*s - d/2, bounds.midY + y*s - d/2, d, d)
 * ```
 *
 * `snowglobeStack` below is that table, verbatim, read back at a bounds of 88 so the numbers are the
 * configurations' own. One participant fills the circle; two through six extend one another; seven
 * re-lays the whole set. `+[CNUIAvatarLayoutManager maxAvatarCountForType:]` answers 10, but the
 * table itself stops at **seven faces**: asking for 8, 9, 10 or 11 returns the same seven entries,
 * so an eighth participant is simply not drawn. `isRTL:YES` mirrors x about the centre (verified:
 * two faces at a bounds of 88 return x 9.5 / 47.5 in LTR and 30.5 / 12.5 in RTL) and nothing else.
 *
 * Stacking order comes from `-[CNUIAvatarLayoutItemConfiguration updateLayer:inBounds:atIndex:isRTL:layoutType:]`,
 * which ends in `setZPosition:` of **-index**: the first (largest) face is in front and each later,
 * smaller one sits behind it. There is no ring, cut-out or hairline between the faces — no selector
 * in ContactsUI or ContactsUICore draws one, they simply overlap.
 *
 * `-[CKUIBehaviorPhone groupAvatarViewSize]` is 60 x 60, which is the same Ø 60 the nav-bar avatar
 * measures in `conv3-light.png`, so that is the default size here. (`detailsAvatarPancakeView*` on
 * the same object — diameter 37, cut-out 41, overlap 13.5, widths 58 and 72 for two and three — is a
 * *different* stack, `CKDetailsAvatarPancakeView`, used by the details screen's participant header.
 * It is not this one.)
 *
 * ## The per-sender avatar
 *
 * `-[CKUIBehaviorPhone transcriptContactImageDiameter]` is **32**, and
 * `-[CKTranscriptAvatarSupplementaryView initWithFrame:]` builds its `CKAvatarView` at exactly
 * `(0, 0, 32, 32)`, no inset. `-[CKUIBehaviorPhone contactPhotoBalloonMargin]` is **7**: it is added
 * to the diameter in `-[CKTranscriptAbstractLabelCell layoutSubviewsForContents]` (and in the
 * balloon, message and stamp cells) as `transcriptContactImageDiameter + contactPhotoBalloonMargin`
 * = **39**, the whole leading gutter an incoming row gives up in a group.
 *
 * Placement is `+[CKChatItemLayoutUtilities avatarSupplementaryItemForChatItem:layoutEnvironment:]`:
 * a square supplementary item of that diameter, anchored with
 * `[NSCollectionLayoutAnchor layoutAnchorWithEdges:6 absoluteOffset:(-32, 0)]`. Edges 6 is
 * `NSDirectionalRectEdge.leading | .bottom`, so the avatar hangs off the balloon's leading edge and
 * its **bottom lines up with the balloon's bottom** — which is why a cluster carries one avatar, on
 * its last (tailed) bubble. `+[CKChatItemLayoutUtilities balloonEdgeSpacingForItemWithLayoutEnvironment:orientation:itemSize:supplementaryItems:]`
 * then spends that same offset: leading spacing = `marginInsets.left - tailSize.width + |offset|`.
 *
 * The group typing indicator uses a bigger face:
 * `-[CKUIBehaviorPhone transcriptGroupTypingContactImageDiameter]` is 44, taken by the same
 * `avatarSupplementaryItemForChatItem:` when the item is a typing indicator. `typing-indicator.tsx`
 * does not draw one yet; the constant is exported here so it can.
 */

/** One face in the stack. Same shape `avatar.tsx` takes, plus the name used for the composed label. */
export type GroupParticipant = { name?: string; initials?: string; src?: string };

/** `{ x, y, diameter }` in the Snowglobe table's own 88-point box, centre-relative. */
export type StackSlot = { x: number; y: number; diameter: number };

/** The base box every Snowglobe configuration is expressed in (`CNUIAvatarLayoutItemConfiguration.baseSize`). */
export const snowglobeBaseSize = 88;

/** Most faces the table will draw. Participants past this many are not shown. */
export const snowglobeMaxFaces = 7;

/**
 * `SnowglobeAvatarLayoutConfigurations`, read back from
 * `+[CNUIAvatarLayoutManager layoutConfigurationsForType:2 withItemCount:n]` at a bounds of 88.
 * Index 0 is the front-most, largest face.
 */
export const snowglobeStack: readonly (readonly StackSlot[])[] = [
  [{ x: 0, y: 0, diameter: 88 }],
  [{ x: -10.5, y: -10.5, diameter: 48 }, { x: 17.5, y: 17.5, diameter: 28 }],
  [{ x: -12.5, y: -12.5, diameter: 42 }, { x: 21.5, y: 7.5, diameter: 32 }, { x: -6, y: 23.5, diameter: 26 }],
  [{ x: -12.5, y: -12.5, diameter: 42 }, { x: 21.5, y: 7.5, diameter: 32 }, { x: -6, y: 23.5, diameter: 26 }, { x: 20, y: -20.5, diameter: 20 }],
  [{ x: -12.5, y: -12.5, diameter: 42 }, { x: 21.5, y: 7.5, diameter: 32 }, { x: -6, y: 23.5, diameter: 26 }, { x: 20, y: -20.5, diameter: 20 }, { x: -27.5, y: 14, diameter: 14 }],
  [{ x: -12.5, y: -12.5, diameter: 42 }, { x: 21.5, y: 7.5, diameter: 32 }, { x: -6, y: 23.5, diameter: 26 }, { x: 20, y: -20.5, diameter: 20 }, { x: -27.5, y: 14, diameter: 14 }, { x: 7.5, y: -32.5, diameter: 10 }],
  [{ x: -12.5, y: -12.5, diameter: 42 }, { x: 19.5, y: 11.5, diameter: 30 }, { x: 21.5, y: -16.5, diameter: 22 }, { x: -21, y: 19.5, diameter: 20 }, { x: 2, y: 30, diameter: 15 }, { x: -3, y: 15, diameter: 11 }, { x: 9, y: -31.5, diameter: 10 }],
];

/** The table row for `count` faces: one through seven, then seven for anything larger. */
export function snowglobeSlots(count: number): readonly StackSlot[] {
  return snowglobeStack[Math.min(Math.max(count, 1), snowglobeMaxFaces) - 1];
}

/**
 * One slot's box inside a circle of `size`, in CSS px, mirrored for RTL exactly as
 * `-itemFrameInContainingBounds:isRTL:` does.
 */
export function snowglobeFrame(slot: StackSlot, size: number, rtl = false): { left: number; top: number; size: number } {
  const scale = size / snowglobeBaseSize;
  const face = slot.diameter * scale;
  const x = (rtl ? -slot.x : slot.x) * scale;
  return { left: size / 2 + x - face / 2, top: size / 2 + slot.y * scale - face / 2, size: face };
}

/** `-[CKUIBehaviorPhone groupAvatarViewSize]`, 60 x 60. */
export const groupAvatarSize = 60;

/**
 * Metrics for the avatar beside an incoming bubble in a group. `gutter` is what an incoming row
 * gives up on its leading side: the two are always spent together in ChatKit.
 */
export const senderAvatarMetrics = {
  /** `-[CKUIBehaviorPhone transcriptContactImageDiameter]`. */
  diameter: 32,
  /** `-[CKUIBehaviorPhone contactPhotoBalloonMargin]`, between the avatar and the balloon. */
  balloonMargin: 7,
  /** diameter + balloonMargin, the leading inset an incoming row takes in a group. */
  gutter: 39,
  /** `-[CKUIBehaviorPhone transcriptGroupTypingContactImageDiameter]`, for the typing indicator. */
  typingDiameter: 44,
} as const;

export type GroupAvatarProps = Omit<ComponentProps<"span">, "children"> & {
  /** Circle diameter. Defaults to the framework's 60. */
  size?: number;
  /** The people in the conversation, in the order the stack should draw them. */
  participants: readonly GroupParticipant[];
  /** Accessible name; falls back to the participants' names. */
  name?: string;
  /** Mirror the stack, the way `isRTL:YES` does. Defaults to the document direction. */
  rtl?: boolean;
};

/** "Alex Morgan, Jamie Chen and Sam Rivera", or "3 people" when nobody is named. */
function participantsLabel(participants: readonly GroupParticipant[]): string {
  const named = participants.map(person => person.name ?? person.initials).filter((value): value is string => Boolean(value));
  if (!named.length) return participants.length === 1 ? "1 person" : `${participants.length} people`;
  if (named.length === 1) return named[0];
  return `${named.slice(0, -1).join(", ")} and ${named[named.length - 1]}`;
}

/**
 * A group conversation's photo: the participants' avatars stacked into one circle, largest in front.
 * Draws at most seven faces, as the framework table does.
 */
export function GroupAvatar({ size = groupAvatarSize, participants, name, rtl, className, style, ...props }: GroupAvatarProps) {
  const faces = participants.slice(0, snowglobeMaxFaces);
  const slots = snowglobeSlots(faces.length || 1);
  const label = name ?? participantsLabel(participants);
  return (
    <span
      data-slot="group-avatar"
      data-size={size}
      data-count={participants.length}
      role="img"
      aria-label={label}
      dir={rtl === undefined ? undefined : rtl ? "rtl" : "ltr"}
      className={cn("relative inline-block shrink-0 select-none align-middle", className)}
      style={{ width: size, height: size, ...style }}
      {...props}
    >
      {/* An empty group still draws one circle, so the surface never collapses while a conversation loads. */}
      {(faces.length ? faces : [{}]).map((person, index) => {
        const frame = snowglobeFrame(slots[index], size, rtl);
        // setZPosition: -index. The largest face is drawn first and stays in front.
        const layer: CSSProperties = { position: "absolute", left: frame.left, top: frame.top, zIndex: faces.length - index };
        const avatar: AvatarProps = { size: frame.size, initials: person.initials, src: person.src, name: person.name };
        return <Avatar key={index} {...avatar} aria-hidden="true" role={undefined} style={layer} />;
      })}
    </span>
  );
}

export type SenderAvatarProps = Omit<ComponentProps<"span">, "children"> & {
  /** The sender's name, used as the accessible label. */
  name?: string;
  initials?: string;
  src?: string;
  /** Diameter. Defaults to the framework's 32; the group typing indicator uses 44. */
  size?: number;
};

/**
 * The Ø 32 photo beside an incoming bubble in a group. One per cluster, on the last bubble, bottom
 * aligned with the balloon: `message-list.tsx` places it.
 */
export function SenderAvatar({ name, initials, src, size = senderAvatarMetrics.diameter, className, style, ...props }: SenderAvatarProps) {
  return (
    <Avatar
      data-slot="sender-avatar"
      size={size}
      initials={initials}
      src={src}
      name={name}
      className={className}
      style={style}
      {...props}
    />
  );
}

"use client";

import { useEffect, useLayoutEffect, useMemo, useRef, useState, useSyncExternalStore, type ComponentProps, type CSSProperties } from "react";
import { cn } from "@/lib/utils";
import { usePlatform, type Platform } from "@/components/imessage/platform";
import { fontStack } from "@/components/imessage/tokens";

/**
 * Recording an audio message: the composer's field becomes a row with a live waveform, a timer and
 * the stop control, and once you stop, a play control and a send button.
 *
 * ## Where these numbers come from
 *
 * **No capture in `references/` holds this screen on either platform.** Everything geometric below
 * was instead read out of ChatKit itself, which is the framework macOS Messages runs on: a Mac
 * Catalyst probe (`clang -target arm64-apple-ios18.0-macabi`) dlopens
 * `/System/iOSSupport/System/Library/PrivateFrameworks/ChatKit.framework/ChatKit`, swizzles
 * `-[UIDevice userInterfaceIdiom]` so `+[CKUIBehavior sharedBehaviors]` vends the Phone or the Mac
 * behaviour, and then **builds the real view**: `-[CKAudioMessageRecordingView initWithFrame:service:]`
 * (a Swift class, `ChatKit.AudioMessageRecordingView`), feeds it levels through
 * `-addToWaveformWithIntensity:`, walks `-setState:` 0 to 3 and reads every subview's frame back.
 * So the frames below are the frames Messages lays out, not a reading of a screenshot and not a guess.
 *
 * Read off `CKUIBehavior` (shared by both idioms unless noted):
 *
 * | Selector | Value |
 * |---|---|
 * | `audioRecordingViewDurationSpacing` | 12, and it is the only gap the row uses |
 * | `audioRecordingViewButtonSpacing` | 16, the waveform's leading inset with no play button |
 * | `audioWaveformViewHeight` / `audioWaveformHeight` | 39 / 35 |
 * | `waveformPowerLevelWidth` / `audioWaveformGapWidth` | 2 / 2, so the bar pitch is 4 |
 * | `minimumWaveformHeight` | 4 |
 * | `audioRecordingViewTimeBetweenWaveformSegments` | 0.0833333 s, i.e. 12 bars a second |
 * | `minAudioRecordingDuration` / `maxAudioRecordingDuration` | 0.25 / 60 |
 * | `audioRecordingViewMinimumDBLevel` / `MaximumDBLevel` | -60 / -10 |
 * | `audioBalloonTimeFont` | SF Regular **13** on Phone, **16** on Mac: the timer's type |
 * | `audioMessagePeakAnimationDuration` | 0.5 |
 *
 * Read off the built view (`-[CKAudioMessageRecordingView sizeThatFits:]` and its subviews' frames,
 * Phone idiom in a 294-wide box, which is the measured width of the iOS composer field):
 *
 * - the row is **52** tall (Mac: **49**), and every child is centred in it;
 * - play/pause: a **34** circle 9 in from the leading edge (Mac: **31**), fill `#767680` at 12%,
 *   `play.fill` / `pause.fill`;
 * - stop: a **34** circle 9 in from the trailing edge (Mac: 31), fill `#FF383C` at 19%, `stop.fill`;
 * - send: `CKGlassSendButton`, **30 x 22, radius 11**, 15 in from the trailing edge (Mac: 13.5),
 *   `#0088ff` with `arrow.up`;
 * - the timer: `ChatKit.AudioMessageRecordingAppendButton`, **29.5 x 16 radius 8** while recording
 *   (Mac 35 x 19 radius 9.5) and **61 x 26 radius 13** once stopped (Mac 62.5 x 27 radius 13.5),
 *   where it also carries a `plus` and appends to the take;
 * - the waveform box: 39 tall in the 52 row and 36.75 in the Mac 49, i.e. **0.75 of the row** both
 *   times, its leading edge 16 while recording and (button + 12) once the play control is there.
 *
 * Those four layouts reproduce exactly: leading inset + parts + 12 between each + trailing inset add
 * up to the framework's own subview frames to the pixel, on both idioms and in both states.
 *
 * Bar height is **not** linear in the level: feeding known intensities and reading the segment views
 * back gives `height = level^2 * waveformHeight`, floored at the 4 above (0.111 -> 4.333, 0.222 ->
 * 7.704, 0.444 -> 17.333, 1 -> 39, all at 39 of box). The bars are 2 wide with a radius of 1.
 *
 * Colours, resolved through `-resolvedColorWithTraitCollection:` in both styles:
 * recording bars `#FF383C` light / `#FF4245` dark; played-back bars `rgba(0,0,0,0.5)` /
 * `rgba(255,255,255,0.55)` with the part that has not played yet at half that alpha; the timer red
 * while recording and 85% label ink afterwards.
 *
 * The `x` that replaces the composer's `+` is `CKGlassCancelAudioRecordingButton`: **41** across on
 * Phone and **35** on Mac, its `xmark` ink 17 x 16 centred. Each glyph outline here was traced from
 * the framework's own rendering: the probe rasterised `xmark`, `stop.fill`, `play.fill`,
 * `pause.fill`, `plus` and `arrow.up` at 17 pt (arrow Bold) at 8x and measured the ink -- stop 14
 * square with a 1.5 corner, pause two 4.25 x 14 bars 2 apart, play a 12.5 x 14 triangle, plus and
 * xmark 1.5 of stroke over 14 and 13.5, arrow 13.5 x 16 with a 2.44 stem. The arrow is the same
 * glyph the composer's send pill draws, and the two agree: 2.44 of stroke here against the 2.41
 * traced from `conv3-light.png`.
 *
 * ## What is not from the framework
 *
 * - **Where the row sits.** It reuses the composer's measured geometry so it lands on the field:
 *   iOS 28 of padding, the leading circle, a 12 gap, then the row across the field's 294 with its
 *   bottom edge on the field's (`ios-composer.tsx`); macOS the field's own left 49, width 530 and
 *   bottom 11 (`macos-composer.tsx`). The row is taller than the field it replaces (52 against
 *   40.33, 49 against 31), so it grows upward. **Judgement**: nothing says the row is centred on the
 *   field's box rather than resting on its bottom edge.
 * - **The row's corner radius**: half its height, i.e. a capsule, because both composer fields are
 *   capsules at one line (iOS 20 on 40.33, macOS 15.5 on 31, both measured). Judgement.
 * - **The row's fill**: the composer's own glass (iOS) and field fill (macOS), copied from those two
 *   files rather than imported, so this stays a registry item with no dependency on either.
 * - **The stopped pill's fill and the play glyph's ink**: reused from the play button's measured fill
 *   and the pill's own label colour. The framework builds them from a `UIBackgroundConfiguration`
 *   that resolves to nothing outside a window, so the probe could not read them. Judgement.
 * - **Playback windowing.** While recording, the newest bar's right edge is the waveform box's right
 *   edge (framework). Once stopped, the framework resamples the take to the bars that fit
 *   (`waveformMinPowerLevelsCount` 25, `waveformMaxPowerLevelsCount` 50, and the built view showed
 *   27 bars in a 109-wide box), which is what this does; that the whole take spans the box rather
 *   than scrolling under a playhead is judgement.
 * - **Motion.** The state change is the framework's own `stateChangeAnimationDuration` **0.6** and
 *   `stateChangeSpringDamping` **0.86` (Swift ivars of `AudioMessageRecordingView`, read at the
 *   constructor's trap), but the spring frequency UIKit derives from that pair is not stored
 *   anywhere, so the `linear()` easing here samples a spring settled to 0.1% at 0.6 s: judgement.
 *   The entrance and exit reuse the measured 260/200 ms and `cubic-bezier(0.32, 0.72, 0, 1)` of the
 *   iOS effects screen (`effectsPickerMetrics.timing`), which is a reuse, not a measurement of this.
 *
 * Every animation is seekable rather than merely playable: the scroll is one linear Web Animations
 * timeline whose offset is linear in time, so `progress` pauses and seeks it to a frame that renders
 * identically on every run, and the state change takes `transition={{ from, progress }}` the way
 * `MacComposer` takes `grow`. `prefers-reduced-motion` builds no timeline at all and poses the row.
 */
export const audioRecorderMetrics = {
  /** Both sets are ChatKit's, read per idiom. Points equal CSS px. */
  ios: {
    /** `-[CKAudioMessageRecordingView sizeThatFits:]`, Phone idiom. */
    rowHeight: 52,
    /** Composer geometry (`ios-composer.tsx`): the row takes the field's box and its bottom edge. */
    composer: { padding: 28, leading: 41, leadingGap: 12, fieldWidth: 294 },
    button: { size: 34, inset: 9 },
    send: { width: 30, height: 22, radius: 11, inset: 15 },
    timer: { width: 29.5, height: 16, radius: 8, fontSize: 13 },
    append: { width: 61, height: 26, radius: 13 },
    waveform: { leadingInset: 16, gap: 12, heightRatio: 0.75, barWidth: 2, barGap: 2, minBarHeight: 4 },
  },
  macos: {
    rowHeight: 49,
    /** `macos-composer.tsx`: field left 49, width 530, 11 above the pane's bottom. */
    composer: { bottom: 11, left: 49, fieldWidth: 530, leading: 35, leadingInset: 8.5 },
    button: { size: 31, inset: 9 },
    send: { width: 30, height: 22, radius: 11, inset: 13.5 },
    timer: { width: 35, height: 19, radius: 9.5, fontSize: 16 },
    append: { width: 62.5, height: 27, radius: 13.5 },
    waveform: { leadingInset: 16, gap: 12, heightRatio: 0.75, barWidth: 2, barGap: 2, minBarHeight: 4 },
  },
} as const;

/** Timings. The first four are ChatKit's; the last two are borrowed, see the note above. */
export const audioRecorderMotion = {
  /** `audioRecordingViewTimeBetweenWaveformSegments`: one bar every 83.33 ms. */
  segment: 1000 / 12,
  /** `minAudioRecordingDuration` / `maxAudioRecordingDuration`, in seconds. */
  minDuration: 0.25,
  maxDuration: 60,
  /** `AudioMessageRecordingView.stateChangeAnimationDuration` and `.stateChangeSpringDamping`. */
  stateChange: 600,
  stateChangeDamping: 0.86,
  /** Reused from the measured iOS effects screen; nothing measures this row appearing. */
  enter: 260,
  exit: 200,
  ease: "cubic-bezier(0.32, 0.72, 0, 1)",
} as const;

export type AudioRecorderState = "recording" | "stopped" | "playing";

export type AudioRecorderProps = Omit<ComponentProps<"div">, "onChange" | "children"> & {
  platform?: Platform;
  /** Which pose the row is in. */
  state?: AudioRecorderState;
  /**
   * Levels 0..1, oldest first, one per 83.33 ms segment. Leave it out for a deterministic stand-in:
   * this never touches a microphone, and a screenshot has to land on the same bars every run.
   */
  levels?: number[];
  /** Length of the take in seconds. Defaults to `levels.length / 12`. */
  duration?: number;
  /** Seconds into the take, controlled. */
  position?: number;
  /**
   * Seeks the clock to this fraction of `duration` instead of running it, which is what the harness
   * does. It also stops the internal clock, so a checkpoint is a pure function of its props.
   */
  progress?: number;
  /** Seek the state change instead of playing it, the way `MacComposer` takes `grow`. */
  transition?: { from: AudioRecorderState; progress: number };
  /** False plays the exit and then calls `onExited`. */
  open?: boolean;
  onExited?: () => void;
  onCancel?: () => void;
  onStop?: () => void;
  onSend?: () => void;
  /** The `+` inside the timer pill, which appends to the take. */
  onAppend?: () => void;
  onPlayChange?: (playing: boolean) => void;
  onSeek?: (seconds: number) => void;
  /** Width of the row. Defaults to the platform's measured composer field. */
  width?: number;
  /** Takes focus when it opens. Off by default so a seeked frame never moves the caret. */
  autoFocus?: boolean;
};

const clamp01 = (value: number) => Math.max(0, Math.min(1, value));

/** m:ss, the way the framework's own label reads ("0:00", "0:12"). */
function clock(seconds: number): string {
  const whole = Math.max(0, Math.floor(seconds));
  return `${Math.floor(whole / 60)}:${String(whole % 60).padStart(2, "0")}`;
}

/**
 * A stand-in take. Deterministic on purpose: no `Math.random` may reach a render, and the harness
 * screenshots this row. The shape is the one `message-audio.tsx` uses for its own stand-in peaks.
 */
function fallbackLevels(count: number): number[] {
  return Array.from({ length: count }, (_, i) => {
    const a = Math.sin(i * 0.7) * 0.5 + 0.5;
    const b = Math.sin(i * 1.9 + 1.1) * 0.5 + 0.5;
    return 0.35 + Math.min(1, a * 0.6 + b * 0.55) * 0.65;
  });
}

/**
 * The whole take, averaged down to the bars that fit, which is what the framework does once
 * recording stops (it holds between `waveformMinPowerLevelsCount` and `waveformMaxPowerLevelsCount`
 * levels for a balloon). Averaging, not sampling, so the summary does not flicker with the bucket.
 */
function resample(levels: number[], count: number): number[] {
  if (count <= 0) return [];
  if (levels.length === 0) return Array.from({ length: count }, () => 0);
  return Array.from({ length: count }, (_, i) => {
    const from = Math.floor((i * levels.length) / count);
    const to = Math.max(from + 1, Math.floor(((i + 1) * levels.length) / count));
    let sum = 0;
    for (let j = from; j < to; j++) sum += levels[j] ?? 0;
    return sum / (to - from);
  });
}

/**
 * A damped spring as a `linear()` easing, so the state change can be a single seekable timeline.
 * The damping ratio is the framework's 0.86; the frequency is not stored anywhere, so this picks
 * the one that settles to 0.1% exactly at the framework's 600 ms, which is a fit, not a reading.
 */
function springEasing(damping: number, steps = 24): string {
  const omega = -Math.log(0.001) / damping;
  const damped = omega * Math.sqrt(Math.max(0.0001, 1 - damping * damping));
  const points = Array.from({ length: steps + 1 }, (_, i) => {
    const t = i / steps;
    const value = 1 - Math.exp(-damping * omega * t) * (Math.cos(damped * t) + ((damping * omega) / damped) * Math.sin(damped * t));
    return `${value.toFixed(4)} ${(t * 100).toFixed(2)}%`;
  });
  return `linear(${points.join(", ")})`;
}

/**
 * Web Animations rejects an easing it cannot parse, and `linear()` needs a 2023 engine, so a browser
 * without it falls back to the measured decelerating curve rather than losing the animation.
 */
function animateWithSpring(element: Element, frames: Keyframe[], duration: number, easing: string): Animation {
  try {
    return element.animate(frames, { duration, easing });
  } catch {
    return element.animate(frames, { duration, easing: audioRecorderMotion.ease });
  }
}

const reducedMotionQuery = () => (typeof window === "undefined" ? null : window.matchMedia?.("(prefers-reduced-motion: reduce)") ?? null);
function subscribeReducedMotion(onChange: () => void) {
  const query = reducedMotionQuery();
  query?.addEventListener("change", onChange);
  return () => query?.removeEventListener("change", onChange);
}
/** True when the viewer asked for less motion; false while server rendering. Its own copy, as in `macos-composer.tsx`. */
function usePrefersReducedMotion() {
  return useSyncExternalStore(subscribeReducedMotion, () => reducedMotionQuery()?.matches ?? false, () => false);
}

/* Glyphs. Every box below is the ink the framework's own 17 pt symbol renders at 8x, measured. */

/** `xmark`, ink 13.5 square, 1.5 of stroke with round caps. */
function XmarkGlyph({ size = 13.5 }: { size?: number }) {
  return (
    <svg aria-hidden="true" width={size} height={size} viewBox="0 0 13.5 13.5" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round">
      <path d="M0.75 0.75 12.75 12.75M12.75 0.75 0.75 12.75" />
    </svg>
  );
}

/** `stop.fill`, a 14 square with a 1.5 corner (fitted to the rendered coverage at two depths). */
function StopGlyph() {
  return (
    <svg aria-hidden="true" width="14" height="14" viewBox="0 0 14 14" fill="currentColor">
      <rect x="0" y="0" width="14" height="14" rx="1.5" />
    </svg>
  );
}

/** `play.fill`, ink 12.5 x 14, its corners rounded by ~1.3 (the stroke rounds the joins). */
function PlayGlyph() {
  return (
    <svg aria-hidden="true" width="12.5" height="14" viewBox="0 0 12.5 14" fill="currentColor" stroke="currentColor" strokeWidth="1.3" strokeLinejoin="round">
      <path d="M0.65 0.9 11.2 7 0.65 13.1Z" />
    </svg>
  );
}

/** `pause.fill`, two 4.25 x 14 bars 2 apart, corner ~1.2. */
function PauseGlyph() {
  return (
    <svg aria-hidden="true" width="10.5" height="14" viewBox="0 0 10.5 14" fill="currentColor">
      <rect x="0" y="0" width="4.25" height="14" rx="1.2" />
      <rect x="6.25" y="0" width="4.25" height="14" rx="1.2" />
    </svg>
  );
}

/** `plus`, 14 across each way at 1.5 of stroke. */
function PlusGlyph() {
  return (
    <svg aria-hidden="true" width="14" height="14" viewBox="0 0 14 14" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round">
      <path d="M0.75 7H13.25M7 0.75V13.25" />
    </svg>
  );
}

/** `arrow.up` Bold, ink 13.5 x 16: 2.44 of stem, arms 5.28 across per 5.88 down. */
function ArrowUpGlyph() {
  return (
    <svg aria-hidden="true" width="13.5" height="16" viewBox="0 0 13.5 16" fill="none" stroke="currentColor" strokeWidth="2.44" strokeLinecap="round" strokeLinejoin="round">
      <path d="M1.47 7.1 6.75 1.22 12.03 7.1M6.75 1.22V14.78" />
    </svg>
  );
}

const vars =
  // iOS glass, copied from `ios-composer.tsx` (measured), and the framework's own recording colours.
  "[--ar-glass:rgba(255,255,255,0.9)] [--ar-rim:none] [--ar-shadow:0_6px_36px_4px_rgba(0,0,0,0.065)] [--ar-round-shadow:0_5px_20px_6px_rgba(0,0,0,0.055)] " +
  "[--ar-red:#ff383c] [--ar-ink:rgba(0,0,0,0.85)] [--ar-glyph:#1a1919] [--ar-wave:rgba(0,0,0,0.5)] [--ar-fill:rgba(118,118,128,0.12)] " +
  "dark:[--ar-glass:rgba(28,28,28,0.9)] dark:[--ar-rim:inset_0_0_0_1px_rgba(255,255,255,0.09)] dark:[--ar-shadow:none] dark:[--ar-round-shadow:none] " +
  "dark:[--ar-red:#ff4245] dark:[--ar-ink:rgba(255,255,255,0.85)] dark:[--ar-glyph:#f4f3f4] dark:[--ar-wave:rgba(255,255,255,0.55)]";

const macVars =
  // macOS field fill, rim and shadow, copied from `macos-composer.tsx` (measured).
  "[--ar-glass:#ffffff] [--ar-rim:none] [--ar-shadow:0_5px_25px_rgba(0,0,0,0.07)] [--ar-round-shadow:0_5px_25px_rgba(0,0,0,0.07)] [--ar-glyph:#010101] " +
  "dark:[--ar-glass:#232323] dark:[--ar-rim:inset_0.774px_0.774px_0_0_#424242,inset_-0.774px_-0.774px_0_0_#424242] dark:[--ar-shadow:0_5px_25px_rgba(0,0,0,0.05)] dark:[--ar-round-shadow:0_5px_25px_rgba(0,0,0,0.05)] dark:[--ar-glyph:#f1f1f1]";

type Geometry = {
  waveLeft: number;
  waveRight: number;
  timerRight: number;
  timerWidth: number;
  timerHeight: number;
  timerRadius: number;
  stop: number;
  send: number;
  play: number;
};

export function AudioRecorder({
  platform: platformProp,
  state = "recording",
  levels,
  duration: durationProp,
  position: positionProp,
  progress,
  transition,
  open = true,
  onExited,
  onCancel,
  onStop,
  onSend,
  onAppend,
  onPlayChange,
  onSeek,
  width,
  autoFocus = false,
  className,
  style,
  ...props
}: AudioRecorderProps) {
  const contextPlatform = usePlatform();
  const platform = platformProp ?? contextPlatform;
  const ios = platform === "ios";
  const m = audioRecorderMetrics[platform];
  const motion = audioRecorderMotion;
  const reduced = usePrefersReducedMotion();

  const rowWidth = width ?? m.composer.fieldWidth;
  const take = useMemo(() => (levels?.length ? levels : fallbackLevels(60)), [levels]);
  const duration = durationProp ?? take.length / 12;
  const recording = state === "recording";

  const root = useRef<HTMLDivElement>(null);
  const strip = useRef<HTMLDivElement>(null);
  const waveBox = useRef<HTMLDivElement>(null);
  const timerBox = useRef<HTMLDivElement>(null);
  const stopButton = useRef<HTMLButtonElement>(null);
  const sendButton = useRef<HTMLButtonElement>(null);
  const playButton = useRef<HTMLButtonElement>(null);
  const laidOut = useRef<AudioRecorderState | null>(null);
  const exited = useRef(false);
  /** The callback lives in a ref so an inline arrow cannot restart the exit it just reported. */
  const exitedCallback = useRef(onExited);
  useEffect(() => {
    exitedCallback.current = onExited;
  });

  /**
   * The clock, for a caller that passes neither a position nor a seek. The elapsed time is stamped
   * with the run it belongs to, so a new run reads as zero during render instead of needing the
   * effect to write zero into state before the first tick lands.
   */
  const live = progress === undefined && positionProp === undefined;
  const run = `${live}|${open}|${state}`;
  const [tick, setTick] = useState({ run: "", seconds: 0 });
  const ticking = tick.run === run ? tick.seconds : 0;
  useEffect(() => {
    if (!live || !open) return;
    if (state !== "recording" && state !== "playing") return;
    const started = performance.now();
    const id = window.setInterval(() => {
      const seconds = (performance.now() - started) / 1000;
      setTick({ run, seconds: Math.min(seconds, duration) });
    }, motion.segment);
    return () => window.clearInterval(id);
  }, [live, open, state, duration, motion.segment, run]);

  const position = Math.max(0, Math.min(duration, positionProp ?? (progress !== undefined ? clamp01(progress) * duration : ticking)));

  const geometry = useMemo(() => {
    const build = (which: AudioRecorderState): Geometry => {
      const isRecording = which === "recording";
      const trailing = isRecording ? m.button.inset + m.button.size : m.send.inset + m.send.width;
      const timerWidth = isRecording ? m.timer.width : m.append.width;
      return {
        waveLeft: isRecording ? m.waveform.leadingInset : m.button.inset + m.button.size + m.waveform.gap,
        waveRight: trailing + m.waveform.gap + timerWidth + m.waveform.gap,
        timerRight: trailing + m.waveform.gap,
        timerWidth,
        timerHeight: isRecording ? m.timer.height : m.append.height,
        timerRadius: isRecording ? m.timer.radius : m.append.radius,
        stop: isRecording ? 1 : 0,
        send: isRecording ? 0 : 1,
        play: isRecording ? 0 : 1,
      };
    };
    return { recording: build("recording"), stopped: build("stopped"), playing: build("playing") };
  }, [m]);

  const pose = geometry[state];
  const waveWidth = Math.max(0, rowWidth - pose.waveLeft - pose.waveRight);
  const waveHeight = m.rowHeight * m.waveform.heightRatio;
  const pitch = m.waveform.barWidth + m.waveform.barGap;

  /**
   * While recording the strip carries the whole take and scrolls under the box's right edge, so the
   * bar for "now" is always flush with it and the ones still to come are clipped. Once it stops, the
   * take is averaged down to the bars that fit and the whole of it is in view.
   */
  const bars = recording ? take : resample(take, Math.max(1, Math.floor((waveWidth + m.waveform.barGap) / pitch)));
  const played = duration > 0 ? position / duration : 0;
  const stripOffset = (take.length - 1) * pitch;

  /**
   * The scroll. One linear timeline: the offset is `(N - 1) * pitch - 48 * t`, which is linear in
   * time because the framework adds a bar every 83.33 ms at a pitch of 4. That makes it seekable to
   * an exact frame, and it needs no measurement of the box, since the strip hangs off its right edge.
   */
  useLayoutEffect(() => {
    const element = strip.current;
    if (!element || !recording) return;
    const total = duration * 1000;
    const to = stripOffset - (total / motion.segment) * pitch;
    if (reduced || total <= 0) {
      const at = stripOffset - (position * 1000 / motion.segment) * pitch;
      element.style.transform = `translateX(${at}px)`;
      return () => { element.style.transform = ""; };
    }
    const animation = element.animate(
      [{ transform: `translateX(${stripOffset}px)` }, { transform: `translateX(${to}px)` }],
      { duration: total, easing: "linear", fill: "both" },
    );
    if (progress !== undefined || positionProp !== undefined) {
      // Seeked, not played: a scrubbed checkpoint has to land on the same frame every run.
      animation.pause();
      animation.currentTime = Math.max(0, Math.min(total, position * 1000));
    }
    return () => animation.cancel();
  }, [recording, duration, stripOffset, pitch, position, progress, positionProp, reduced, motion.segment]);

  /**
   * The state change. It is a transient override of the layout the render already put in place (no
   * `fill`), so the end of it is the settled row rather than a copy of it, and `transition` seeks it
   * instead of playing it. Which direction it runs is read from the props during render.
   */
  const transitionFrom = transition?.from;
  const transitionProgress = transition?.progress;
  useLayoutEffect(() => {
    const from = transitionFrom ?? laidOut.current;
    laidOut.current = state;
    if (from === null || from === undefined || from === state || reduced) return;
    const a = geometry[from];
    const b = geometry[state];
    const easing = springEasing(motion.stateChangeDamping);
    const animations: Animation[] = [];
    const move = (element: Element | null, frames: Keyframe[]) => {
      if (element) animations.push(animateWithSpring(element, frames, motion.stateChange, easing));
    };
    move(waveBox.current, [{ left: `${a.waveLeft}px`, right: `${a.waveRight}px` }, { left: `${b.waveLeft}px`, right: `${b.waveRight}px` }]);
    move(timerBox.current, [
      { right: `${a.timerRight}px`, width: `${a.timerWidth}px`, height: `${a.timerHeight}px`, borderRadius: `${a.timerRadius}px` },
      { right: `${b.timerRight}px`, width: `${b.timerWidth}px`, height: `${b.timerHeight}px`, borderRadius: `${b.timerRadius}px` },
    ]);
    move(stopButton.current, [{ opacity: a.stop }, { opacity: b.stop }]);
    move(sendButton.current, [{ opacity: a.send }, { opacity: b.send }]);
    move(playButton.current, [{ opacity: a.play }, { opacity: b.play }]);
    if (transitionProgress !== undefined) {
      const at = clamp01(transitionProgress) * motion.stateChange;
      for (const animation of animations) {
        animation.pause();
        animation.currentTime = at;
      }
    }
    return () => { for (const animation of animations) animation.cancel(); };
  }, [state, transitionFrom, transitionProgress, geometry, reduced, motion.stateChange, motion.stateChangeDamping]);

  /**
   * Entrance and exit, one timeline run forwards or backwards. `open` is read during render, so the
   * closing pose gets its committed frames before `onExited` lets the caller unmount the row.
   */
  useEffect(() => {
    const element = root.current;
    if (!element) return;
    if (open) exited.current = false;
    const closing = !open;
    const finish = () => {
      if (exited.current) return;
      exited.current = true;
      exitedCallback.current?.();
    };
    // Scrubbing is inspection, not a dismissal: a seeked exit poses the row and reports nothing.
    const reports = closing && progress === undefined;
    if (reduced) {
      element.style.opacity = closing ? "0" : "";
      if (!reports) return;
      const frame = requestAnimationFrame(finish);
      return () => cancelAnimationFrame(frame);
    }
    const away = { opacity: 0, transform: "scale(0.97)" };
    const settled = { opacity: 1, transform: "scale(1)" };
    const animation = element.animate(closing ? [settled, away] : [away, settled], {
      duration: closing ? motion.exit : motion.enter,
      easing: closing ? "ease-out" : motion.ease,
      fill: "both",
    });
    if (progress !== undefined) {
      animation.pause();
      animation.currentTime = closing ? motion.exit : motion.enter;
      return () => animation.cancel();
    }
    if (!closing) return () => animation.cancel();
    animation.addEventListener("finish", finish);
    return () => animation.removeEventListener("finish", finish);
  }, [open, progress, reduced, motion.enter, motion.exit, motion.ease]);

  useEffect(() => {
    if (!autoFocus || !open || progress !== undefined) return;
    (recording ? stopButton.current : playButton.current)?.focus({ preventScroll: true });
  }, [autoFocus, open, progress, recording]);

  const seek = (clientX: number) => {
    const element = waveBox.current;
    if (!element || !onSeek || recording) return;
    const rect = element.getBoundingClientRect();
    onSeek(clamp01((clientX - rect.left) / rect.width) * duration);
  };

  const timeText = recording || state === "playing" ? clock(position) : clock(duration);
  const circle = "absolute flex items-center justify-center rounded-full focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#0088ff]";

  const row = (
    <div
      data-slot="recording-row"
      className="relative select-none"
      style={{
        width: rowWidth,
        height: m.rowHeight,
        borderRadius: m.rowHeight / 2,
        background: "var(--ar-glass)",
        boxShadow: "var(--ar-rim), var(--ar-shadow)",
        backdropFilter: ios ? "blur(24px)" : undefined,
        WebkitBackdropFilter: ios ? "blur(24px)" : undefined,
      }}
    >
      <button
        ref={playButton}
        type="button"
        data-slot="play"
        aria-label={state === "playing" ? "Pause audio message" : "Play audio message"}
        aria-pressed={state === "playing"}
        aria-hidden={recording}
        tabIndex={recording ? -1 : undefined}
        onClick={() => onPlayChange?.(state !== "playing")}
        className={circle}
        style={{
          left: m.button.inset, top: (m.rowHeight - m.button.size) / 2, width: m.button.size, height: m.button.size,
          background: "var(--ar-fill)", color: "var(--ar-ink)", opacity: pose.play, pointerEvents: recording ? "none" : undefined,
        }}
      >
        {state === "playing" ? <PauseGlyph /> : <PlayGlyph />}
      </button>

      <div
        ref={waveBox}
        data-slot="waveform"
        role={recording ? undefined : "slider"}
        aria-hidden={recording || undefined}
        tabIndex={recording ? undefined : 0}
        aria-label={recording ? undefined : "Playback position"}
        aria-valuemin={recording ? undefined : 0}
        aria-valuemax={recording ? undefined : Math.round(duration)}
        aria-valuenow={recording ? undefined : Math.round(position)}
        aria-valuetext={recording ? undefined : clock(position)}
        onPointerDown={event => { if (!recording && onSeek) { event.currentTarget.setPointerCapture(event.pointerId); seek(event.clientX); } }}
        onPointerMove={event => { if (event.buttons === 1) seek(event.clientX); }}
        onKeyDown={event => {
          if (recording || !onSeek) return;
          if (event.key === "ArrowRight") { event.preventDefault(); onSeek(Math.min(duration, position + 1)); }
          if (event.key === "ArrowLeft") { event.preventDefault(); onSeek(Math.max(0, position - 1)); }
        }}
        className="absolute overflow-hidden focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#0088ff]"
        style={{ left: pose.waveLeft, right: pose.waveRight, top: (m.rowHeight - waveHeight) / 2, height: waveHeight }}
      >
        {/* Anchored to the box's trailing edge: while recording, the newest bar's right edge is that
            edge and the rest of the take is clipped to its right until the scroll brings it in. */}
        <div
          ref={strip}
          data-slot="waveform-bars"
          className="absolute flex items-center"
          style={{ right: 0, top: 0, height: waveHeight, gap: m.waveform.barGap, transform: recording ? `translateX(${stripOffset}px)` : undefined }}
        >
          {bars.map((level, index) => {
            const reached = recording || (bars.length > 0 && index / bars.length < played);
            return (
              <span
                key={index}
                aria-hidden="true"
                style={{
                  width: m.waveform.barWidth,
                  height: Math.max(m.waveform.minBarHeight, level * level * waveHeight),
                  borderRadius: m.waveform.barWidth / 2,
                  background: recording ? "var(--ar-red)" : "var(--ar-wave)",
                  opacity: reached ? 1 : 0.5,
                }}
              />
            );
          })}
        </div>
      </div>

      <div
        ref={timerBox}
        data-slot="timer"
        className="absolute flex items-center justify-center"
        style={{
          right: pose.timerRight, top: (m.rowHeight - pose.timerHeight) / 2, width: pose.timerWidth, height: pose.timerHeight,
          borderRadius: pose.timerRadius, background: recording ? "transparent" : "var(--ar-fill)",
          gap: 4, fontFamily: fontStack, fontSize: m.timer.fontSize, color: recording ? "var(--ar-red)" : "var(--ar-ink)",
          fontVariantNumeric: "tabular-nums", whiteSpace: "nowrap",
        }}
      >
        {!recording && onAppend ? (
          <button type="button" data-slot="append" aria-label="Record more" onClick={onAppend}
            className="flex items-center justify-center rounded-full focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#0088ff]"
            style={{ width: 11.5, height: 11.5, color: "inherit" }}>
            <PlusGlyph />
          </button>
        ) : null}
        <span role="timer" aria-label={recording ? "Recording time" : "Audio message length"}>{timeText}</span>
      </div>

      <button
        ref={stopButton}
        type="button"
        data-slot="stop"
        aria-label="Stop recording"
        aria-hidden={!recording}
        tabIndex={recording ? undefined : -1}
        onClick={onStop}
        className={circle}
        style={{
          right: m.button.inset, top: (m.rowHeight - m.button.size) / 2, width: m.button.size, height: m.button.size,
          background: "color-mix(in srgb, var(--ar-red) 19%, transparent)", color: "var(--ar-red)",
          opacity: pose.stop, pointerEvents: recording ? undefined : "none",
        }}
      >
        <StopGlyph />
      </button>

      <button
        ref={sendButton}
        type="button"
        data-slot="send"
        aria-label="Send audio message"
        aria-hidden={recording}
        tabIndex={recording ? -1 : undefined}
        onClick={onSend}
        className="absolute flex items-center justify-center focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#0088ff]"
        style={{
          right: m.send.inset, top: (m.rowHeight - m.send.height) / 2, width: m.send.width, height: m.send.height,
          borderRadius: m.send.radius, background: "#0088ff", color: "#ffffff",
          opacity: pose.send, pointerEvents: recording ? "none" : undefined,
        }}
      >
        <ArrowUpGlyph />
      </button>
    </div>
  );

  const cancel = (
    <button
      type="button"
      data-slot="cancel"
      aria-label="Cancel audio message"
      onClick={onCancel}
      className="flex shrink-0 items-center justify-center rounded-full focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#0088ff]"
      style={{
        width: ios ? audioRecorderMetrics.ios.composer.leading : audioRecorderMetrics.macos.composer.leading,
        height: ios ? audioRecorderMetrics.ios.composer.leading : audioRecorderMetrics.macos.composer.leading,
        background: "var(--ar-glass)", boxShadow: "var(--ar-rim), var(--ar-round-shadow)", color: "var(--ar-glyph)",
        backdropFilter: ios ? "blur(24px)" : undefined, WebkitBackdropFilter: ios ? "blur(24px)" : undefined,
      }}
    >
      <XmarkGlyph />
    </button>
  );

  if (!ios) {
    const mac = audioRecorderMetrics.macos;
    return (
      <div
        ref={root}
        data-slot="audio-recorder"
        data-state={state}
        data-platform="macos"
        role="group"
        aria-label="Audio message"
        className={cn("absolute inset-x-0 bottom-0 select-none", macVars, className)}
        style={{ height: mac.composer.bottom + mac.rowHeight + 10, fontFamily: fontStack, ...style }}
        {...props}
      >
        <div className="absolute" style={{ left: mac.composer.leadingInset, bottom: mac.composer.bottom }}>{cancel}</div>
        <div className="absolute" style={{ left: mac.composer.left, bottom: mac.composer.bottom }}>{row}</div>
      </div>
    );
  }

  const composer = audioRecorderMetrics.ios.composer;
  return (
    <div
      ref={root}
      data-slot="audio-recorder"
      data-state={state}
      data-platform="ios"
      role="group"
      aria-label="Audio message"
      className={cn("relative isolate flex w-full items-end select-none", vars, className)}
      style={{ padding: `0 ${composer.padding}px ${composer.padding}px ${composer.padding}px`, fontFamily: fontStack, ...style } as CSSProperties}
      {...props}
    >
      {cancel}
      <div style={{ marginLeft: composer.leadingGap }}>{row}</div>
    </div>
  );
}
